(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,56420,70326,e=>{"use strict";var t=e.i(71645),n=e.i(5014);e.s(["f",0,function(e,i=[],s=[]){let a,r="string"==typeof e?function(e,t,n=[]){if(null==t)throw Error("[lucide]: iconNode is required when icon name is used");return{name:e?.replace(/([a-z0-9])([A-Z])/g,"$1-$2").toLowerCase(),size:24,node:t,...n.length>0?{aliases:n}:{}}}(e,i,s):e,o=(0,t.forwardRef)(({className:e,...i},s)=>(0,t.createElement)(n.default,{ref:s,icon:r,className:e,...i}));return r.name&&(o.displayName=(a=(e=>{let t="",n=!1;for(let i of e){if("-"===i||"_"===i||i<=" "){n=t.length>0;continue}0===t.length?t+=i.toLowerCase():t+=n?i.toUpperCase():i,n=!1}return t})(r.name)).charAt(0).toUpperCase()+a.slice(1)),o}],56420);var i=e.i(45260);let s={1:[1,2],2:[3,4],3:[5,6],4:[7,8],5:[9,9],6:[11,12],7:[13,14],8:[15,15],9:[16,17],10:[19,20],11:[21,22],12:[23,23],13:[25,25],14:[26,27],15:[28,29],16:[30,31],17:[33,34],18:[35,35],19:[37,37],20:[38,39],21:[40,41],22:[42,43],23:[45,46],24:[47,47],25:[48,49],26:[51,51],27:[52,53],28:[54,54]},a={1:4,2:10,3:18,4:24,5:32,6:36,7:44,8:50,9:55},r=i.default.map(e=>{let t=s[e.n];if(!t)throw Error(`pacing.ts has no days for chapter ${e.n}`);return{...e,days:t,meta:e.meta.map(e=>"Days"===e.label?{...e,value:(([e,t])=>e===t?`Day ${e}`:`${e}–${t}`)(t)}:e)}}),o=e=>`/${e}`,l=[{n:1,roman:"I",name:"Foundation Keep",icon:"🏰",color:"#38BFFF",chapters:[1,2],badge:"Wellness Apprentice",desc:"What health really means, how to make smart decisions, and the skills that power the entire quest."},{n:2,roman:"II",name:"Mind Citadel",icon:"🧠",color:"#A855F7",chapters:[3,5],badge:"Mind Knight",desc:"Mental health, stress, resilience, and knowing when and how to get help — for yourself and others."},{n:3,roman:"III",name:"Relationship Realm",icon:"💞",color:"#FF3B5C",chapters:[6,9],badge:"Social Champion",desc:"Friendships, family, conflict resolution, and violence prevention — the social side of health."},{n:4,roman:"IV",name:"Nourish Dungeon",icon:"🥗",color:"#00E5A0",chapters:[10,12],badge:"Body Warrior",desc:"Nutrition science, healthy weight, body image, and the fitness plan to fuel your body right."},{n:5,roman:"V",name:"Body Labyrinth",icon:"⚙️",color:"#FF8C00",chapters:[13,16],badge:"System Sage",desc:"Skin to skeleton to hormones — mapping the inner architecture of the human body."},{n:6,roman:"VI",name:"Life Cycle Shrine",icon:"🌱",color:"#2DD4BF",chapters:[17,18],badge:"Life Keeper",desc:"From a single cell to late adulthood — genetics, prenatal development, and the complete life cycle."},{n:7,roman:"VII",name:"Shadow World",icon:"💀",color:"#F43F5E",chapters:[19,22],badge:"Shadow Slayer",desc:"Medicines, tobacco, alcohol, and the fentanyl crisis that changed the risk landscape for every teen."},{n:8,roman:"VIII",name:"Disease Fortress",icon:"🏥",color:"#94A3B8",chapters:[23,25],badge:"Health Guardian",desc:"Communicable diseases, STIs, HIV, cancer, cardiovascular disease, and diabetes — fully updated."},{n:9,roman:"IX",name:"The Final Tower",icon:"★",color:"#FFD700",chapters:[26,28],badge:"Master of Wellness",desc:"Safety, CPR, first aid, emergency preparedness, and community health — the ultimate capstone."}].map(e=>{let t=function(e,[t,n]){let i=r.filter(e=>e.n>=t&&e.n<=n),s=Math.min(...i.map(e=>e.days[0])),o=Math.max(...i.map(e=>e.days[1])),l=a[e];if(l<o)throw Error(`Realm ${e} Boss Day ${l} falls before its last lesson day ${o}`);return[s,l]}(e.n,e.chapters);return{...e,dayRange:t,days:(([e,t])=>e===t?`Day ${e}`:`Days ${e}–${t}`)(t)}});o("side_quests.html"),o("pick_a_side.html"),o("ask.html"),o("live.html"),o("pet.html"),o("mastery.html"),o("checklist.html"),o("leaderboard.html");let c=[{label:"Home",href:"/"},{label:"Chapters",href:"/chapters"},{label:"Realms",href:"/realms"},{label:"Arcade",href:"/arcade"},{label:"Quest",href:o("quest.html")},{label:"My Sprite",href:o("pet.html")},{label:"Hall",href:o("leaderboard.html")}];e.s(["S",0,{1:["Wellness","Lifestyle"],2:["Life Skills","Goals"],3:["Mental Health","Emotions"],4:["Stress","Coping"],5:["Disorders","Support"],6:["Relationships","Communication"],7:["Family","Getting Help"],8:["Friendship","Peer Pressure"],9:["Conflict","Safety"],10:["Nutrition","MyPlate"],11:["Weight","Body Image"],12:["Fitness","Exercise"],13:["Skin","Teeth","Eyes"],14:["Body Systems","Anatomy"],15:["Heart","Lungs","Digestion"],16:["Hormones","Puberty"],17:["Prenatal","Genetics"],18:["Adolescence","Aging"],19:["Medicines","Safety"],20:["Tobacco","Vaping"],21:["Alcohol","Risk"],22:["Drugs","Fentanyl"],23:["Viruses","Bacteria"],24:["STIs","Prevention"],25:["Cancer","Diabetes"],26:["Safety","Cyberbullying"],27:["CPR","First Aid"],28:["Community","Environment"]},"d",0,r,"z",0,o,"r",0,e=>/\.(html|pdf)([?#]|$)/i.test(e),"o",0,c,"p",0,e=>l.find(t=>e>=t.chapters[0]&&e<=t.chapters[1]),"R",0,l],70326)},45260,(e,t,n)=>{t.exports=JSON.parse('[{"n":1,"realmTag":"Realm I — Foundation Keep","title":"Understanding Health & Wellness","sub":"Your health is more than just feeling sick or not — it\'s the complete picture of your physical, mental, emotional, and social well-being. This chapter is your foundation for everything that follows.","meta":[{"icon":"📅","label":"Days","value":"1–4"},{"icon":"📖","label":"Lessons","value":"4"},{"icon":"🏆","label":"Realm Badge","value":"Wellness Apprentice"},{"icon":"⚔","label":"Boss Battle","value":"Health Jeopardy"}],"lessons":["L1: What is Health?","L2: The Health Triangle","L3: Building Health Literacy","L4: Influencing Your Health"],"pdf":"/Chapter_01_Understanding_Health_and_Wellness.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Your Total Health</h3>\\r\\n              <h4>What Is Health?</h4>\\r\\n              <p>Health is not just about your body. It is a combination of many different areas of well-being that all work together. Think of it less like a triangle and more like a web. When one area is struggling, the others feel it too.</p>\\r\\n\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <div class=\\"callout-label\\">Key Idea</div>\\r\\n                <div>When these areas are in balance, you experience true wellness: functioning at your best. Neglect one area too long and it starts pulling the others down.</div>\\r\\n              </div>\\r\\n\\r\\n              <h4>The Many Dimensions of Health</h4>\\r\\n              <div class=\\"reading-grid compact\\">\\r\\n                <div class=\\"reading-tile\\"><h3>Physical</h3><p>How well your body functions day to day. Sleep 8-10 hours, eat well, move at least 60 minutes a day, and skip tobacco and drugs.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Mental</h3><p>How you think and process the world, including your ability to learn, decide, and handle challenges.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Emotional</h3><p>How you recognize, express, and manage feelings, including bouncing back from setbacks.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Social</h3><p>How you connect with others through supportive relationships built on respect and trust.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Spiritual</h3><p>A deep sense of meaning, purpose, and values: feeling that your life matters.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Financial</h3><p>Managing money in a way that reduces stress, one of the hidden drivers of poor health.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Environmental</h3><p>The health of the spaces around you, including clean air, safe neighborhoods, and access to green spaces.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Cultural</h3><p>Connection to your cultural identity, traditions, and community.</p></div>\\r\\n              </div>\\r\\n\\r\\n              <h4>The Health Continuum</h4>\\r\\n              <p>Think of your health like a sliding scale, from premature death on one end to feeling your absolute best on the other. Every choice moves you one direction. Many Americans drift lower because of chronic diseases such as heart disease, obesity, and cancer. Many of these conditions are preventable with better daily habits.</p>\\r\\n            </section>\\r\\n\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — What Affects Your Health?</h3>\\r\\n              <p>Lots of things shape your health that you may not even think about. You cannot control everything, but understanding these influences helps you make smarter choices.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Heredity:</strong> Traits passed biologically from your parents. You cannot change your genes, but you can change how you respond to them.</li>\\r\\n                <li><strong>Environment:</strong> Your surroundings, from air quality to access to doctors. Family, friends, and peers influence your choices too.</li>\\r\\n                <li><strong>Culture:</strong> Beliefs, customs, and behaviors of your group shape everything from food to spiritual practices.</li>\\r\\n                <li><strong>Attitude:</strong> Optimists tend to actually be healthier. A positive mindset is a real health move.</li>\\r\\n                <li><strong>Media and Technology:</strong> Media constantly pushes ideas about health and lifestyle, but not all of it is accurate. Stick to .gov or .edu sites and trusted organizations like the CDC.</li>\\r\\n              </ul>\\r\\n            </section>\\r\\n\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Health Risks and Your Behavior</h3>\\r\\n              <h4>The CDC\'s 6 Top Risk Behaviors for People Under 24</h4>\\r\\n              <ol class=\\"reader-list\\">\\r\\n                <li>Tobacco use</li>\\r\\n                <li>Poor eating habits</li>\\r\\n                <li>Not enough physical activity</li>\\r\\n                <li>Alcohol and drug use</li>\\r\\n                <li>Risky sexual behavior</li>\\r\\n                <li>Violence and unintentional injuries</li>\\r\\n              </ol>\\r\\n              <p>Risk behaviors can threaten your health or the health of others. They build through cumulative risks. The more risks you stack, the worse the consequences. Speeding is risky. Texting while speeding is way more dangerous.</p>\\r\\n\\r\\n              <h4>How to Protect Yourself</h4>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><h3>Prevention</h3><p>Regular checkups, wearing a seatbelt, and using sunscreen are steps that keep health problems from happening or getting worse.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Abstinence</h3><p>A deliberate decision to avoid high-risk behaviors including tobacco, alcohol, drugs, and sexual activity that could harm you.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Lifestyle Factors</h3><p>Everyday personal habits such as sleep, nutrition, physical activity, and avoiding substances all shape long-term health.</p></div>\\r\\n              </div>\\r\\n            </section>\\r\\n\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Promoting Health and Wellness</h3>\\r\\n              <p>The United States spends more per person on health care than any other country, and a huge chunk of that cost could be avoided if more people had solid health education: accurate information and the skills to act on it.</p>\\r\\n\\r\\n              <h4>Healthy People 2030</h4>\\r\\n              <p>Healthy People 2030 sets national health goals every decade. Key priorities include helping all Americans live healthier, longer lives and closing health disparities. Health disparities are gaps in health outcomes across groups based on race, gender, income, location, or disability. Everyone deserves a fair shot at good health.</p>\\r\\n\\r\\n              <h4>Health Literacy</h4>\\r\\n              <p>Health literacy is your ability to find, understand, and use health information. It matters more than age, income, or education level when it comes to your overall health.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Thinks critically before believing health claims</li>\\r\\n                <li>Knows how to find reliable sources</li>\\r\\n                <li>Makes decisions good for themselves and their community</li>\\r\\n                <li>Can communicate health information clearly to others</li>\\r\\n              </ul>\\r\\n\\r\\n              <div class=\\"reading-check\\">\\r\\n                <strong>Course Goal</strong>\\r\\n                <span>This course helps you become someone who takes charge of your own health with knowledge, confidence, and good judgment.</span>\\r\\n              </div>\\r\\n            </section>\\r\\n\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Health</strong><span>The combination of many areas of well-being, including physical, mental, emotional, social, spiritual, financial, environmental, and cultural health.</span></div>\\r\\n                <div><strong>Spiritual health</strong><span>A deep-seated sense of meaning and purpose in life.</span></div>\\r\\n                <div><strong>Wellness</strong><span>An overall state of well-being or total health.</span></div>\\r\\n                <div><strong>Chronic disease</strong><span>An ongoing condition or illness such as heart disease, obesity, or cancer.</span></div>\\r\\n                <div><strong>Heredity</strong><span>All the traits biologically passed on to you from your parents.</span></div>\\r\\n                <div><strong>Environment</strong><span>The sum of your surroundings, including physical places and the people in your world.</span></div>\\r\\n                <div><strong>Peers</strong><span>People of the same age who share similar interests.</span></div>\\r\\n                <div><strong>Culture</strong><span>The collective beliefs, customs, and behaviors of a group.</span></div>\\r\\n                <div><strong>Media</strong><span>The various methods for communicating information.</span></div>\\r\\n                <div><strong>Technology</strong><span>The tools and methods used to deliver media content.</span></div>\\r\\n                <div><strong>Risk behaviors</strong><span>Actions that can potentially threaten your health or the health of others.</span></div>\\r\\n                <div><strong>Cumulative risks</strong><span>Related risks that increase in effect with each added risk.</span></div>\\r\\n                <div><strong>Prevention</strong><span>Taking steps to keep something from happening or getting worse.</span></div>\\r\\n                <div><strong>Abstinence</strong><span>A deliberate decision to avoid high-risk behaviors.</span></div>\\r\\n                <div><strong>Lifestyle factors</strong><span>Personal habits or behaviors related to the way a person lives.</span></div>\\r\\n                <div><strong>Health education</strong><span>Providing accurate health information and teaching health skills to help people make healthy decisions.</span></div>\\r\\n                <div><strong>Healthy People 2030</strong><span>A nationwide health promotion and disease prevention plan with goals set for the current decade.</span></div>\\r\\n                <div><strong>Health disparities</strong><span>Differences in health outcomes among groups based on gender, race, education, disability, or location.</span></div>\\r\\n                <div><strong>Health literacy</strong><span>A person\'s capacity to learn about and understand basic health information and use it to promote their own wellness.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=1","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 1 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=1#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=1#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 1 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=1#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=1","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 1 terms · earn medals","color":"#FF8C00"},{"href":"/game05_hot_takes.html","icon":"⚡","title":"Hot Takes Buzzer Battle","desc":"Perfect warm-up for Chapter 1 debates on what \\"health\\" really means.","count":"Daily warm-up","color":"#FFD700"},{"href":"/game12_would_you_rather.html","icon":"🤔","title":"Would You Rather","desc":"Opens great discussion on how students prioritize their own health dimensions.","count":"Discussion opener","color":"#00E5A0"},{"href":"/game15_myth_busters.html","icon":"💥","title":"Myth Busters","desc":"Busting health myths is the perfect first-day hook — students are always surprised.","count":"Day 1 hook","color":"#a855f7"},{"href":"/game11_taboo.html","icon":"🤐","title":"Health Taboo","desc":"Test vocab mastery at the end of Chapter 1 before moving to Chapter 2.","count":"Vocab check","color":"#FF8C00"}],"activities":[{"icon":"📊","title":"Side Quest 1 — Health Triangle Self-Assessment","desc":"Start with the classic health triangle (physical, mental/emotional, social), then add the other dimensions from Lesson 1 — spiritual, financial, environmental, and cultural. Rate yourself honestly and set one goal for your lowest area.","tags":[{"text":"Solo Quest","kind":"solo"},{"text":"~15 min","kind":""},{"text":"Week 1","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"🗺","title":"Exploration — 8 Dimensions of Health Map","desc":"Create a personal wellness wheel showing where you are on all 8 dimensions from Lesson 1 — physical, mental, emotional, social, spiritual, financial, environmental, and cultural. Color-coded and honest.","tags":[{"text":"Solo Quest","kind":"solo"},{"text":"~20 min","kind":""},{"text":"Week 1","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📰","title":"Exploration — Health in the News","desc":"Find one health news story from the past 12 months. Identify which dimension of health (Lesson 1) it relates to, whether the source is credible, and what the key takeaway is for teens.","tags":[{"text":"Team Event","kind":"team"},{"text":"~25 min","kind":""},{"text":"Week 2","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🎯","title":"Habit Challenge — 2-Week Healthy Habit Tracker","desc":"Choose ONE health habit to build over 2 weeks: sleep, water intake, screen time, physical activity, or fruit/vegetable servings. Track daily with a simple log. Report at the end of Realm I.","tags":[{"text":"Solo Quest","kind":"solo"},{"text":"2 Weeks","kind":""},{"text":"Chapter 1–2","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle — Health Jeopardy: Foundation Keep","desc":"The chapter boss battle. 5 categories covering both Chapter 1 and Chapter 2 content. Daily Double, Final Jeopardy with wagers. Teams compete for Realm I victory.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~45 min","kind":""}],"aiUrl":null}],"related":[{"href":"/habit_showdown.html","icon":"⚖️","title":"Habit Showdown","desc":"Good habit or bad? Myth or fact?"},{"href":"/dopp_breakout.html","icon":"🧱","title":"Habit Breaker","desc":"Smash a wall of bad habits"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":2,"realmTag":"Realm I — Foundation Keep","title":"Skills for a Healthy Life","sub":"Health decisions shape your future more than almost any other factor. This chapter gives you the actual skills — decision-making, goal setting, and knowing how to say no — that you\'ll use for the rest of your life.","meta":[{"icon":"📅","label":"Days","value":"1–4"},{"icon":"📖","label":"Lessons","value":"4"},{"icon":"🏆","label":"Badge","value":"Wellness Apprentice"}],"lessons":["L1: Decision Making","L2: Goal Setting","L3: Accessing Information","L4: Refusal Skills"],"pdf":"/Chapter_02_Taking_Charge_of_Your_Health.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Building Health Skills</h3>\\r\\n              <p><strong>Health skills</strong>, also called life skills, are the tools and strategies you use to protect, maintain, and improve your health. Once you build them, they stick with you for life.</p>\\r\\n\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <div class=\\"callout-label\\">Key Idea</div>\\r\\n                <div>Health skills are not just facts to memorize. They are actions you practice: communicating, saying no, finding reliable information, managing stress, making decisions, and setting goals.</div>\\r\\n              </div>\\r\\n\\r\\n              <h4>The Core Health Skills</h4>\\r\\n              <div class=\\"reading-grid compact\\">\\r\\n                <div class=\\"reading-tile\\"><h3>Communication</h3><p>Share ideas and feelings clearly while genuinely listening to others. Use \\"I\\" statements, stay calm, and listen actively.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Refusal Skills</h3><p>Say no firmly, respectfully, and confidently when pressured into something that goes against your values or health.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Conflict Resolution</h3><p>End disagreements through cooperation and problem-solving. Compromise often means both sides give a little to reach a result everyone can live with.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Accessing Information</h3><p>Find reliable health information from .gov and .edu sites, health professionals, and recently published work from respected experts.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Analyzing Influences</h3><p>Recognize what shapes your choices: values, family, culture, friends, and media. Self-awareness leads to better decisions.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Healthful Behaviors</h3><p>Make good habits part of your daily routine, including eating well, sleeping enough, staying active, and avoiding harmful substances.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Stress Management</h3><p>Stress is normal, but too much unmanaged stress can make you sick. Exercise, relaxation, and time management can help.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Advocacy</h3><p>Take action to encourage others to make healthy choices or support health-related causes.</p></div>\\r\\n              </div>\\r\\n            </section>\\r\\n\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Making Responsible Decisions and Setting Goals</h3>\\r\\n              <p>Good decisions start with your <strong>values</strong>: the beliefs and attitudes that guide the way you live. When a decision feels hard, talking it through with a trusted adult or family member can help.</p>\\r\\n\\r\\n              <h4>The 6-Step Decision-Making Process</h4>\\r\\n              <ol class=\\"reader-list\\">\\r\\n                <li><strong>State the situation:</strong> What exactly do I need to decide?</li>\\r\\n                <li><strong>List the options:</strong> What are all the possible choices?</li>\\r\\n                <li><strong>Weigh the outcomes:</strong> Use HELP: Healthful, Ethical, Legal, and Parent Approval.</li>\\r\\n                <li><strong>Consider values:</strong> Does this choice align with what matters to me?</li>\\r\\n                <li><strong>Make a decision and act:</strong> Commit to the healthiest responsible choice.</li>\\r\\n                <li><strong>Evaluate the decision:</strong> How did it go? What would I do differently?</li>\\r\\n              </ol>\\r\\n\\r\\n              <h4>Setting Goals: The S.M.A.R.T. Framework</h4>\\r\\n              <p>Goals are things you aim for that take planning and effort. The reason many goals fail is that they are too vague. S.M.A.R.T. goals make the target clear.</p>\\r\\n              <div class=\\"reading-grid compact\\">\\r\\n                <div class=\\"reading-tile\\"><h3>Specific</h3><p>Clearly define what you want. \\"Drink 8 glasses of water every day\\" is clearer than \\"be healthier.\\"</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Measurable</h3><p>Make sure you can track progress. \\"Run 3 times a week\\" is easier to measure than \\"exercise more.\\"</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Achievable</h3><p>Challenge yourself but stay realistic. Training for a 5K can be achievable; a marathon next week is probably not.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Relevant</h3><p>Connect the goal to something that matters. If you want to make the basketball team, stamina is relevant.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Time-bound</h3><p>Give yourself a deadline. \\"Cut out soda for 30 days\\" is stronger than \\"someday I will eat better.\\"</p></div>\\r\\n              </div>\\r\\n\\r\\n              <div class=\\"reading-check\\">\\r\\n                <strong>Upgrade the Goal</strong>\\r\\n                <span>Weak goal: \\"I want to sleep more.\\" S.M.A.R.T. goal: \\"I will be in bed by 10:30 PM on school nights for the next two weeks.\\"</span>\\r\\n              </div>\\r\\n\\r\\n              <p>Short-term goals are stepping stones to long-term goals. Build an <strong>action plan</strong>: write down your goal, list the steps, identify who can support you, set a timeline, create checkpoints, and celebrate when you succeed.</p>\\r\\n            </section>\\r\\n\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Being a Health-Literate Consumer</h3>\\r\\n              <p>Every day you make buying decisions. When it comes to health products and services, being a smart <strong>health consumer</strong> matters. One of the biggest influences on buying decisions is <strong>advertising</strong>: media messages designed to get you to buy something.</p>\\r\\n\\r\\n              <h4>Common Advertising Techniques to Watch For</h4>\\r\\n              <div class=\\"reading-grid compact\\">\\r\\n                <div class=\\"reading-tile\\"><h3>Bandwagon</h3><p>\\"Everyone\'s doing it!\\"</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Testimonial</h3><p>\\"It worked for me!\\"</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Rich and Famous</h3><p>Makes a product look luxurious or celebrity-approved.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Good Times</h3><p>Shows happy people using the product.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Great Outdoors</h3><p>Uses nature imagery to make something seem healthy.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Free Gifts</h3><p>Makes deals feel too good to pass up.</p></div>\\r\\n              </div>\\r\\n\\r\\n              <h4>How to Shop Smart</h4>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Read product labels. Ingredients are listed by weight from most to least. Active ingredients are what make a product work.</li>\\r\\n                <li>Use comparison shopping. Compare cost, quality, features, and safety ratings before buying.</li>\\r\\n                <li>Check the warranty, which is a written promise to repair or replace a product if it does not work properly.</li>\\r\\n                <li>Look for safety certifications such as UL for appliances and ANSI for helmets and protective gear.</li>\\r\\n                <li>Use trusted health sources such as .gov, .edu, the CDC, or the American Medical Association.</li>\\r\\n              </ul>\\r\\n            </section>\\r\\n\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Managing Consumer Problems</h3>\\r\\n              <h4>When a Product Does Not Work</h4>\\r\\n              <ol class=\\"reader-list\\">\\r\\n                <li>Read the warranty and return policy before you buy.</li>\\r\\n                <li>Follow the instructions carefully.</li>\\r\\n                <li>If it still does not work, contact the manufacturer.</li>\\r\\n                <li>If the issue is unresolved, reach out to the Better Business Bureau, consumer advocates, or the FDA.</li>\\r\\n              </ol>\\r\\n\\r\\n              <h4>Watch Out for Health Fraud</h4>\\r\\n              <p><strong>Health fraud</strong>, also called quackery, is the sale of worthless products or services claiming to cure or prevent health problems. Weight loss and beauty products are common targets.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <div class=\\"callout-label\\">Red Flags</div>\\r\\n                <div>\\"Secret formula,\\" \\"miracle cure,\\" \\"overnight results,\\" \\"all natural,\\" and \\"hurry, offer expires soon\\" are signs to slow down and check the claim.</div>\\r\\n              </div>\\r\\n              <p>Before buying anything that sounds too good to be true, check with a doctor, the Better Business Bureau, or a professional health organization like the American Heart Association.</p>\\r\\n            </section>\\r\\n\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Health skills</strong><span>Specific tools and strategies to maintain, protect, and improve all aspects of your health; also called life skills.</span></div>\\r\\n                <div><strong>Interpersonal communication</strong><span>The exchange of thoughts, feelings, and beliefs between two or more people.</span></div>\\r\\n                <div><strong>Refusal skills</strong><span>Communication strategies that help you say no to unsafe or unhealthful behaviors.</span></div>\\r\\n                <div><strong>Conflict resolution</strong><span>The process of ending a conflict through cooperation and problem solving.</span></div>\\r\\n                <div><strong>Stress</strong><span>The reaction of the body and mind to everyday challenges and demands.</span></div>\\r\\n                <div><strong>Stress management skills</strong><span>Skills that help you reduce and manage stress in your life.</span></div>\\r\\n                <div><strong>Advocacy</strong><span>Taking action to influence others to address a health-related concern or support a health-related belief.</span></div>\\r\\n                <div><strong>Values</strong><span>The ideas, beliefs, and attitudes about what is important that help guide the way you live.</span></div>\\r\\n                <div><strong>Decision-making skills</strong><span>Steps that enable you to make a healthful decision.</span></div>\\r\\n                <div><strong>Goals</strong><span>Things you aim for that take planning and work.</span></div>\\r\\n                <div><strong>Short-term goal</strong><span>A goal you can reach in a short period of time.</span></div>\\r\\n                <div><strong>Long-term goal</strong><span>A goal you plan to reach over an extended period of time.</span></div>\\r\\n                <div><strong>Action plan</strong><span>A multistep strategy to identify and achieve your goals.</span></div>\\r\\n                <div><strong>S.M.A.R.T. goals</strong><span>A goal-setting framework where goals are Specific, Measurable, Achievable, Relevant, and Time-bound.</span></div>\\r\\n                <div><strong>Health consumer</strong><span>Someone who purchases or uses health products or services.</span></div>\\r\\n                <div><strong>Advertising</strong><span>A written or spoken media message designed to interest consumers in purchasing a product or service.</span></div>\\r\\n                <div><strong>Comparison shopping</strong><span>Judging the benefits of different products by comparing factors such as quality, features, and cost.</span></div>\\r\\n                <div><strong>Warranty</strong><span>A company\'s or store\'s written agreement to repair a product or refund your money if it does not function properly.</span></div>\\r\\n                <div><strong>Consumer advocates</strong><span>People or groups whose purpose is to take on consumer issues and inform the public about potential problems.</span></div>\\r\\n                <div><strong>Malpractice</strong><span>Failure by a health professional to meet accepted standards of care.</span></div>\\r\\n                <div><strong>Health fraud</strong><span>The sale of worthless products or services that claim to prevent disease or cure health problems; also called quackery.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=2","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 2 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=2#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=2#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 2 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=2#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=2","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 2 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"SMART Goals Workshop","desc":"Write one real 4-week health goal using the SMART framework. Make it specific, measurable, achievable, realistic, and time-bound. Track your progress for the full realm.","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"🔍","title":"Refusal Skills Role Play","desc":"With a partner, practice 5 different refusal techniques using realistic teen scenarios. Which technique works best in which situation? Present your top strategy to the class.","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"📊","title":"Decision-Making Case Studies","desc":"Apply the 5-step decision-making process to 3 real teen health dilemmas. For each, identify the options, weigh the consequences, and explain what you would do and why.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/habit_showdown.html","icon":"⚖️","title":"Habit Showdown","desc":"Good habit or bad? Myth or fact?"},{"href":"/dopp_dunk.html","icon":"🏀","title":"Sprite Hoops","desc":"Shoot bad habits into the trash"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":3,"realmTag":"Realm II — Mind Citadel","title":"Mental and Emotional Health","sub":"Mental health is health. Understanding your emotions, building self-esteem, and developing resilience are skills just as real as any physical ones — and just as important to train.","meta":[{"icon":"📅","label":"Days","value":"5–8"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Mind Knight"}],"lessons":["L1: Developing Self-Esteem","L2: Identity & Character","L3: Expressing Emotions"],"pdf":"/Chapter_03_Achieving_Mental_and_Emotional_Health.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Developing Your Self-Esteem</h3>\\r\\n              <h4>What Is Mental and Emotional Health?</h4>\\r\\n              <p><strong>Mental and emotional health</strong> is your ability to accept yourself and others, express and manage your emotions, and handle the demands and challenges life throws at you. When you\'re struggling emotionally it often shows up as poor sleep, unhealthy eating, or strained relationships.</p>\\r\\n\\r\\n              <h4>Signs of Good Mental and Emotional Health</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Sense of belonging:</strong> Feeling connected to family, friends, and your community</li>\\r\\n                <li><strong>Sense of purpose:</strong> Believing your life has meaning and direction</li>\\r\\n                <li><strong>Positive outlook:</strong> Seeing the bright side even when things are hard</li>\\r\\n                <li><strong>Self-sufficiency:</strong> Trusting yourself to make responsible decisions</li>\\r\\n                <li><strong>Healthy self-esteem:</strong> Believing in your own worth, even when you make mistakes</li>\\r\\n              </ul>\\r\\n\\r\\n              <p>People with good mental and emotional health are <strong>resilient</strong> — they have the ability to adapt and bounce back from disappointment, difficulty, or crisis. Everyone faces hard times; resilience is what helps you get through them.</p>\\r\\n\\r\\n              <h4>Building Self-Esteem</h4>\\r\\n              <p><strong>Self-esteem</strong> is how much you value, respect, and feel confident about yourself. It shapes your outlook and influences the health choices you make. It grows when you push through challenges and use <strong>positive self-talk</strong> — the encouraging inner voice that reminds you of your worth.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Choose friends who genuinely value and respect you</li>\\r\\n                <li>Replace negative self-talk with supportive self-talk</li>\\r\\n                <li>See mistakes as learning opportunities, not failures</li>\\r\\n                <li>Try new activities to discover your strengths</li>\\r\\n                <li>Volunteer — helping others is one of the fastest ways to feel good about yourself</li>\\r\\n                <li>Focus on progress, not perfection</li>\\r\\n              </ul>\\r\\n\\r\\n              <h4>Maslow\'s Hierarchy of Needs</h4>\\r\\n              <p>Psychologist Abraham Maslow created a model explaining what motivates human growth. The <strong>hierarchy of needs</strong> is a ranked list of needs essential to development, starting at the most basic and building upward:</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Physical needs:</strong> Food, water, sleep, shelter</li>\\r\\n                <li><strong>Safety needs:</strong> Being secure from danger</li>\\r\\n                <li><strong>Belonging needs:</strong> Love, connection, feeling accepted</li>\\r\\n                <li><strong>Esteem needs:</strong> Feeling valued and recognized</li>\\r\\n                <li><strong>Self-actualization:</strong> Reaching your full potential</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <div class=\\"callout-label\\">Key Idea</div>\\r\\n                <div>You need to meet lower-level needs before you can focus on higher ones — and it matters <em>how</em> you meet those needs. Joining a gang to feel accepted, for example, is a high-risk behavior that damages all sides of your health.</div>\\r\\n              </div>\\r\\n            </section>\\r\\n\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Developing Personal Identity and Character</h3>\\r\\n              <h4>Your Personal Identity</h4>\\r\\n              <p>Your <strong>personal identity</strong> is your sense of yourself as a unique individual — your values, interests, beliefs, strengths, and relationships. It\'s shaped by your family, culture, friendships, and experiences, and continues developing throughout your teen years and beyond.</p>\\r\\n\\r\\n              <h4>The 6 Traits of Good Character</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Trustworthiness:</strong> Honest, reliable, and loyal. You do what you say you\'ll do.</li>\\r\\n                <li><strong>Respect:</strong> Treat people and their property with care, even when you disagree.</li>\\r\\n                <li><strong>Responsibility:</strong> Think before you act, own your choices, and follow through.</li>\\r\\n                <li><strong>Fairness:</strong> Play by the rules, share, and don\'t take advantage of others.</li>\\r\\n                <li><strong>Caring:</strong> Show kindness, gratitude, and compassion toward others.</li>\\r\\n                <li><strong>Citizenship:</strong> Contribute to your school and community, follow laws, and advocate for a healthy environment.</li>\\r\\n              </ul>\\r\\n\\r\\n              <p>A person of good character demonstrates these values consistently through <strong>integrity</strong> — living by core ethical values even when no one is watching.</p>\\r\\n\\r\\n              <h4>Building a Healthy Identity</h4>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Know your strengths and weaknesses — honestly and without being too hard on yourself</li>\\r\\n                <li>Surround yourself with positive, supportive people</li>\\r\\n                <li>Develop a sense of purpose through short-term and long-term goals</li>\\r\\n                <li>Build meaningful relationships — people who give you constructive criticism are your most valuable supporters</li>\\r\\n                <li>Give back to your community through volunteering</li>\\r\\n              </ul>\\r\\n            </section>\\r\\n\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Expressing Emotions in Healthful Ways</h3>\\r\\n              <h4>Understanding Your Emotions</h4>\\r\\n              <p><strong>Emotions</strong> are signals that tell your mind and body how to react. They\'re neither good nor bad — what matters is how you choose to express them. During the teen years, <strong>hormones</strong> can make emotions feel more intense and unpredictable.</p>\\r\\n              <div class=\\"reading-check\\">\\r\\n                <strong>Reality Check</strong>\\r\\n                <span>According to the CDC, about <strong>40% of high school students</strong> reported persistent sadness or hopelessness in 2023.</span>\\r\\n              </div>\\r\\n\\r\\n              <h4>Common Emotions</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Happiness:</strong> Feeling satisfied and positive; brings energy and creativity</li>\\r\\n                <li><strong>Sadness:</strong> A normal reaction to loss or disappointment — it\'s okay to feel sad</li>\\r\\n                <li><strong>Love:</strong> Deep affection, care, and respect for someone</li>\\r\\n                <li><strong>Fear:</strong> A natural response to danger; can become a problem if it stops healthy risk-taking</li>\\r\\n                <li><strong>Guilt:</strong> Regret when you act against your values — sometimes felt over things beyond your control</li>\\r\\n                <li><strong>Anger:</strong> Normal reaction to hurt or harm — becomes <strong>hostility</strong> when intentionally harmful toward others</li>\\r\\n              </ul>\\r\\n\\r\\n              <h4>Managing Your Emotions</h4>\\r\\n              <p>When emotions feel overwhelming: take slow deep breaths, relax your muscles, remove yourself from the situation, write in a private journal, or talk to someone you trust.</p>\\r\\n              <p>Some people use <strong>defense mechanisms</strong> — mental processes that protect from intense emotional pain. Common ones include: Repression, Denial, Projection, Rationalization, Suppression, Regression, and Compensation. These can provide short-term relief, but relying on them too long prevents you from solving the actual problem.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <div class=\\"callout-label\\">Anger Tip</div>\\r\\n                <div>When you feel anger building, <strong>PAUSE</strong>. Try deep breathing, remove yourself from the situation, channel the energy into something physical, or talk it out. <strong>Empathy</strong> — understanding how the other person feels — can also help you cool down and see the full picture.</div>\\r\\n              </div>\\r\\n            </section>\\r\\n\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Mental/emotional health</strong><span>The ability to accept yourself and others, express and manage emotions, and deal with the demands and challenges of life</span></div>\\r\\n                <div><strong>Resilient</strong><span>Having the ability to adapt effectively and recover from disappointment, difficulty, or crisis</span></div>\\r\\n                <div><strong>Self-esteem</strong><span>How much you value, respect, and feel confident about yourself</span></div>\\r\\n                <div><strong>Competence</strong><span>Having enough skills to do something successfully</span></div>\\r\\n                <div><strong>Hierarchy of needs</strong><span>A ranked list of needs essential to human growth and development, from basic physical needs up to reaching your full potential</span></div>\\r\\n                <div><strong>Self-actualization</strong><span>The drive to reach your full potential and become the best version of yourself</span></div>\\r\\n                <div><strong>Personal identity</strong><span>Your sense of yourself as a unique individual, shaped by your values, relationships, experiences, and beliefs</span></div>\\r\\n                <div><strong>Role model</strong><span>Someone whose success or behavior serves as an example for others</span></div>\\r\\n                <div><strong>Personality</strong><span>The complex set of characteristics that makes a person unique</span></div>\\r\\n                <div><strong>Character</strong><span>The distinctive qualities that describe how a person thinks, feels, and behaves</span></div>\\r\\n                <div><strong>Integrity</strong><span>A firm, consistent commitment to core ethical values</span></div>\\r\\n                <div><strong>Constructive criticism</strong><span>Honest, non-hostile feedback that points out problems and encourages improvement</span></div>\\r\\n                <div><strong>Emotions</strong><span>Signals that tell your mind and body how to react to situations</span></div>\\r\\n                <div><strong>Hormones</strong><span>Chemicals produced by your glands that regulate the activities of different body cells</span></div>\\r\\n                <div><strong>Hostility</strong><span>The intentional use of unfriendly or offensive behavior toward others</span></div>\\r\\n                <div><strong>Empathy</strong><span>The ability to imagine and understand how someone else feels</span></div>\\r\\n                <div><strong>Defense mechanisms</strong><span>Mental processes that protect individuals from strong or stressful emotions and situations</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=3","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 3 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=3#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=3#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 3 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=3#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=3","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 3 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"Emotional Intelligence Inventory","desc":"Rate yourself honestly on the 5 components of emotional intelligence: self-awareness, self-regulation, motivation, empathy, and social skills. Identify your strongest and weakest areas with evidence.","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"🔍","title":"Teen Mental Health in the News","desc":"Find a recent article or study on teen mental health trends. What does the data show? What factors are driving those trends? What does it mean for your generation specifically?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Coping Strategy Experiment","desc":"Try 3 different coping strategies this week — one physical, one cognitive, one social. Write a reflection: what worked, what didn\'t, and what you would use in a real crisis.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_match.html","icon":"🧠","title":"Sprite Memory","desc":"Match healthy pairs before time runs out"},{"href":"/dopp_wordle.html","icon":"🔤","title":"Word Quest","desc":"Guess the 5-letter health word"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":4,"realmTag":"Realm II — Mind Citadel","title":"Managing Stress","sub":"Your body responds to stress the same way it responded to predators 10,000 years ago. Understanding that response — and knowing how to calm it — is one of the most powerful health skills you can develop.","meta":[{"icon":"📅","label":"Days","value":"7–10"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Mind Knight"}],"lessons":["L1: What Is Stress?","L2: How Stress Affects the Body","L3: Stress Management Techniques"],"pdf":"/Chapter_04_Managing_Stress_and_Coping_with_Loss.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — What Is Stress?</h3>\\r\\n              <h4>Defining Stress</h4>\\r\\n              <p>Stress is the body\'s response to any demand placed on it. It is not inherently bad — some stress sharpens focus, fuels motivation, and helps you perform. The key is whether the stress is short-term and manageable, or chronic and overwhelming.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <div class=\\"callout-label\\">Key Idea</div>\\r\\n                <div>A stressor is anything that causes stress. Stressors can be physical (illness, lack of sleep), emotional (breakups, loss), or environmental (noise, crowding). Your perception of a stressor matters as much as the stressor itself.</div>\\r\\n              </div>\\r\\n              <h4>Types of Stress</h4>\\r\\n              <div class=\\"reading-grid compact\\">\\r\\n                <div class=\\"reading-tile\\"><h3>Eustress</h3><p>Positive stress that motivates you — like excitement before a big game or a first date.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Distress</h3><p>Negative stress that feels overwhelming or uncontrollable — chronic worry, burnout, anxiety.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Acute stress</h3><p>Short-term, intense stress that passes once the event ends.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Chronic stress</h3><p>Long-term, persistent stress that takes a serious toll on mental and physical health.</p></div>\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — The Body\'s Response to Stress</h3>\\r\\n              <p>When you encounter a stressor, your body automatically activates the fight-or-flight response — a survival mechanism hardwired into your nervous system. Your brain releases adrenaline and cortisol, your heart rate increases, muscles tense, and you become hyperaware of your surroundings.</p>\\r\\n              <h4>The General Adaptation Syndrome (GAS)</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Alarm Stage:</strong> The body detects the stressor and triggers the fight-or-flight response.</li>\\r\\n                <li><strong>Resistance Stage:</strong> The body attempts to cope and adapt. Resources are being used up.</li>\\r\\n                <li><strong>Exhaustion Stage:</strong> If stress continues too long without relief, the body runs out of reserves and becomes vulnerable to illness.</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\">\\r\\n                <strong>Physical Toll</strong>\\r\\n                <span>Chronic stress is linked to heart disease, weakened immunity, digestive problems, insomnia, and depression. Managing stress is literally life-saving.</span>\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Stress Management Techniques</h3>\\r\\n              <p>You cannot eliminate all stressors, but you can control how you respond to them. Effective stress management is a skill — and like any skill, it improves with practice.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><h3>Physical Methods</h3><p>Exercise, progressive muscle relaxation, deep breathing, yoga, adequate sleep.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Mental Methods</h3><p>Reframing (changing how you interpret a stressor), mindfulness, journaling, positive self-talk.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Social Methods</h3><p>Talking with a trusted person, laughing with friends, joining a group or club.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Time Management</h3><p>Prioritizing tasks, breaking large projects into steps, saying no when your plate is full.</p></div>\\r\\n              </div>\\r\\n              <h4>The 4 A\'s of Stress Management</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Avoid:</strong> Remove the stressor if possible.</li>\\r\\n                <li><strong>Alter:</strong> Change the situation by communicating differently.</li>\\r\\n                <li><strong>Accept:</strong> Accept what you cannot change and adjust your response.</li>\\r\\n                <li><strong>Adapt:</strong> Reframe the stressor into a growth opportunity.</li>\\r\\n              </ul>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Resilience and Post-Traumatic Growth</h3>\\r\\n              <p>Resilience is not about avoiding stress — it is about developing the capacity to move through it. People with high resilience do not experience less hardship; they recover more quickly and often emerge stronger.</p>\\r\\n              <h4>Building Resilience</h4>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Maintain strong social connections — isolation makes stress worse</li>\\r\\n                <li>Keep a routine — predictability reduces anxiety</li>\\r\\n                <li>Find meaning — people who see purpose in hardship recover faster</li>\\r\\n                <li>Take care of basics — sleep, nutrition, and exercise form the foundation</li>\\r\\n                <li>Practice optimism — not denial, but the belief that things can improve</li>\\r\\n              </ul>\\r\\n              <p>Post-traumatic growth is real: many people report that their most difficult experiences ultimately helped them develop greater strength, deeper relationships, and a clearer sense of what matters in life.</p>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Stress</strong><span>The body\'s response to real or imagined demands or threats.</span></div>\\r\\n                <div><strong>Stressor</strong><span>Any situation or event that causes stress.</span></div>\\r\\n                <div><strong>Eustress</strong><span>Positive stress that motivates and energizes a person.</span></div>\\r\\n                <div><strong>Distress</strong><span>Negative stress that feels uncontrollable and depletes the body and mind.</span></div>\\r\\n                <div><strong>Fight-or-flight response</strong><span>The body\'s automatic physical reaction to a perceived threat, preparing you to confront or flee.</span></div>\\r\\n                <div><strong>Adrenaline</strong><span>A hormone released during the stress response that increases heart rate and energy.</span></div>\\r\\n                <div><strong>Cortisol</strong><span>The primary stress hormone; elevated levels over time harm immunity, sleep, and mood.</span></div>\\r\\n                <div><strong>General Adaptation Syndrome</strong><span>The three-stage process (alarm, resistance, exhaustion) the body goes through when exposed to prolonged stress.</span></div>\\r\\n                <div><strong>Resilience</strong><span>The ability to recover from stress, trauma, and adversity.</span></div>\\r\\n                <div><strong>Mindfulness</strong><span>The practice of focusing attention on the present moment without judgment.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=4","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 4 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=4#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=4#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 4 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=4#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=4","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 4 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"Personal Stress Audit","desc":"List your top 5 stressors. Classify each as eustress or distress. Rate intensity 1–10. Identify which are within your control and which aren\'t. What pattern do you notice?","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"🔍","title":"Chronic Stress & the Teen Brain","desc":"Find current research on how chronic stress affects adolescent brain development, immune function, and long-term health. Summarize the 3 most alarming findings and what they mean for daily choices.","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Stress Management Plan","desc":"Design a realistic personal stress-reduction plan using at least 3 different strategies from the chapter. Be specific — what will you do, when, and how will you know it\'s working?","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_dunk.html","icon":"🏀","title":"Sprite Hoops","desc":"Shoot bad habits into the trash"},{"href":"/sprite_run.html","icon":"🛕","title":"Sprite Run","desc":"Swipe past soda, grab fruit"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":5,"realmTag":"Realm II — Mind Citadel","title":"Mental and Emotional Problems","sub":"Mental health conditions are not character flaws — they\'re medical conditions. This chapter covers the most common disorders affecting teens, how to recognize warning signs, and how to get help.","meta":[{"icon":"📅","label":"Days","value":"9–10"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Mind Knight"}],"lessons":["L1: Mental Disorders","L2: Suicide Prevention","L3: Getting Help"],"pdf":"/Chapter_05_Mental_and_Emotional_Problems.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Mental Disorders</h3>\\r\\n              <h4>What Is a Mental Disorder?</h4>\\r\\n              <p>A mental disorder is an illness that affects a person\'s thinking, feelings, or behavior to the point where it interferes with normal functioning. Mental disorders are medical conditions — they have biological, psychological, and social causes, just like physical diseases.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <div class=\\"callout-label\\">Key Idea</div>\\r\\n                <div>Mental disorders are not character flaws or signs of weakness. They are diagnosable, treatable medical conditions. About 50% of all mental disorders begin by age 14.</div>\\r\\n              </div>\\r\\n              <h4>Common Mental Disorders in Teens</h4>\\r\\n              <div class=\\"reading-grid compact\\">\\r\\n                <div class=\\"reading-tile\\"><h3>Anxiety Disorders</h3><p>Excessive, persistent fear or worry that interferes with daily life. Includes generalized anxiety, panic disorder, social anxiety, and phobias.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Depression</h3><p>Persistent sadness, loss of interest, low energy, and hopelessness lasting more than two weeks.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>ADHD</h3><p>Difficulty with attention, impulse control, and sometimes hyperactivity. Very common and highly manageable with the right support.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Eating Disorders</h3><p>Unhealthy relationships with food and body image, including anorexia, bulimia, and binge eating disorder.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>PTSD</h3><p>Post-traumatic stress disorder develops after experiencing or witnessing a traumatic event.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>OCD</h3><p>Obsessive-compulsive disorder involves recurring, unwanted thoughts and repetitive behaviors.</p></div>\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Depression and Anxiety</h3>\\r\\n              <p>Depression and anxiety are the two most common mental health issues among teenagers. Understanding them — what they look like, what causes them, and how they are treated — is essential health literacy.</p>\\r\\n              <h4>Warning Signs of Depression</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Persistent sadness, emptiness, or hopelessness</li>\\r\\n                <li>Loss of interest in activities once enjoyed</li>\\r\\n                <li>Changes in sleep (too much or too little)</li>\\r\\n                <li>Changes in appetite or weight</li>\\r\\n                <li>Difficulty concentrating, making decisions</li>\\r\\n                <li>Fatigue or loss of energy nearly every day</li>\\r\\n                <li>Feelings of worthlessness or excessive guilt</li>\\r\\n              </ul>\\r\\n              <h4>Warning Signs of Anxiety</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Constant worry that is hard to control</li>\\r\\n                <li>Physical symptoms: racing heart, sweating, trembling</li>\\r\\n                <li>Avoiding situations that trigger fear</li>\\r\\n                <li>Trouble sleeping due to worry</li>\\r\\n                <li>Irritability and difficulty concentrating</li>\\r\\n              </ul>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Suicide Prevention</h3>\\r\\n              <p>Suicide is the second leading cause of death for people aged 10–34 in the United States. It is preventable. Most people who consider suicide do not want to die — they want the pain to stop. Knowing the warning signs and how to respond saves lives.</p>\\r\\n              <h4>Warning Signs</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Talking about wanting to die or having no reason to live</li>\\r\\n                <li>Giving away prized possessions</li>\\r\\n                <li>Saying goodbye to people as if they will not see them again</li>\\r\\n                <li>Sudden calmness after a period of deep depression</li>\\r\\n                <li>Researching methods of self-harm</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\">\\r\\n                <strong>What To Do</strong>\\r\\n                <span>Ask directly, listen without judgment, and get help immediately. Never promise to keep a suicide crisis secret. Call or text 988 (Suicide &amp; Crisis Lifeline) or go to the nearest emergency room.</span>\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Getting Help</h3>\\r\\n              <p>Treatment works. Most people with mental health conditions improve significantly with the right support. The most important step is reaching out.</p>\\r\\n              <h4>Types of Professional Help</h4>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><h3>Therapist / Counselor</h3><p>Provides talk therapy to help understand and change thought and behavior patterns. No medication involved.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Psychiatrist</h3><p>A medical doctor who can diagnose mental disorders and prescribe medication.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>School Counselor</h3><p>First point of contact for many teens — can provide support and connect students to community resources.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Crisis Lines</h3><p>988 (call/text) for suicide and mental health crises. Available 24/7, free, and confidential.</p></div>\\r\\n              </div>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Asking for help is the bravest thing you can do</li>\\r\\n                <li>Mental illness is not a personal failure</li>\\r\\n                <li>Recovery is possible — most people get better with treatment</li>\\r\\n                <li>You do not have to wait until you are in crisis to seek support</li>\\r\\n              </ul>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Mental disorder</strong><span>An illness that affects a person\'s thoughts, emotions, or behavior, interfering with normal functioning.</span></div>\\r\\n                <div><strong>Anxiety disorder</strong><span>A mental disorder characterized by excessive, persistent fear or worry that interferes with daily life.</span></div>\\r\\n                <div><strong>Depression</strong><span>A mood disorder marked by persistent sadness, loss of interest, and low energy lasting more than two weeks.</span></div>\\r\\n                <div><strong>Phobia</strong><span>An intense, irrational fear of a specific object or situation.</span></div>\\r\\n                <div><strong>ADHD</strong><span>Attention-deficit/hyperactivity disorder; difficulty sustaining attention and controlling impulses.</span></div>\\r\\n                <div><strong>Eating disorder</strong><span>A mental illness involving severe disturbances in eating behaviors and body image.</span></div>\\r\\n                <div><strong>PTSD</strong><span>Post-traumatic stress disorder; a condition triggered by experiencing or witnessing a traumatic event.</span></div>\\r\\n                <div><strong>Suicide</strong><span>The act of intentionally ending one\'s own life.</span></div>\\r\\n                <div><strong>Stigma</strong><span>A mark of shame or disgrace associated with a particular circumstance or characteristic.</span></div>\\r\\n                <div><strong>Therapy</strong><span>A treatment for mental and emotional disorders in which a trained professional helps a person understand and manage their condition.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=5","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 5 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=5#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=5#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 5 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=5#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=5","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 5 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"Mental Health Myths vs. Facts","desc":"Research 5 common myths about mental illness — stigma, treatment, violence, weakness, etc. Find peer-reviewed facts that correct each one. Present as a myth-busting infographic or slide.","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🔍","title":"Warning Signs & Resources Map","desc":"Research the warning signs of depression, anxiety, and eating disorders. Then map the real resources available — at school, locally, and nationally. How accessible are they for teens?","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📊","title":"Anti-Stigma Campaign Concept","desc":"Design a 1-page concept for a school mental health anti-stigma campaign. Define the audience, core message, medium, and call to action. What would actually change student behavior?","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/habit_showdown.html","icon":"⚖️","title":"Habit Showdown","desc":"Good habit or bad? Myth or fact?"},{"href":"/dopp_wordle.html","icon":"🔤","title":"Word Quest","desc":"Guess the 5-letter health word"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":6,"realmTag":"Realm III — Relationship Realm","title":"Building Healthy Relationships","sub":"Healthy relationships are one of the strongest predictors of long-term happiness and health. This chapter covers what makes relationships healthy — and what makes them not.","meta":[{"icon":"📅","label":"Days","value":"11–14"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Social Champion"}],"lessons":["L1: Friendships","L2: Romantic Relationships","L3: Communication Skills"],"pdf":"/Chapter_06_Skills_for_Healthy_Relationships.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Foundations of Healthy Relationships</h3>\\r\\n              <h4>What Makes a Relationship Healthy?</h4>\\r\\n              <p>Healthy relationships — whether with friends, family, or romantic partners — share the same core qualities: mutual respect, trust, honesty, support, and open communication. When these qualities are present, relationships add to your life. When they are absent, relationships drain and damage.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <div class=\\"callout-label\\">Key Idea</div>\\r\\n                <div>You teach people how to treat you. The boundaries you set and enforce communicate what you will and will not accept in your relationships.</div>\\r\\n              </div>\\r\\n              <h4>Types of Relationships</h4>\\r\\n              <div class=\\"reading-grid compact\\">\\r\\n                <div class=\\"reading-tile\\"><h3>Friendships</h3><p>Voluntary bonds built on shared interests, trust, and mutual support. Quality over quantity matters.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Family</h3><p>Primary relationships that shape your values, communication style, and sense of self from birth.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Romantic</h3><p>Involve deeper emotional and sometimes physical intimacy. Require the same respect and communication as all healthy relationships.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Professional/Peer</h3><p>Classmates, teammates, coworkers. Boundaries are often clearer; respect and cooperation are essential.</p></div>\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Communication Skills</h3>\\r\\n              <p>Communication is the foundation of every relationship. Most relationship problems are, at their core, communication problems. Learning to communicate clearly and respectfully is one of the highest-value life skills you can develop.</p>\\r\\n              <h4>Components of Effective Communication</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>\\"I\\" statements:</strong> Express how you feel without blaming. \\"I feel hurt when...\\" instead of \\"You always...\\"</li>\\r\\n                <li><strong>Active listening:</strong> Full attention, no interrupting, reflecting back what you heard.</li>\\r\\n                <li><strong>Nonverbal communication:</strong> Eye contact, posture, tone of voice — these carry more weight than words.</li>\\r\\n                <li><strong>Assertiveness:</strong> Stating your needs clearly and respectfully, without aggression or passivity.</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\">\\r\\n                <strong>Communication Styles</strong>\\r\\n                <span>Passive communicators avoid conflict but build resentment. Aggressive communicators win arguments but damage trust. Assertive communicators express needs directly while respecting others — this is the goal.</span>\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Peer Pressure and Refusal Skills</h3>\\r\\n              <p>Peer pressure does not always look like someone threatening you. More often it is subtle: wanting to fit in, fear of rejection, or not wanting to be the only one who says no. Building strong refusal skills protects your health and your values.</p>\\r\\n              <h4>Effective Refusal Strategies</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Say no clearly and without apology — \\"No, I\'m not doing that.\\"</li>\\r\\n                <li>Suggest an alternative — \\"I\'m not doing that, but I\'ll do this instead.\\"</li>\\r\\n                <li>Use the broken record technique — keep repeating no calmly.</li>\\r\\n                <li>Leave the situation — you always have the right to walk away.</li>\\r\\n                <li>Use delay tactics — \\"I need to think about it\\" buys time.</li>\\r\\n              </ul>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Unhealthy Relationships and Boundaries</h3>\\r\\n              <p>Not all relationships are healthy. Recognizing the signs of unhealthy and abusive relationships early — before they escalate — is critical for your safety and well-being.</p>\\r\\n              <h4>Signs of an Unhealthy Relationship</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>One person consistently controls or manipulates the other</li>\\r\\n                <li>Disrespect, criticism, or humiliation — especially in public</li>\\r\\n                <li>Jealousy framed as love or caring</li>\\r\\n                <li>Pressure to change who you are or give up your other relationships</li>\\r\\n                <li>Fear of your partner\'s or friend\'s reactions</li>\\r\\n              </ul>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Everyone deserves a relationship free from fear, control, and disrespect</li>\\r\\n                <li>Setting and enforcing boundaries is not selfish — it is necessary</li>\\r\\n                <li>If you feel unsafe, tell a trusted adult or call the National Domestic Violence Hotline: 1-800-799-7233</li>\\r\\n              </ul>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Relationship</strong><span>A bond or connection between people based on shared feelings, experiences, or interests.</span></div>\\r\\n                <div><strong>Communication</strong><span>The process of sharing thoughts, feelings, and information with others.</span></div>\\r\\n                <div><strong>Active listening</strong><span>Fully concentrating, understanding, responding, and remembering what is being said.</span></div>\\r\\n                <div><strong>\\"I\\" statements</strong><span>Phrases that express personal feelings without blaming others, beginning with \\"I feel...\\"</span></div>\\r\\n                <div><strong>Assertiveness</strong><span>The ability to express your needs and opinions clearly and respectfully.</span></div>\\r\\n                <div><strong>Peer pressure</strong><span>Influence from people your own age to act or think in a certain way.</span></div>\\r\\n                <div><strong>Refusal skills</strong><span>Strategies used to say no to unwanted or risky behaviors.</span></div>\\r\\n                <div><strong>Boundaries</strong><span>Limits a person sets on what they consider acceptable behavior from others.</span></div>\\r\\n                <div><strong>Trust</strong><span>A firm belief in the reliability, honesty, and ability of another person.</span></div>\\r\\n                <div><strong>Manipulation</strong><span>Using unfair or dishonest methods to control or influence another person.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=6","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 6 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=6#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=6#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 6 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=6#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=6","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 6 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"Healthy vs. Unhealthy Relationship Spectrum","desc":"Analyze 5 relationship scenarios — friendships, family, and romantic. Place each on a spectrum from healthy to abusive. Explain your reasoning using specific evidence from the chapter.","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"🔍","title":"Communication Styles in the Wild","desc":"Research the 4 communication styles: passive, aggressive, passive-aggressive, and assertive. Find a real-world example of each in media, news, or your own experience. Which do you default to?","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Personal Boundaries Statement","desc":"Write 5 personal boundaries you believe everyone should hold in friendships and relationships. Explain the \'why\' behind each one. What happens to a relationship when a boundary is crossed?","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/habit_showdown.html","icon":"⚖️","title":"Habit Showdown","desc":"Good habit or bad? Myth or fact?"},{"href":"/dopp_match.html","icon":"🧠","title":"Sprite Memory","desc":"Match healthy pairs before time runs out"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":7,"realmTag":"Realm III — Relationship Realm","title":"Family Relationships","sub":"Your family is the first relationship you ever had, and it shapes nearly everything that comes after. Learn what makes families strong, how families cope with change, and where to find help when home isn\'t safe.","meta":[{"icon":"📅","label":"Days","value":"Day 15"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Social Champion"}],"lessons":["L1: Healthy Family Relationships","L2: Strengthening Family Relationships","L3: Help for Families"],"pdf":"/Chapter_07_Family_Relationships.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n  <h3>Lesson 1 — Healthy Family Relationships</h3>\\r\\n  <h4>Types of Families</h4>\\r\\n  <p>American families come in many forms. About 65% of children live with two married parents, 22% with their mother only, 5% with their father only, and 4% with neither parent. What makes a family isn\'t a legal definition. It\'s love, commitment and the bonds that form over a lifetime.</p>\\r\\n  <div class=\\"reading-grid compact\\">\\r\\n    <div class=\\"reading-tile\\"><h3>Nuclear</h3><p>Two parents and one or more children living together.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Single-parent</h3><p>One parent raising one or more children, often after divorce, separation or death.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Blended</h3><p>Formed when a single parent remarries, bringing children from earlier relationships together.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Extended</h3><p>Includes grandparents, aunts, uncles or cousins, sometimes living in the same home.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Adoptive &amp; Foster</h3><p>Adoption is a permanent legal family. Foster care is a temporary placement with adults who aren\'t relatives.</p></div>\\r\\n  </div>\\r\\n  <h4>Your Family and Your Health</h4>\\r\\n  <ul class=\\"reader-list\\">\\r\\n    <li><strong>Physical health:</strong> Families provide food, clothing, shelter and medical care, set safety rules and model healthy habits.</li>\\r\\n    <li><strong>Mental/emotional health:</strong> A healthy family gives you a safe place to share feelings, a sense of belonging, and <em>affirmation</em>, positive feedback that helps you feel valued.</li>\\r\\n    <li><strong>Social health:</strong> Your first lessons in communicating, sharing, cooperating and settling disagreements came from your family.</li>\\r\\n  </ul>\\r\\n</section>\\r\\n<section class=\\"reader-section\\">\\r\\n  <h3>Lesson 2 — Strengthening Family Relationships</h3>\\r\\n  <h4>Traits of Strong Families</h4>\\r\\n  <ul class=\\"reader-list\\">\\r\\n    <li><strong>Good communication:</strong> They share thoughts and feelings honestly, listen and show empathy.</li>\\r\\n    <li><strong>Caring and support:</strong> They show appreciation and help each other through hard times.</li>\\r\\n    <li><strong>Respect:</strong> They honor each other\'s opinions, privacy and individuality.</li>\\r\\n    <li><strong>Commitment:</strong> They make time for each other and work on problems together.</li>\\r\\n    <li><strong>Trust:</strong> Parents keep promises, and children show they are reliable and honest.</li>\\r\\n  </ul>\\r\\n  <h4>Coping with Family Change</h4>\\r\\n  <div class=\\"reading-grid compact\\">\\r\\n    <div class=\\"reading-tile\\"><h3>New baby or adoption</h3><p>Exciting, but everyone\'s roles shift. Tension eases as the family adjusts.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Separation &amp; divorce</h3><p>Painful for everyone. <em>Custody</em> may go to one parent or be shared. The divorce is never the children\'s fault.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Remarriage</h3><p>Blended families can take 4–7 years to feel natural. Patience and respect help.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Death, moving, money</h3><p>Grief, a new school or a lost job all add stress. Talking openly helps the whole family cope.</p></div>\\r\\n  </div>\\r\\n  <div class=\\"reading-callout\\"><div class=\\"callout-label\\">Key Idea</div><div>The most important coping strategy is honest, open communication. Talking about your feelings, even when it\'s uncomfortable, lowers stress and helps family members support each other.</div></div>\\r\\n</section>\\r\\n<section class=\\"reader-section\\">\\r\\n  <h3>Lesson 3 — Help for Families</h3>\\r\\n  <h4>Violence in Families</h4>\\r\\n  <p><em>Abuse</em> is the physical, mental, emotional or sexual mistreatment of one person by another. When it happens between family members, it is called <em>domestic violence</em>. It can be spousal abuse, child abuse (including <em>neglect</em>) or elder abuse. Abuse is always wrong, and it is a crime.</p>\\r\\n  <h4>Recognize · Resist · Report</h4>\\r\\n  <ul class=\\"reader-checklist\\">\\r\\n    <li><strong>Recognize:</strong> Abuse is a crime. Take any report seriously.</li>\\r\\n    <li><strong>Resist:</strong> If it\'s safe, get away and reach a trusted adult.</li>\\r\\n    <li><strong>Report:</strong> Tell someone who can help: a trusted adult, school counselor, doctor, hotline or police.</li>\\r\\n  </ul>\\r\\n  <p>The <em>cycle of violence</em>, abuse repeating from one generation to the next, can be broken with professional help. Asking for help takes courage. Crisis centers, family counseling and support groups all help families heal.</p>\\r\\n  <div class=\\"reading-callout\\"><div class=\\"callout-label\\">Get Help</div><div>National Domestic Violence Hotline: <strong>1-800-799-7233</strong> (or text START to 88788) · Childhelp Child Abuse Hotline: <strong>1-800-422-4453</strong> · 988 Suicide &amp; Crisis Lifeline. All are free and open 24/7.</div></div>\\r\\n</section>\\r\\n<section class=\\"reader-section vocab-section\\">\\r\\n  <h3>Chapter Vocabulary</h3>\\r\\n  <div class=\\"vocab-table\\">\\r\\n                <div><strong>Siblings</strong><span>Brothers and sisters.</span></div>\\r\\n                <div><strong>Nuclear family</strong><span>Two parents and one or more children living in the same home.</span></div>\\r\\n                <div><strong>Blended family</strong><span>A family formed when a single parent remarries, bringing together children from previous relationships.</span></div>\\r\\n                <div><strong>Extended family</strong><span>A family that includes relatives beyond parents and children, such as grandparents, aunts, uncles and cousins.</span></div>\\r\\n                <div><strong>Foster care</strong><span>The temporary placement of children in the homes of adults who are not related to them.</span></div>\\r\\n                <div><strong>Affirmation</strong><span>Positive feedback that helps others feel appreciated and supported.</span></div>\\r\\n                <div><strong>Separation</strong><span>A decision by two married people to live apart from each other.</span></div>\\r\\n                <div><strong>Divorce</strong><span>A legal end to a marriage contract.</span></div>\\r\\n                <div><strong>Custody</strong><span>The legal right to make decisions affecting children and the responsibility for their care.</span></div>\\r\\n                <div><strong>Abuse</strong><span>The physical, mental, emotional, or sexual mistreatment of one person by another.</span></div>\\r\\n                <div><strong>Domestic violence</strong><span>Acts of violence or abuse involving family members.</span></div>\\r\\n                <div><strong>Spousal abuse</strong><span>Domestic violence or abuse directed at a spouse or partner.</span></div>\\r\\n                <div><strong>Child abuse</strong><span>Domestic abuse directed at a child, including physical, emotional, or sexual harm.</span></div>\\r\\n                <div><strong>Neglect</strong><span>The failure to provide for a child&#x27;s basic needs.</span></div>\\r\\n                <div><strong>Elder abuse</strong><span>The abuse or neglect of older family members.</span></div>\\r\\n                <div><strong>Cycle of violence</strong><span>The pattern of repeating violent or abusive behaviors from one generation to the next.</span></div>\\r\\n                <div><strong>Crisis center</strong><span>A facility that offers advice and support to people dealing with personal emergencies.</span></div>\\r\\n  </div>\\r\\n</section>","vocabGames":[{"href":"/vocab_engine.html?ch=7","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 7 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=7#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=7#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 7 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=7#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=7","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 7 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🗣","title":"Side Quest — Family Interview","desc":"Interview a family member (parent, grandparent, or guardian) about a challenge their family faced and how they got through it. What did they learn? What made them stronger? Write a one-page reflection on what you discovered.","tags":[{"text":"Solo","kind":""},{"text":"~25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📰","title":"Exploration — Families Under Stress","desc":"Find a statistic or news story about a challenge facing families today — financial stress, divorce, caregiving, or blended family dynamics. What community resources exist to help? Are they accessible to families in your area?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"💭","title":"Challenge — Communication Audit","desc":"Identify one communication habit in your family that strengthens your relationships and one that creates tension. Based on what you learned in Chapter 7, write a specific plan for how YOU could help improve the tension point.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_match.html","icon":"🧠","title":"Sprite Memory","desc":"Match healthy pairs before time runs out"},{"href":"/dopp_wordle.html","icon":"🔤","title":"Word Quest","desc":"Guess the 5-letter health word"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":8,"realmTag":"Realm III — Relationship Realm","title":"Peer Relationships","sub":"Friends shape your choices more than almost anything else in your teen years. Learn what makes a friendship healthy, how to stay safe online, how to say no to pressure without losing friends, and how to set limits in dating.","meta":[{"icon":"📅","label":"Days","value":"Day 16"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Social Champion"}],"lessons":["L1: Safe and Healthy Friendships","L2: Peer Pressure and Refusal Skills","L3: Practicing Abstinence"],"pdf":"/Chapter_08_Peer_Relationships.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n  <h3>Lesson 1 — Safe and Healthy Friendships</h3>\\r\\n  <h4>Types of Friendships</h4>\\r\\n  <p>Your <em>peers</em>, people your age with similar interests, have a powerful influence on your health. Strong friendships share similar values, honest communication, mutual respect, concern for each other\'s safety, and sharing of joys and disappointments.</p>\\r\\n  <div class=\\"reading-grid compact\\">\\r\\n    <div class=\\"reading-tile\\"><h3>Casual</h3><p>Built on shared interests without deep emotional bonds. You enjoy each other but don\'t always confide.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Close</h3><p>Deep emotional ties. You can share thoughts, feelings and struggles without judgment.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Platonic</h3><p>A friendship with someone of a different gender, with real affection but no romance.</p></div>\\r\\n  </div>\\r\\n  <h4>Online Friendships — Stay Safe</h4>\\r\\n  <ul class=\\"reader-checklist\\">\\r\\n    <li>Never share your full name, address, phone number or school.</li>\\r\\n    <li>Don\'t send photos to people you haven\'t met in person.</li>\\r\\n    <li>Never meet an online contact alone. Always tell a trusted adult first.</li>\\r\\n    <li>If someone online makes you uncomfortable, tell an adult right away.</li>\\r\\n    <li>Be careful in gaming chats, social media DMs and apps that connect you with strangers.</li>\\r\\n  </ul>\\r\\n  <div class=\\"reading-callout\\"><div class=\\"callout-label\\">Key Idea</div><div>A <em>clique</em> can feel like belonging, but it often comes with pressure to conform and to leave others out. Healthy friendships expand your world. They don\'t shrink it.</div></div>\\r\\n</section>\\r\\n<section class=\\"reader-section\\">\\r\\n  <h3>Lesson 2 — Peer Pressure and Refusal Skills</h3>\\r\\n  <h4>What Is Peer Pressure?</h4>\\r\\n  <p><em>Peer pressure</em> is the influence people your age have on your actions and decisions. It can be direct or subtle. Not all of it is bad: positive peer pressure can push you to try new activities, volunteer, work harder and avoid risky behavior.</p>\\r\\n  <p>Negative pressure can show up as <em>harassment</em> (repeatedly targeting someone) or <em>manipulation</em> (indirect, dishonest control through guilt trips, threats, flattery or bribes).</p>\\r\\n  <h4>Three Refusal Steps</h4>\\r\\n  <ul class=\\"reader-list\\">\\r\\n    <li><strong>1. State your position.</strong> Say no clearly and firmly, with an honest reason: \\"It goes against my values.\\" Use confident body language.</li>\\r\\n    <li><strong>2. Suggest alternatives.</strong> \\"No, let\'s go to the movies instead.\\" You stay connected without giving up your values.</li>\\r\\n    <li><strong>3. Stand your ground.</strong> If the pressure keeps coming, make it clear you won\'t budge. Walking away is always an option.</li>\\r\\n  </ul>\\r\\n  <div class=\\"reading-callout\\"><div class=\\"callout-label\\">Try This</div><div>Practice your refusals out loud before you\'re in a high-pressure moment. It\'s much easier to hold your ground when you already know what you\'ll say.</div></div>\\r\\n</section>\\r\\n<section class=\\"reader-section\\">\\r\\n  <h3>Lesson 3 — Practicing Abstinence</h3>\\r\\n  <h4>Dating and Setting Limits</h4>\\r\\n  <p>Dating can be a positive experience when both people respect each other. The most important limit you can set is <em>abstinence</em>: a deliberate decision to avoid high-risk behaviors, including sexual activity and the use of alcohol, tobacco and other drugs. <em>Self-control</em> means letting your values, not the emotions of the moment, guide your choices.</p>\\r\\n  <h4>Why Abstinence Matters</h4>\\r\\n  <div class=\\"reading-grid compact\\">\\r\\n    <div class=\\"reading-tile\\"><h3>Unplanned pregnancy</h3><p>Teen birth rates are at a record low, but an unplanned pregnancy still changes the course of thousands of young lives every year.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>STIs</h3><p>People ages 15–24 are about 13% of the population but have nearly half of new STIs. Abstinence is the only 100% effective protection.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Emotional risks</h3><p>Hurt, guilt, loss of self-respect and regret are common when teens aren\'t ready for a sexual relationship.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Media pressure</h3><p>Shows and social media glamorize sex without showing consequences. That\'s entertainment, not reality.</p></div>\\r\\n  </div>\\r\\n  <h4>Handling Pressure Lines</h4>\\r\\n  <ul class=\\"reader-list\\">\\r\\n    <li>\\"Everybody does it.\\" → \\"No. Not everybody is doing it.\\"</li>\\r\\n    <li>\\"No one will know.\\" → \\"I\'ll know, and I\'m the one who matters.\\"</li>\\r\\n    <li>\\"If you loved me, you\'d do it.\\" → \\"If you loved me, you\'d respect my decision.\\"</li>\\r\\n  </ul>\\r\\n  <div class=\\"reading-callout\\"><div class=\\"callout-label\\">Key Idea</div><div>It\'s never too late. Anyone can choose abstinence going forward, and it\'s a positive choice that protects your health and future.</div></div>\\r\\n</section>\\r\\n<section class=\\"reader-section vocab-section\\">\\r\\n  <h3>Chapter Vocabulary</h3>\\r\\n  <div class=\\"vocab-table\\">\\r\\n                <div><strong>Peers</strong><span>People your age who share similar interests.</span></div>\\r\\n                <div><strong>Platonic friendship</strong><span>A friendship with someone of a different gender involving genuine affection, but without romantic involvement.</span></div>\\r\\n                <div><strong>Clique</strong><span>A small circle of friends who exclude people viewed as outsiders.</span></div>\\r\\n                <div><strong>Peer pressure</strong><span>The influence that people your age may have on your actions and behaviors.</span></div>\\r\\n                <div><strong>Harassment</strong><span>Persistently annoying or targeting others through hurtful behaviors like name-calling, teasing, or bullying.</span></div>\\r\\n                <div><strong>Manipulation</strong><span>An indirect, dishonest way to control or influence other people.</span></div>\\r\\n                <div><strong>Refusal skills</strong><span>Communication strategies that help you say no when urged to take part in unsafe or unhealthy behaviors.</span></div>\\r\\n                <div><strong>Priorities</strong><span>The goals, tasks, values, and activities you judge to be most important.</span></div>\\r\\n                <div><strong>Intimacy</strong><span>A closeness between two people that develops over time through genuine connection and trust.</span></div>\\r\\n                <div><strong>Infatuation</strong><span>Exaggerated feelings of intense passion that can feel overwhelming but are often short-lived.</span></div>\\r\\n                <div><strong>Abstinence</strong><span>A deliberate decision to avoid high-risk behaviors, including sexual activity and the use of alcohol, tobacco, and other drugs.</span></div>\\r\\n                <div><strong>Self-control</strong><span>The ability to use responsibility and values to override emotions in the moment.</span></div>\\r\\n                <div><strong>Sexually transmitted infections (STIs)</strong><span>Infectious diseases spread from person to person through sexual contact.</span></div>\\r\\n  </div>\\r\\n</section>","vocabGames":[{"href":"/vocab_engine.html?ch=8","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 8 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=8#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=8#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 8 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=8#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=8","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 8 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🎭","title":"Side Quest — Refusal Skills Role-Play","desc":"With a partner, act out three pressure situations (a party, a dare at school, an online request). Use the three refusal steps: state your position, suggest an alternative, stand your ground. Switch roles, then write down the line that worked best for you.","tags":[{"text":"Partner","kind":"team"},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"🔎","title":"Exploration — Positive Peer Pressure","desc":"Find a real example of positive peer pressure, like a team, club, or online challenge that pushed people toward healthy choices. What made it work? How could your friend group create positive pressure this week?","tags":[{"text":"Team","kind":"team"},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🧭","title":"Challenge — My Priorities & Limits","desc":"List your top five priorities. Then write the limits you will keep in friendships, online, and in dating to protect them. Add one sentence you will use if someone pressures you to cross a limit.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/habit_showdown.html","icon":"⚖️","title":"Habit Showdown","desc":"Good habit or bad? Myth or fact?"},{"href":"/dopp_dunk.html","icon":"🏀","title":"Sprite Hoops","desc":"Shoot bad habits into the trash"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":9,"realmTag":"Realm III — Relationship Realm","title":"Resolving Conflicts and Preventing Violence","sub":"Conflict is a normal part of life, but violence never has to be. Learn what makes conflicts escalate, how to negotiate and mediate, how to spot and stop bullying and violence, and how to recognize an abusive relationship.","meta":[{"icon":"📅","label":"Days","value":"17–18"},{"icon":"📖","label":"Lessons","value":"4"},{"icon":"🏆","label":"Badge","value":"Social Champion"}],"lessons":["L1: Causes of Conflict","L2: Resolving Conflicts","L3: Understanding Violence","L4: Preventing and Overcoming Abuse"],"pdf":"/Chapter_09_Resolving_Conflicts_and_Preventing_Violence.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n  <h3>Lesson 1 — Causes of Conflict</h3>\\r\\n  <p>A <em>conflict</em> is any disagreement, struggle or fight. Because people are different, conflicts are a normal part of life. The goal is to manage them before they get out of hand. Handled well, conflicts can actually make relationships stronger.</p>\\r\\n  <h4>Common Causes</h4>\\r\\n  <div class=\\"reading-grid compact\\">\\r\\n    <div class=\\"reading-tile\\"><h3>Misunderstandings</h3><p>Two people read the same thing differently, especially across backgrounds, cultures or ages.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Power struggles</h3><p>Who gets to make the decisions or set the rules.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Jealousy &amp; envy</h3><p>Feeling left behind or replaced.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Property disputes</h3><p>Arguments over borrowed or damaged belongings.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Conflicting values</h3><p>Different beliefs about how people should act.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Lack of respect</h3><p>Rudeness, prejudice or treating someone as less than equal.</p></div>\\r\\n  </div>\\r\\n  <div class=\\"reading-callout\\"><div class=\\"callout-label\\">Key Idea</div><div>The feelings most likely to make a conflict <em>escalate</em> (get more serious) are hurt pride, embarrassment and the desire for revenge. Noticing them in yourself is one of the best ways to prevent violence.</div></div>\\r\\n</section>\\r\\n<section class=\\"reader-section\\">\\r\\n  <h3>Lesson 2 — Resolving Conflicts</h3>\\r\\n  <h4>Negotiation, Step by Step</h4>\\r\\n  <ul class=\\"reader-list\\">\\r\\n    <li><strong>1. Calm down first.</strong> Never negotiate while emotions are too hot to think clearly.</li>\\r\\n    <li><strong>2. Each side explains.</strong> Use \\"I\\" messages (\\"I feel… when… because…\\") and active listening. No interrupting.</li>\\r\\n    <li><strong>3. Ask clarifying questions</strong> so both sides really understand each other.</li>\\r\\n    <li><strong>4. Brainstorm solutions</strong> without judging them yet.</li>\\r\\n    <li><strong>5. Weigh the pros and cons</strong> together.</li>\\r\\n    <li><strong>6. Agree on a solution.</strong> Aim for win-win, or the best compromise.</li>\\r\\n    <li><strong>7. Follow up</strong> later to see if it worked.</li>\\r\\n  </ul>\\r\\n  <h4>Mediation and Peer Mediation</h4>\\r\\n  <p>When negotiating isn\'t enough, <em>mediation</em> brings in a neutral third party. In <em>peer mediation</em>, trained students help classmates settle conflicts. The keys are neutrality, <em>confidentiality</em> and clear ground rules.</p>\\r\\n  <div class=\\"reading-callout\\"><div class=\\"callout-label\\">Important</div><div>Peer mediation is NOT for situations involving violence, weapons or crimes. Those go to school administrators or law enforcement.</div></div>\\r\\n</section>\\r\\n<section class=\\"reader-section\\">\\r\\n  <h3>Lesson 3 — Understanding Violence</h3>\\r\\n  <p><em>Violence</em> is the threatened or actual use of physical force to harm a person or damage property. Uncontrolled anger, the need to control others, prejudice and revenge all contribute. Alcohol and drugs make violence more likely because they lower inhibitions and impair judgment.</p>\\r\\n  <div class=\\"reading-callout\\"><div class=\\"callout-label\\">Firearm Safety</div><div>Guns are now the leading cause of death for U.S. children and teens. Teens who carry guns are more likely to be hurt by one. Don\'t carry a weapon. Guns at home should be stored unloaded and locked.</div></div>\\r\\n  <h4>Types of Violence</h4>\\r\\n  <div class=\\"reading-grid compact\\">\\r\\n    <div class=\\"reading-tile\\"><h3>Assault</h3><p>An unlawful physical attack or threat of attack. About half happen between people who know each other.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>School threats</h3><p>Know your school\'s emergency plan. Report threats, even ones that sound like jokes. Speaking up saves lives.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Sexual violence</h3><p>Any unwelcome sexual contact. Most victims are under 18.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Hate crimes</h3><p>Crimes motivated by hatred of a group because of race, religion, disability, sexual orientation or other traits.</p></div>\\r\\n  </div>\\r\\n  <h4>Bullying and Cyberbullying</h4>\\r\\n  <p>Bullying is repeated, deliberate hurtful behavior where one side has more power. Cyberbullying happens through texts, social media and games, and it can follow you home. Don\'t respond or retaliate. Save the evidence, block the person, and tell a trusted adult. When you see it happen, be an <strong>upstander</strong>: speak up, support the target, or get help.</p>\\r\\n</section>\\r\\n<section class=\\"reader-section\\">\\r\\n  <h3>Lesson 4 — Preventing and Overcoming Abuse</h3>\\r\\n  <h4>Warning Signs of an Abusive Relationship</h4>\\r\\n  <ul class=\\"reader-checklist\\">\\r\\n    <li>Pressures you into sexual activity</li>\\r\\n    <li>Pushes the relationship to be serious or exclusive very fast</li>\\r\\n    <li>Acts jealous or possessive, controlling where you go or who you see</li>\\r\\n    <li>Yells, swears or attacks you emotionally</li>\\r\\n    <li>Threatens physical violence</li>\\r\\n  </ul>\\r\\n  <div class=\\"reading-callout\\"><div class=\\"callout-label\\">Key Idea</div><div>Controlling behavior is NOT love. These are warning signs of abuse, not signs of caring.</div></div>\\r\\n  <h4>Forms of Abuse</h4>\\r\\n  <div class=\\"reading-grid compact\\">\\r\\n    <div class=\\"reading-tile\\"><h3>Physical</h3><p>Hitting, kicking, shoving, biting or throwing things.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Emotional</h3><p>Verbal abuse, humiliation, threats or isolating someone from friends and family.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Sexual</h3><p>Any unwanted sexual contact or pressure.</p></div>\\r\\n    <div class=\\"reading-tile\\"><h3>Stalking</h3><p>Repeatedly following, harassing or threatening someone, in person or online.</p></div>\\r\\n  </div>\\r\\n  <p>About 1 in 9 high school girls reports sexual violence by a dating partner. Alcohol is a major factor, and some attackers use date rape drugs. Never leave your drink unattended, and don\'t finish a drink that smells or tastes strange.</p>\\r\\n  <div class=\\"reading-callout\\"><div class=\\"callout-label\\">Get Help</div><div>RAINN Sexual Assault Hotline: <strong>1-800-656-4673</strong> · love is respect (teen dating abuse): text LOVEIS to 22522 · 988 Suicide &amp; Crisis Lifeline. Survivors deserve support, not shame. Abuse is never the victim\'s fault.</div></div>\\r\\n</section>\\r\\n<section class=\\"reader-section vocab-section\\">\\r\\n  <h3>Chapter Vocabulary</h3>\\r\\n  <div class=\\"vocab-table\\">\\r\\n                <div><strong>Conflict</strong><span>Any disagreement, struggle, or fight.</span></div>\\r\\n                <div><strong>Interpersonal conflicts</strong><span>Conflicts between two or more people or groups.</span></div>\\r\\n                <div><strong>Escalate</strong><span>To become more serious or intense.</span></div>\\r\\n                <div><strong>Negotiation</strong><span>The use of communication and compromise to settle a disagreement.</span></div>\\r\\n                <div><strong>Mediation</strong><span>Bringing in a neutral third party to help others resolve their conflicts peacefully.</span></div>\\r\\n                <div><strong>Confidentiality</strong><span>Respecting the privacy of both parties and keeping details of a discussion secret.</span></div>\\r\\n                <div><strong>Peer mediation</strong><span>A process in which specially trained students help other students resolve conflicts peacefully.</span></div>\\r\\n                <div><strong>Violence</strong><span>The threatened or actual use of physical force or power to harm another person or damage property.</span></div>\\r\\n                <div><strong>Assault</strong><span>An unlawful physical attack or threat of attack.</span></div>\\r\\n                <div><strong>Random violence</strong><span>Violence committed for no particular reason against an unrelated victim.</span></div>\\r\\n                <div><strong>Homicide</strong><span>The willful killing of one human being by another.</span></div>\\r\\n                <div><strong>Sexual violence</strong><span>Any form of unwelcome sexual contact directed at an individual.</span></div>\\r\\n                <div><strong>Bullying</strong><span>Repeated, deliberate hurtful behavior by someone who has more power than the target.</span></div>\\r\\n                <div><strong>Cyberbullying</strong><span>Bullying that happens through phones, social media, games, or other technology.</span></div>\\r\\n                <div><strong>Physical abuse</strong><span>A pattern of intentionally causing bodily harm or injury to another person.</span></div>\\r\\n                <div><strong>Emotional abuse</strong><span>A pattern of attacking another person&#x27;s emotional development and sense of worth.</span></div>\\r\\n                <div><strong>Verbal abuse</strong><span>The use of words to mistreat or injure another person; a form of emotional abuse.</span></div>\\r\\n                <div><strong>Stalking</strong><span>Repeatedly following, harassing, or threatening an individual in person or online.</span></div>\\r\\n  </div>\\r\\n</section>","vocabGames":[{"href":"/vocab_engine.html?ch=9","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 9 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=9#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=9#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 9 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=9#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=9","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 9 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🧩","title":"Side Quest — I-Message Workshop","desc":"Rewrite 5 aggressive or passive statements as effective I-messages using the \'I feel... when... because...\' format. Then identify one real conflict in your life where an I-message could change the outcome.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"🕊","title":"Exploration — Prevention Program Analysis","desc":"Find a news story or study about a school or community violence prevention or peer mediation program. What strategies did they use? What were the outcomes? Could it work in your school? Be specific.","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🛡","title":"Challenge — Upstander Scenario","desc":"Describe a realistic scenario where you witness bullying or harassment. Write out exactly what you would say and do as an upstander. What obstacles might stop you — and how do you push past them? Be honest and specific.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_corner.html","icon":"👑","title":"Sprite Dodge","desc":"Out-dodge King Junk for 60 seconds"},{"href":"/dopp_kong.html","icon":"🧗","title":"Sprite Climb","desc":"Climb past rolling junk food"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":10,"realmTag":"Realm IV — Nourish Dungeon","title":"Nutrition for Health","sub":"You are literally built from what you eat. Understanding the six essential nutrients, how to read a label, and how to use MyPlate gives you real power over your long-term health.","meta":[{"icon":"📅","label":"Days","value":"17–20"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Body Warrior"}],"lessons":["L1: Nutrients","L2: Guidelines for Healthy Eating","L3: Making Healthy Food Choices"],"pdf":"/Chapter_10_Nutrition_for_Health.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Nutrients Your Body Needs</h3>\\r\\n              <h4>The Six Classes of Nutrients</h4>\\r\\n              <p>Nutrients are substances in food that your body needs to grow, repair itself, and function. There are six classes of nutrients, and a healthy diet includes all of them in the right amounts.</p>\\r\\n              <div class=\\"reading-grid compact\\">\\r\\n                <div class=\\"reading-tile\\"><h3>Carbohydrates</h3><p>Your body\'s primary fuel source. Choose whole grains, fruits, and vegetables over refined sugars and white flour.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Proteins</h3><p>Build and repair tissues, make enzymes and hormones. Sources: meat, fish, eggs, beans, nuts, dairy.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Fats</h3><p>Essential for brain function, hormone production, and absorbing fat-soluble vitamins. Choose unsaturated fats; limit saturated and avoid trans fats.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Vitamins</h3><p>Organic compounds needed in small amounts for many body processes. Fat-soluble (A, D, E, K) and water-soluble (B, C).</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Minerals</h3><p>Inorganic elements like calcium, iron, potassium. Essential for bone health, blood production, and nerve function.</p></div>\\r\\n                <div class=\\"reading-tile\\"><h3>Water</h3><p>Involved in every body process. Teens need 8–11 cups daily. Even mild dehydration impairs focus and performance.</p></div>\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — MyPlate and Dietary Guidelines</h3>\\r\\n              <p>The USDA\'s MyPlate model replaces the old food pyramid and provides a simpler visual guide for building a healthy plate at each meal.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <div class=\\"callout-label\\">MyPlate at a Glance</div>\\r\\n                <div>Half your plate: fruits and vegetables. A quarter: grains (make half whole grains). A quarter: protein. Add a serving of dairy on the side. Drink water instead of sugary drinks.</div>\\r\\n              </div>\\r\\n              <h4>2020–2025 Dietary Guidelines Key Points</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Follow a healthy dietary pattern at every life stage</li>\\r\\n                <li>Limit added sugars to less than 10% of daily calories</li>\\r\\n                <li>Limit sodium to less than 2,300 mg per day</li>\\r\\n                <li>Limit saturated fats to less than 10% of daily calories</li>\\r\\n                <li>Avoid alcohol if under 21</li>\\r\\n              </ul>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Reading Food Labels</h3>\\r\\n              <p>Food labels are your most powerful nutrition tool. Learning to read them takes about 5 minutes — and it changes how you shop and eat forever.</p>\\r\\n              <h4>Key Parts of the Nutrition Facts Label</h4>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Serving size:</strong> Everything on the label is based on this amount. Always check — one \\"bag\\" may be 2.5 servings.</li>\\r\\n                <li><strong>Calories:</strong> Total energy per serving. 2,000/day is the general reference.</li>\\r\\n                <li><strong>% Daily Value:</strong> 5% or less is low; 20% or more is high. Use this to compare products.</li>\\r\\n                <li><strong>Nutrients to limit:</strong> Saturated fat, sodium, added sugars.</li>\\r\\n                <li><strong>Nutrients to get enough of:</strong> Fiber, vitamin D, calcium, iron, potassium.</li>\\r\\n                <li><strong>Ingredients list:</strong> Listed by weight — if sugar is first, it\'s the main ingredient.</li>\\r\\n              </ul>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Healthy Eating Patterns</h3>\\r\\n              <p>The goal is not a perfect diet — it is a sustainable pattern of eating that gives your body what it needs most of the time.</p>\\r\\n              <h4>Eating Well as a Teen</h4>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Eat breakfast — teens who eat breakfast have better concentration, grades, and mood</li>\\r\\n                <li>Choose whole foods over processed — fewer ingredients, more nutrients</li>\\r\\n                <li>Watch portion sizes — restaurant portions are often 2–3x the recommended serving</li>\\r\\n                <li>Limit ultra-processed foods — chips, fast food, packaged snacks are engineered to override your hunger signals</li>\\r\\n                <li>Hydrate with water first — most Americans are chronically mildly dehydrated</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\">\\r\\n                <strong>The 80/20 Rule</strong>\\r\\n                <span>Eating nutritiously 80% of the time while leaving room for enjoyment 20% of the time is far more sustainable — and healthier — than trying to be perfect and giving up.</span>\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Nutrients</strong><span>Substances in food that the body needs to grow, repair itself, and function properly.</span></div>\\r\\n                <div><strong>Carbohydrates</strong><span>The body\'s main source of energy; found in grains, fruits, vegetables, and dairy.</span></div>\\r\\n                <div><strong>Proteins</strong><span>Nutrients that build and repair body tissues and make enzymes and hormones.</span></div>\\r\\n                <div><strong>Fats</strong><span>Nutrients that provide energy, support brain function, and help absorb vitamins.</span></div>\\r\\n                <div><strong>Vitamins</strong><span>Organic compounds needed in small amounts to support body processes.</span></div>\\r\\n                <div><strong>Minerals</strong><span>Inorganic elements like calcium and iron essential for bone health and body functions.</span></div>\\r\\n                <div><strong>Calorie</strong><span>A unit of energy that measures how much energy food provides to the body.</span></div>\\r\\n                <div><strong>Dietary guidelines</strong><span>Science-based advice from the USDA and HHS on what to eat and drink to promote health.</span></div>\\r\\n                <div><strong>MyPlate</strong><span>The USDA\'s food guidance model showing the five food groups and their proportions on a plate.</span></div>\\r\\n                <div><strong>Fiber</strong><span>A type of carbohydrate the body cannot digest; promotes digestive health and reduces disease risk.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=10","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 10 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=10#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=10#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 10 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=10#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=10","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 10 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"Nutrition Label Showdown","desc":"Bring in 3 food packages from home. Analyze each label: calories, serving size, % Daily Values, added sugar, and saturated fat. Rank them and defend your choices to the class.","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"🔍","title":"Nutrition in the News","desc":"Find a recent news story about food, diet, or nutrition research. What is the claim? Is it supported by peer-reviewed science or is it just a trend? Present your findings.","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"3-Day MyPlate Tracker","desc":"Log everything you eat and drink for 3 full days. Compare your intake to MyPlate recommendations. Which food groups are you over or under? Write a one-page reflection.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_drop.html","icon":"🧺","title":"Sprite Catch","desc":"Catch fruits and veggies, dodge the junk"},{"href":"/dopp_tetris.html","icon":"🟦","title":"Snack Stack","desc":"Stack healthy snacks, clear lines"},{"href":"/dopp_snake.html","icon":"🐍","title":"Sprite Snake","desc":"Grow on fruit and veggies"},{"href":"/cup_pong.html","icon":"🏓","title":"Cup Pong","desc":"Dump 10 cups of sugary drinks"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":11,"realmTag":"Realm IV — Nourish Dungeon","title":"Managing Weight","sub":"Body image is one of the most powerful health forces in a teen\'s life. This chapter covers the science of healthy weight, the reality of eating disorders, and how to build a healthy relationship with food and your body.","meta":[{"icon":"📅","label":"Days","value":"19–22"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Body Warrior"}],"lessons":["L1: Maintaining a Healthy Weight","L2: Body Image","L3: Eating Disorders"],"pdf":"/Chapter_11_Managing_Weight_and_Eating_Behaviors.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Weight, Health &amp; Body Image</h3>\\r\\n              <p>Healthy weight is about more than a number on the scale. <strong>Body composition</strong> — the ratio of fat to lean tissue — is a more meaningful measure of health. Factors like genetics, metabolism, age, and activity level all influence where your body settles.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Body Image vs. Body Reality</strong><br>\\r\\n                Body image is how you <em>see</em> yourself, which often differs from reality. Media, social comparison, and peer pressure can distort body image and lead to unhealthy behaviors.\\r\\n              </div>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Underweight</strong><span>BMI below 18.5; may signal nutritional deficiency or eating disorder</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Healthy Weight</strong><span>BMI 18.5–24.9; associated with lower disease risk</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Overweight</strong><span>BMI 25–29.9; increased risk for chronic conditions</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Obese</strong><span>BMI 30+; significantly elevated health risk</span></div>\\r\\n              </div>\\r\\n              <p>BMI is a useful screening tool but doesn\'t directly measure body fat — athletes may have high BMI with low fat. Healthcare providers use BMI alongside other assessments for a complete picture.</p>\\r\\n              <div class=\\"reading-check\\">\\r\\n                <strong>Quick Check:</strong> Why isn\'t BMI always an accurate measure of an individual\'s health?\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Achieving &amp; Maintaining a Healthy Weight</h3>\\r\\n              <p>Weight management is about balance — <strong>energy in</strong> (calories consumed) vs. <strong>energy out</strong> (calories burned). No single diet or trick achieves lasting results; sustainable habits make the difference.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Set realistic goals</strong> — aim for 0.5–1 lb per week, not crash losses</li>\\r\\n                <li><strong>Eat mindfully</strong> — recognize hunger cues, avoid emotional eating</li>\\r\\n                <li><strong>Move consistently</strong> — 60 min daily activity for teens (CDC)</li>\\r\\n                <li><strong>Sleep enough</strong> — poor sleep raises hunger hormones and fat storage</li>\\r\\n                <li><strong>Limit ultra-processed foods</strong> — high in calories, low in nutrients</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Fad Diets Warning</strong><br>\\r\\n                Extreme or fad diets promise fast results but often cause muscle loss, nutritional deficiencies, and weight regain. Evidence-based approaches focus on gradual change and overall lifestyle.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\">\\r\\n                <strong>Quick Check:</strong> What does \\"energy balance\\" mean, and why does it matter for weight management?\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Eating Disorders</h3>\\r\\n              <p>Eating disorders are serious mental health conditions involving disordered eating behaviors that harm physical and emotional health. They affect all genders, ages, and body types.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Anorexia Nervosa</strong><span>Extreme restriction of food; distorted body image; fear of weight gain</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Bulimia Nervosa</strong><span>Cycles of bingeing then purging; often done in secret</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Binge Eating Disorder</strong><span>Frequent episodes of eating large amounts without purging; most common eating disorder</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Orthorexia</strong><span>Obsessive focus on \\"clean\\" or \\"pure\\" eating to the point of harm</span></div>\\r\\n              </div>\\r\\n              <p>Warning signs include dramatic weight changes, obsession with food/body, avoiding meals, or mood changes around eating. Early intervention dramatically improves outcomes.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Treatment involves medical, nutritional, and psychological support</li>\\r\\n                <li>Recovery is possible — most people improve with professional care</li>\\r\\n                <li>Avoid diet talk and body shaming around peers — it can trigger disorders</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\">\\r\\n                <strong>Quick Check:</strong> Name two warning signs of an eating disorder a concerned friend might notice.\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Building a Positive Relationship with Food</h3>\\r\\n              <p>A healthy relationship with food means eating for nourishment and enjoyment — not guilt or fear. <strong>Intuitive eating</strong> encourages tuning into hunger and fullness cues rather than rigid rules.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>All Foods Fit Principle</strong><br>\\r\\n                Labeling foods as \\"good\\" or \\"bad\\" creates guilt and shame. Balance, variety, and moderation allow for occasional treats without derailing overall health.\\r\\n              </div>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Eat regular meals — skipping leads to overeating later</li>\\r\\n                <li>Focus on how food makes you <em>feel</em>, not just calories</li>\\r\\n                <li>Cook and share meals — social eating supports mental health</li>\\r\\n                <li>Challenge media messages about \\"perfect\\" bodies</li>\\r\\n              </ul>\\r\\n              <p>If you or someone you know struggles with eating behaviors, reach out to a trusted adult, school counselor, or the National Alliance for Eating Disorders helpline (1-866-662-1235, weekdays).</p>\\r\\n              <div class=\\"reading-check\\">\\r\\n                <strong>Quick Check:</strong> What is intuitive eating, and how does it differ from dieting?\\r\\n              </div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Body composition</strong><span>The ratio of fat mass to lean (muscle, bone, water) mass in the body.</span></div>\\r\\n                <div><strong>BMI (Body Mass Index)</strong><span>A screening tool calculated from height and weight used to estimate body fat levels.</span></div>\\r\\n                <div><strong>Caloric balance</strong><span>The relationship between calories consumed through food and calories burned through activity.</span></div>\\r\\n                <div><strong>Metabolism</strong><span>The set of chemical processes that convert food into energy used by the body.</span></div>\\r\\n                <div><strong>Eating disorder</strong><span>A serious mental health condition involving abnormal or harmful eating behaviors.</span></div>\\r\\n                <div><strong>Anorexia nervosa</strong><span>An eating disorder characterized by severe food restriction and distorted body image.</span></div>\\r\\n                <div><strong>Bulimia nervosa</strong><span>An eating disorder involving cycles of binge eating followed by purging behaviors.</span></div>\\r\\n                <div><strong>Binge eating disorder</strong><span>Recurrent episodes of eating large amounts of food without compensatory purging.</span></div>\\r\\n                <div><strong>Body image</strong><span>How a person perceives and feels about their own physical appearance.</span></div>\\r\\n                <div><strong>Intuitive eating</strong><span>An approach to food that honors internal hunger and fullness cues rather than external diet rules.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=11","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 11 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=11#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=11#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 11 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=11#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=11","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 11 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"BMI Reality Check","desc":"Research BMI: what it measures, what it misses, and why health experts debate its usefulness. Write a short evidence-based critique — is BMI a good health tool for teens?","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"🔍","title":"Eating Disorder Awareness Research","desc":"Choose one eating disorder and research it in depth: warning signs, health consequences, treatment options, and why it often goes unrecognized. What can schools do better?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Media & Body Image Audit","desc":"Collect 3 ads or social media posts that promote unrealistic body standards. Analyze the hidden messages. How do these images affect teen health behaviors and self-esteem?","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_2048.html","icon":"🔢","title":"Snack 2048","desc":"Merge snacks up to the Healthy Heart"},{"href":"/sprite_slice.html","icon":"🔪","title":"Sprite Slice","desc":"Swipe fruit and veggies, skip the junk"},{"href":"/dopp_corner.html","icon":"👑","title":"Sprite Dodge","desc":"Out-dodge King Junk for 60 seconds"},{"href":"/cup_pong.html","icon":"🏓","title":"Cup Pong","desc":"Dump 10 cups of sugary drinks"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":12,"realmTag":"Realm IV — Nourish Dungeon","title":"Physical Activity","sub":"60 minutes of activity a day. That\'s all it takes to transform your cardiovascular health, mood, brain function, and sleep. This chapter teaches you how to build a plan that actually works.","meta":[{"icon":"📅","label":"Days","value":"21–22"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Body Warrior"}],"lessons":["L1: Physical Fitness","L2: Types of Activity","L3: Creating a Fitness Plan"],"pdf":"/Chapter_12_Physical_Activity_and_Fitness.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Benefits of Physical Activity</h3>\\r\\n              <p>Physical activity is any body movement that uses muscles and burns energy. Regular activity strengthens the heart, builds strong bones, improves mental health, and reduces chronic disease risk.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>CDC Recommendation</strong><br>\\r\\n                Teens should get at least <strong>60 minutes</strong> of moderate-to-vigorous physical activity every day, including aerobic, muscle-strengthening, and bone-strengthening activities.\\r\\n              </div>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Physical Benefits</strong><span>Stronger heart, lungs, muscles, bones; healthy weight; better sleep</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Mental Benefits</strong><span>Reduced anxiety/depression; better focus; improved self-esteem</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Social Benefits</strong><span>Teamwork, cooperation, friendship, belonging</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Academic Benefits</strong><span>Better concentration, memory, and classroom performance</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Name one physical and one mental benefit of regular physical activity.</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Types of Fitness</h3>\\r\\n              <p>Physical fitness has five health-related components and six skill-related components. Building all areas creates well-rounded fitness.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Cardiorespiratory endurance</strong> — heart/lung efficiency during sustained activity</li>\\r\\n                <li><strong>Muscular strength</strong> — maximum force a muscle can exert</li>\\r\\n                <li><strong>Muscular endurance</strong> — ability to repeat muscle contractions over time</li>\\r\\n                <li><strong>Flexibility</strong> — range of motion at joints</li>\\r\\n                <li><strong>Body composition</strong> — ratio of fat to lean tissue</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Skill-Related Fitness</strong><br>\\r\\n                Agility, balance, coordination, power, reaction time, and speed are skill-related components important for sports and daily movement.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the difference between muscular strength and muscular endurance?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — The FITT Principle</h3>\\r\\n              <p>The <strong>FITT principle</strong> guides how to design an effective fitness program. Each letter stands for a key variable:</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>F — Frequency</strong><span>How often you exercise (e.g., 5 days/week)</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>I — Intensity</strong><span>How hard you work (moderate vs. vigorous)</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>T — Time</strong><span>How long each session lasts (e.g., 30–60 min)</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>T — Type</strong><span>What kind of activity (running, swimming, lifting)</span></div>\\r\\n              </div>\\r\\n              <p>Applying FITT helps you progressively overload muscles — gradually increasing challenge so the body adapts and improves without injury.</p>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> How would you use the FITT principle to improve cardiorespiratory endurance?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Preventing Injuries &amp; Staying Safe</h3>\\r\\n              <p>Exercise-related injuries are common but largely preventable. Smart training habits protect your body for lifelong activity.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Always warm up (5–10 min light movement) and cool down (stretching)</li>\\r\\n                <li>Use proper form and technique — most injuries come from poor mechanics</li>\\r\\n                <li>Wear appropriate gear and footwear</li>\\r\\n                <li>Stay hydrated — drink water before, during, and after activity</li>\\r\\n                <li>Rest and recover — overtraining leads to fatigue and injury</li>\\r\\n                <li>Listen to your body — pain is a signal, not a badge of honor</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>RICE for Minor Injuries</strong><br>\\r\\n                Rest · Ice · Compression · Elevation — the first steps for sprains, strains, and minor injuries before seeking medical care.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What does RICE stand for and when would you use it?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Physical activity</strong><span>Any movement produced by skeletal muscles that requires energy expenditure.</span></div>\\r\\n                <div><strong>Physical fitness</strong><span>The ability to carry out daily tasks with vigor and without undue fatigue.</span></div>\\r\\n                <div><strong>Cardiorespiratory endurance</strong><span>The ability of the heart and lungs to supply oxygen to working muscles during sustained activity.</span></div>\\r\\n                <div><strong>Muscular strength</strong><span>The maximum force a muscle or muscle group can exert in a single effort.</span></div>\\r\\n                <div><strong>Muscular endurance</strong><span>The ability of a muscle to perform repeated contractions over time.</span></div>\\r\\n                <div><strong>Flexibility</strong><span>The ability of joints to move through their full range of motion.</span></div>\\r\\n                <div><strong>FITT principle</strong><span>A framework for fitness programming: Frequency, Intensity, Time, and Type.</span></div>\\r\\n                <div><strong>Progressive overload</strong><span>Gradually increasing the stress placed on the body during exercise to continue improving.</span></div>\\r\\n                <div><strong>Warm-up</strong><span>Light activity before exercise that prepares the body and reduces injury risk.</span></div>\\r\\n                <div><strong>Cool-down</strong><span>Gradual reduction in activity intensity after exercise to safely lower heart rate and stretch muscles.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=12","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 12 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=12#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=12#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 12 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=12#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=12","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 12 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"Personal FITT Plan","desc":"Using the FITT principle, design a realistic 4-week fitness plan for yourself. Specify Frequency, Intensity, Time, and Type for each week. Include warm-up and cool-down.","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"🔍","title":"Exercise Science in the News","desc":"Find a recent study or article on the health benefits of physical activity. What did researchers find? How was the study conducted? How strong is the evidence?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Fitness Component Self-Assessment","desc":"Test yourself on all 5 components of health-related fitness: cardiovascular endurance, muscle strength, muscle endurance, flexibility, and body composition. Where are your strengths and gaps?","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/field_day.html","icon":"🏅","title":"Field Day","desc":"5-event track meet"},{"href":"/sprite_run.html","icon":"🛕","title":"Sprite Run","desc":"Swipe past soda, grab fruit"},{"href":"/dopp_motomania.html","icon":"🏍️","title":"Sprite Rider","desc":"Hills, ramps and safe landings"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":13,"realmTag":"Realm V — Body Labyrinth","title":"Personal Health Care","sub":"Your body is constantly working to protect and maintain itself — but it needs your help. This chapter covers the practical daily habits that keep your skin, teeth, eyes, and ears healthy for life.","meta":[{"icon":"📅","label":"Days","value":"21–24"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"System Sage"}],"lessons":["L1: Skin, Hair, and Nails","L2: Teeth and Mouth","L3: Eyes and Ears"],"pdf":"/Chapter_13_Personal_Health_Care.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Skin, Hair &amp; Nail Care</h3>\\r\\n              <p>Your skin is the body\'s largest organ — a protective barrier against bacteria, UV radiation, and injury. Good hygiene preserves this barrier and prevents infection.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Daily Washing</strong><span>Use mild soap and warm water; face wash removes excess oil and prevents acne</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Sunscreen</strong><span>SPF 30+ daily protects against UV damage and skin cancer; reapply every 2 hours outdoors</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Hair Care</strong><span>Regular washing removes dirt and oils; brush gently to prevent breakage</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Nail Care</strong><span>Trim nails regularly; keep clean to prevent bacterial/fungal infections</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Acne Facts</strong><br>\\r\\n                Acne is caused by excess oil, dead skin cells, and bacteria clogging pores — not dirt. Hormones during puberty increase oil production. Gentle cleansing and non-comedogenic products help manage it.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why is daily sunscreen use important even on cloudy days?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Dental &amp; Eye Care</h3>\\r\\n              <p>Oral health affects your whole body — gum disease is linked to heart disease and diabetes. Eyes are equally important: regular exams catch problems early.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Brush</strong> twice daily with fluoride toothpaste for 2 minutes</li>\\r\\n                <li><strong>Floss</strong> once daily to remove plaque between teeth</li>\\r\\n                <li><strong>Dentist visits</strong> every 6 months for cleaning and exam</li>\\r\\n                <li><strong>Eye exams</strong> every 1–2 years; sooner if vision changes</li>\\r\\n                <li><strong>Screen time breaks</strong> — 20-20-20 rule: every 20 min, look 20 feet away for 20 seconds</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the 20-20-20 rule, and why is it helpful?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Healthcare &amp; Checkups</h3>\\r\\n              <p>Preventive care catches health problems before they become serious. Regular checkups, screenings, and vaccinations are cornerstones of good health maintenance.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Annual Physical Exam</strong><br>\\r\\n                A yearly checkup with your healthcare provider includes height/weight, blood pressure, vision/hearing screening, and immunization review. It\'s your chance to ask questions about your health.\\r\\n              </div>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Keep an updated health record: vaccinations, allergies, medications</li>\\r\\n                <li>Know your family health history — many conditions are hereditary</li>\\r\\n                <li>Be honest with your provider — confidentiality laws protect teens</li>\\r\\n                <li>Follow through on referrals to specialists</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why is preventive care important, even when you feel healthy?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Consumer Health &amp; Health Products</h3>\\r\\n              <p>Being a smart health consumer means critically evaluating products, services, and information before making decisions. Misinformation is widespread — especially online.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Red Flags</strong><span>\\"Miracle cures,\\" before/after photos, testimonials, no scientific evidence</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Trusted Sources</strong><span>CDC, WHO, Mayo Clinic, your healthcare provider</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>OTC Medications</strong><span>Follow label instructions; don\'t combine without checking interactions</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Health Insurance</strong><span>Covers medical costs; understand your plan\'s copays, deductibles, and network</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> How can you tell if a health product or claim is trustworthy?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Hygiene</strong><span>Practices that maintain cleanliness and prevent disease.</span></div>\\r\\n                <div><strong>Dermatologist</strong><span>A doctor who specializes in skin, hair, and nail conditions.</span></div>\\r\\n                <div><strong>Plaque</strong><span>A sticky film of bacteria that forms on teeth and can cause cavities and gum disease.</span></div>\\r\\n                <div><strong>Fluoride</strong><span>A mineral that strengthens tooth enamel and helps prevent decay.</span></div>\\r\\n                <div><strong>Preventive care</strong><span>Health services aimed at preventing disease before it occurs, including checkups and vaccinations.</span></div>\\r\\n                <div><strong>Immunization</strong><span>Protection from disease through vaccines that stimulate the immune system.</span></div>\\r\\n                <div><strong>Consumer health</strong><span>The evaluation of products, services, and information related to health.</span></div>\\r\\n                <div><strong>OTC medication</strong><span>Over-the-counter drugs available without a prescription.</span></div>\\r\\n                <div><strong>SPF</strong><span>Sun Protection Factor — a measure of how well sunscreen blocks UV radiation.</span></div>\\r\\n                <div><strong>Acne</strong><span>A skin condition caused by clogged pores resulting in pimples, blackheads, and whiteheads.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=13","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 13 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=13#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=13#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 13 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=13#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=13","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 13 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"ABCDE Melanoma Screening","desc":"Research the ABCDE rule for early melanoma detection. Find real clinical examples of each warning sign. What lifestyle factors increase your skin cancer risk as a teen?","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"🔍","title":"Teen Oral Health Statistics","desc":"Research current data on teen dental health in the U.S.: prevalence of cavities, gum disease, and the long-term cost of untreated dental problems. What barriers prevent teens from getting care?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Personal Health Habits Audit","desc":"Honestly audit your daily personal health habits: skin care and sun protection, dental hygiene, eye care, and ear health. Score yourself and write one specific improvement plan.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_pacman.html","icon":"🍎","title":"Sprite Maze","desc":"Collect water, dodge junk monsters"},{"href":"/dopp_breakout.html","icon":"🧱","title":"Habit Breaker","desc":"Smash a wall of bad habits"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":14,"realmTag":"Realm V — Body Labyrinth","title":"Skeletal, Muscular & Nervous Systems","sub":"Your skeleton is a living structure — it grows, heals, and responds to your daily choices. Your nervous system processes 11 million bits of information every second. This chapter reveals how the skeletal, muscular, and nervous systems work together and what threatens them.","meta":[{"icon":"📅","label":"Days","value":"23–26"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"System Sage"}],"lessons":["L1: The Skeletal System","L2: The Muscular System","L3: The Nervous System"],"pdf":"/Chapter_14_Skeletal_Muscular_and_Nervous_Systems.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — The Skeletal System</h3>\\r\\n              <p>The skeletal system is the body\'s framework — 206 bones that support structure, protect organs, enable movement, produce blood cells, and store minerals like calcium and phosphorus.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Axial Skeleton</strong><span>Skull, vertebral column, rib cage — protects brain, spinal cord, and vital organs</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Appendicular Skeleton</strong><span>Arms, legs, shoulder and hip girdles — enables locomotion</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Joints</strong><span>Where bones meet; types: ball-and-socket, hinge, pivot, gliding</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Bone Health</strong><span>Calcium + Vitamin D + weight-bearing exercise = strong bones throughout life</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Bone Growth</strong><br>\\r\\n                Bones grow at growth plates (epiphyseal plates) through childhood and adolescence. Peak bone mass is reached around age 30 — building strong bones now protects against osteoporosis later.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What two nutrients are most important for bone health, and how do you get them?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — The Muscular System</h3>\\r\\n              <p>The body has over 600 muscles of three types. Muscles work by contracting — shortening to pull bones or move substances through organs.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Skeletal muscle</strong> — voluntary; attached to bones; enables movement; striped appearance</li>\\r\\n                <li><strong>Smooth muscle</strong> — involuntary; lines organs like stomach and blood vessels</li>\\r\\n                <li><strong>Cardiac muscle</strong> — involuntary; found only in the heart; never fatigues</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Muscle Pairs</strong><br>\\r\\n                Muscles work in pairs — when one contracts (agonist), the opposing muscle relaxes (antagonist). Example: bicep contracts/tricep relaxes to flex the arm.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> How do the bicep and tricep work together to move the forearm?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — The Nervous System</h3>\\r\\n              <p>The nervous system is the body\'s communication network, controlling thought, movement, sensation, and automatic functions. It has two main divisions:</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Central Nervous System</strong><span>Brain + spinal cord; processes information and sends commands</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Peripheral Nervous System</strong><span>All other nerves; relays signals between CNS and body</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Somatic</strong><span>Voluntary control of skeletal muscles</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Autonomic</strong><span>Involuntary control of heart, digestion, breathing (sympathetic/parasympathetic)</span></div>\\r\\n              </div>\\r\\n              <p>Neurons are the basic units of the nervous system. They transmit electrical signals across synapses using chemical messengers called neurotransmitters.</p>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the difference between the central and peripheral nervous system?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Caring for Your Body Systems</h3>\\r\\n              <p>Lifestyle choices profoundly affect the health of skeletal, muscular, and nervous systems across a lifetime.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Weight-bearing exercise strengthens bones and builds muscle mass</li>\\r\\n                <li>Adequate calcium (1,300 mg/day for teens) and Vitamin D protect bones</li>\\r\\n                <li>Helmets and protective gear prevent traumatic brain injury (TBI)</li>\\r\\n                <li>Avoid tobacco — nicotine impairs nerve transmission and muscle recovery</li>\\r\\n                <li>Quality sleep allows the brain to consolidate memories and repair itself</li>\\r\\n                <li>Stretching maintains muscle flexibility and joint range of motion</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> How does wearing a helmet protect the nervous system?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Skeletal system</strong><span>The framework of 206 bones that supports the body, protects organs, and enables movement.</span></div>\\r\\n                <div><strong>Cartilage</strong><span>Flexible connective tissue at joints that cushions bones and prevents friction.</span></div>\\r\\n                <div><strong>Tendon</strong><span>Tough connective tissue that attaches muscle to bone.</span></div>\\r\\n                <div><strong>Ligament</strong><span>Connective tissue that connects bone to bone at joints.</span></div>\\r\\n                <div><strong>Skeletal muscle</strong><span>Voluntary muscle attached to bones that enables body movement.</span></div>\\r\\n                <div><strong>Cardiac muscle</strong><span>Involuntary muscle found only in the heart that contracts continuously without fatigue.</span></div>\\r\\n                <div><strong>Neuron</strong><span>A nerve cell that transmits electrical signals throughout the nervous system.</span></div>\\r\\n                <div><strong>Synapse</strong><span>The gap between neurons where chemical neurotransmitters pass signals.</span></div>\\r\\n                <div><strong>Reflex</strong><span>An automatic, involuntary response to a stimulus, processed in the spinal cord.</span></div>\\r\\n                <div><strong>Osteoporosis</strong><span>A disease in which bones become weak and brittle due to loss of calcium and bone density.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=14","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 14 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=14#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=14#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 14 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=14#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=14","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 14 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🦴","title":"Side Quest — Sports Injury Research","desc":"Choose one injury common in teen athletes: ACL tear, stress fracture, concussion, or growth plate injury. Research what causes it, how it\'s treated, and how it\'s prevented. Create a one-page fact sheet you could share with a teammate.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📰","title":"Exploration — Brain Health in the News","desc":"Find a current news story about concussions in youth sports, teen screen time and brain development, or nervous system health. What does the science say? What are schools and leagues changing in response?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📱","title":"Challenge — Posture & Screen Audit","desc":"Track your posture and screen time for one full school day. How many hours were you hunched over a device? What specific changes to your seating, phone habits, or exercise routine would protect your spine and nervous system long-term?","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/field_day.html","icon":"🏅","title":"Field Day","desc":"5-event track meet"},{"href":"/dopp_kong.html","icon":"🧗","title":"Sprite Climb","desc":"Climb past rolling junk food"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":15,"realmTag":"Realm V — Body Labyrinth","title":"Cardiovascular, Respiratory & Digestive Systems","sub":"Your heart beats 100,000 times a day without you thinking about it. Your lungs process 11,000 liters of air. Your gut is home to 38 trillion bacteria. This chapter reveals how your cardiovascular, respiratory, and digestive systems sustain your life — and what you\'re doing every day that helps or hurts them.","meta":[{"icon":"📅","label":"Days","value":"25–29"},{"icon":"📖","label":"Lessons","value":"4"},{"icon":"🏆","label":"Badge","value":"System Sage"}],"lessons":["L1: The Cardiovascular System","L2: The Respiratory System","L3: The Digestive System","L4: The Excretory System"],"pdf":"/Chapter_15_Cardiovascular_Respiratory_and_Digestive_Systems.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — The Cardiovascular System</h3>\\r\\n              <p>The cardiovascular system — heart, blood, and blood vessels — circulates oxygen and nutrients to every cell while removing carbon dioxide and waste products.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Heart</strong><span>4-chambered pump; right side pumps blood to lungs; left side pumps to body</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Arteries</strong><span>Carry oxygenated blood away from heart; thick muscular walls</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Veins</strong><span>Return deoxygenated blood to heart; contain valves to prevent backflow</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Capillaries</strong><span>Tiny vessels where gas and nutrient exchange occurs between blood and cells</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Heart Rate Facts</strong><br>\\r\\n                Resting heart rate for teens: 60–100 bpm. Athletes can have resting HR as low as 40 bpm — a sign of a strong, efficient heart. Regular aerobic exercise lowers resting heart rate over time.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the difference between arteries and veins?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — The Respiratory System</h3>\\r\\n              <p>The respiratory system brings oxygen into the body and expels carbon dioxide. Every breath moves air through a series of structures that filter, warm, and deliver it to the lungs.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Nose/mouth</strong> → <strong>pharynx</strong> → <strong>larynx</strong> → <strong>trachea</strong> → <strong>bronchi</strong> → <strong>bronchioles</strong> → <strong>alveoli</strong></li>\\r\\n                <li>Alveoli are tiny air sacs where gas exchange occurs — O₂ in, CO₂ out</li>\\r\\n                <li>Diaphragm — dome-shaped muscle that powers breathing</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Smoking &amp; Lung Damage</strong><br>\\r\\n                Tobacco smoke destroys cilia (tiny hairs that trap debris), damages alveoli, and causes chronic inflammation. This leads to COPD, emphysema, and lung cancer — often irreversible.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Where does gas exchange occur in the lungs?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — The Digestive System</h3>\\r\\n              <p>The digestive system breaks food into nutrients the body can absorb. This involves mechanical (physical) and chemical (enzyme-based) digestion across ~30 feet of digestive tract.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Mouth</strong><span>Mechanical digestion begins; salivary amylase starts breaking down starch</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Stomach</strong><span>Churns food; HCl kills bacteria; pepsin digests proteins</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Small Intestine</strong><span>Most nutrient absorption; 20 ft long; villi increase surface area</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Large Intestine</strong><span>Water absorption; houses gut microbiome; forms waste</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the difference between mechanical and chemical digestion?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Keeping These Systems Healthy</h3>\\r\\n              <p>Lifestyle choices profoundly affect cardiovascular, respiratory, and digestive health. Small daily habits compound into major differences over a lifetime.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Aerobic exercise strengthens the heart and improves circulation</li>\\r\\n                <li>Never smoke — tobacco is the leading cause of preventable cardiovascular and lung disease</li>\\r\\n                <li>Eat fiber-rich foods to support healthy digestion and gut microbiome</li>\\r\\n                <li>Stay hydrated — water is essential for blood volume and digestion</li>\\r\\n                <li>Limit saturated fat and sodium — both elevate cardiovascular disease risk</li>\\r\\n                <li>Know warning signs: chest pain, shortness of breath, persistent heartburn</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Name two lifestyle choices that protect cardiovascular health.</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Cardiovascular system</strong><span>The organ system of the heart and blood vessels that circulates blood throughout the body.</span></div>\\r\\n                <div><strong>Artery</strong><span>A blood vessel that carries oxygenated blood away from the heart.</span></div>\\r\\n                <div><strong>Vein</strong><span>A blood vessel that returns deoxygenated blood back to the heart.</span></div>\\r\\n                <div><strong>Capillary</strong><span>The smallest blood vessels where gas and nutrient exchange occurs between blood and cells.</span></div>\\r\\n                <div><strong>Alveoli</strong><span>Tiny air sacs in the lungs where oxygen and carbon dioxide are exchanged.</span></div>\\r\\n                <div><strong>Diaphragm</strong><span>The dome-shaped muscle below the lungs that controls breathing.</span></div>\\r\\n                <div><strong>Peristalsis</strong><span>The wave-like muscle contractions that move food through the digestive tract.</span></div>\\r\\n                <div><strong>Villi</strong><span>Tiny finger-like projections in the small intestine that absorb nutrients.</span></div>\\r\\n                <div><strong>Cholesterol</strong><span>A fatty substance in the blood; high levels increase risk of heart disease.</span></div>\\r\\n                <div><strong>Hypertension</strong><span>Persistently high blood pressure; a major risk factor for heart attack and stroke.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=15","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 15 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=15#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=15#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 15 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=15#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=15","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 15 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"❤️","title":"Side Quest — Heart Rate Analysis","desc":"Measure your resting heart rate for three days at the same time each morning. Compare it to healthy ranges for your age. Then research how sleep, exercise, stress, and caffeine affect resting heart rate. Write a short data analysis.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📰","title":"Exploration — Cardiovascular Health in Teens","desc":"Find a news story or research study about a cardiovascular, respiratory, or digestive health issue in young people — energy drink effects, asthma trends, ultra-processed food research. What does the evidence say teens should know?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🍎","title":"Challenge — 3-Day Diet Tracker","desc":"For three days, track one food or drink choice each day that directly affects your digestive or cardiovascular system. Research what it does inside your body. Would your doctor approve? Write an honest self-assessment.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/sprite_dash.html","icon":"🏃","title":"Sprite Dash","desc":"Jump and duck past junk food"},{"href":"/dopp_drop.html","icon":"🧺","title":"Sprite Catch","desc":"Catch fruits and veggies, dodge the junk"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":16,"realmTag":"Realm V — Body Labyrinth","title":"Endocrine & Reproductive Health","sub":"Hormones control your mood, growth, metabolism, sleep, and stress response — and during the teen years, they\'re working overtime. Understanding your endocrine system means understanding why your body does what it does, and how to work with it instead of against it.","meta":[{"icon":"📅","label":"Days","value":"27–29"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"System Sage"}],"lessons":["L1: The Endocrine System","L2: Male Reproductive Health","L3: Female Reproductive Health"],"pdf":"/Chapter_16_Endocrine_and_Reproductive_Health.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — The Endocrine System</h3>\\r\\n              <p>The endocrine system is a network of glands that produce hormones — chemical messengers that regulate growth, metabolism, mood, reproduction, and more.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Pituitary Gland</strong><span>The \\"master gland\\" — regulates other glands; controls growth hormone</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Thyroid</strong><span>Controls metabolism, energy, and body temperature</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Adrenal Glands</strong><span>Produce adrenaline (epinephrine) for fight-or-flight response; also cortisol</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Pancreas</strong><span>Produces insulin and glucagon to regulate blood sugar</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Hormones &amp; Puberty</strong><br>\\r\\n                During puberty, the pituitary gland signals the gonads (ovaries/testes) to produce sex hormones — estrogen, progesterone, and testosterone — triggering physical and emotional changes.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the role of the pituitary gland in the endocrine system?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Puberty &amp; Physical Development</h3>\\r\\n              <p>Puberty is the process of physical and sexual maturation driven by hormonal changes. It typically begins between ages 8–13 for females and 9–14 for males.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Female changes:</strong> breast development, pubic/underarm hair, menstruation, hips widening</li>\\r\\n                <li><strong>Male changes:</strong> testicular growth, pubic/facial hair, voice deepening, muscle development</li>\\r\\n                <li><strong>Both:</strong> growth spurts, acne, body odor, emotional changes</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Normal Variation</strong><br>\\r\\n                The timing of puberty varies widely and is largely genetic. Early or late development is usually normal — but persistent concerns should be discussed with a healthcare provider.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What hormone primarily drives puberty in males? In females?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Reproductive Systems</h3>\\r\\n              <p>The male and female reproductive systems have distinct structures and functions, all regulated by the endocrine system.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Female Reproductive</strong><span>Ovaries (produce eggs/hormones), fallopian tubes, uterus, cervix, vagina</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Male Reproductive</strong><span>Testes (produce sperm/testosterone), epididymis, vas deferens, penis</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Menstrual Cycle</strong><span>~28-day cycle; prepares uterus for potential pregnancy; regulated by hormones</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Fertilization</strong><span>Sperm + egg → zygote; occurs in fallopian tube if timing aligns</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Where does fertilization typically occur in the female reproductive system?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Reproductive Health &amp; Care</h3>\\r\\n              <p>Reproductive health involves physical, emotional, and social well-being related to the reproductive system throughout life.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Annual gynecological exams recommended beginning in the teen years</li>\\r\\n                <li>Testicular self-exams monthly — report unusual lumps to a provider</li>\\r\\n                <li>Abstinence is the only 100% effective method to prevent pregnancy and STIs</li>\\r\\n                <li>HPV vaccine is recommended for preteens — prevents several cancers</li>\\r\\n                <li>Understanding consent is fundamental to all sexual health decisions</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why is the HPV vaccine recommended for teens?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Endocrine system</strong><span>The system of glands that produce and release hormones into the bloodstream.</span></div>\\r\\n                <div><strong>Hormone</strong><span>A chemical messenger produced by a gland that travels through the blood to regulate body functions.</span></div>\\r\\n                <div><strong>Puberty</strong><span>The period of physical and sexual maturation driven by hormonal changes.</span></div>\\r\\n                <div><strong>Estrogen</strong><span>The primary female sex hormone responsible for reproductive development and the menstrual cycle.</span></div>\\r\\n                <div><strong>Testosterone</strong><span>The primary male sex hormone responsible for male reproductive development and muscle growth.</span></div>\\r\\n                <div><strong>Menstruation</strong><span>The monthly shedding of the uterine lining when pregnancy does not occur.</span></div>\\r\\n                <div><strong>Ovulation</strong><span>The release of a mature egg from the ovary, typically mid-cycle.</span></div>\\r\\n                <div><strong>Fertilization</strong><span>The union of a sperm cell and an egg cell to form a zygote.</span></div>\\r\\n                <div><strong>Insulin</strong><span>A hormone produced by the pancreas that regulates blood sugar levels.</span></div>\\r\\n                <div><strong>Adrenal glands</strong><span>Glands above the kidneys that produce adrenaline and cortisol for stress response.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=16","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 16 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=16#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=16#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 16 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=16#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=16","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 16 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🔬","title":"Side Quest — Hormone Deep Dive","desc":"Choose one hormone — cortisol, testosterone, estrogen, insulin, or melatonin — and research how it affects teen health specifically. What lifestyle choices boost or disrupt it? Create a one-page informational guide.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📰","title":"Exploration — Teen Hormonal Health Research","desc":"Find a credible news story or research finding about teen hormonal health — puberty timing trends, sleep and melatonin disruption, or stress hormones in adolescents. What are the findings and what do they mean for teens your age?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"😴","title":"Challenge — Sleep & Stress Reflection","desc":"For one week, track your sleep hours and your stress level (1–10) each day. At the end, look for patterns. Based on Chapter 16, identify which hormones are most likely being affected by your patterns — and what you could change.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_wordle.html","icon":"🔤","title":"Word Quest","desc":"Guess the 5-letter health word"},{"href":"/dopp_match.html","icon":"🧠","title":"Sprite Memory","desc":"Match healthy pairs before time runs out"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":17,"realmTag":"Realm VI — Life Cycle Shrine","title":"The Beginning of the Life Cycle","sub":"In nine months, a single cell becomes a fully formed human being with a beating heart, working lungs, and a brain with 100 billion neurons. This chapter covers prenatal development, genetics, and the environmental factors that shape a healthy start to life.","meta":[{"icon":"📅","label":"Days","value":"30–31"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Life Keeper"}],"lessons":["L1: Prenatal Development","L2: Heredity and Genetics","L3: Birth Through Childhood"],"pdf":"/Chapter_17_The_Beginning_of_the_Life_Cycle.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Conception &amp; Early Development</h3>\\r\\n              <p>Human life begins at fertilization — when a sperm cell penetrates an egg to form a single-celled zygote with a unique combination of 46 chromosomes.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Zygote (0–2 wks)</strong><span>Fertilized egg; travels to uterus and implants in the endometrium</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Embryo (2–8 wks)</strong><span>Rapid cell division; major organ systems begin forming</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Fetus (8 wks–birth)</strong><span>All major structures present; continues growing and maturing</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Placenta</strong><span>Organ connecting mother and fetus; transfers nutrients and oxygen; removes waste</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the difference between a zygote, embryo, and fetus?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Prenatal Care &amp; Development</h3>\\r\\n              <p>Prenatal care — medical care during pregnancy — significantly improves outcomes for mother and baby. The developing fetus is vulnerable to environmental factors called teratogens.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Critical Periods</strong><br>\\r\\n                The first trimester (weeks 1–12) is the most critical for organ development. Exposure to alcohol, tobacco, drugs, or certain medications during this time can cause birth defects.\\r\\n              </div>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Folic acid before/during pregnancy reduces neural tube defects</li>\\r\\n                <li>No alcohol — Fetal Alcohol Spectrum Disorder (FASD) is 100% preventable</li>\\r\\n                <li>Avoid tobacco — linked to low birth weight and premature birth</li>\\r\\n                <li>Regular OB/GYN visits track fetal growth and maternal health</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is a teratogen, and why is the first trimester most vulnerable?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Labor, Birth &amp; the Newborn</h3>\\r\\n              <p>A typical pregnancy lasts ~40 weeks (280 days). Labor involves three stages: cervical dilation, delivery of the baby, and delivery of the placenta.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Stage 1</strong><span>Cervix dilates to 10 cm; contractions become stronger and closer together</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Stage 2</strong><span>Baby moves through birth canal and is delivered</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Stage 3</strong><span>Placenta (afterbirth) is delivered</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Cesarean Section</strong><span>Surgical delivery through the abdomen when vaginal birth is not safe</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What happens during each of the three stages of labor?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Infancy &amp; Early Childhood</h3>\\r\\n              <p>The first years of life involve the most rapid growth and brain development a human ever experiences. Early experiences literally shape brain architecture.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Breastfeeding provides optimal nutrition and immune protection for infants</li>\\r\\n                <li>Secure attachment to caregivers is essential for emotional development</li>\\r\\n                <li>Sensory stimulation (talking, reading, play) builds neural connections</li>\\r\\n                <li>Vaccinations protect infants from serious preventable diseases</li>\\r\\n                <li>Safe sleep practices prevent Sudden Infant Death Syndrome (SIDS)</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why are the first few years of life so critical for brain development?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Fertilization</strong><span>The union of a sperm and egg cell to form a zygote.</span></div>\\r\\n                <div><strong>Zygote</strong><span>The single cell formed when a sperm fertilizes an egg; contains 46 chromosomes.</span></div>\\r\\n                <div><strong>Embryo</strong><span>The developing human from fertilization through 8 weeks, when major organs begin forming.</span></div>\\r\\n                <div><strong>Fetus</strong><span>The developing human from 8 weeks after fertilization until birth.</span></div>\\r\\n                <div><strong>Placenta</strong><span>The organ that connects mother and fetus to transfer nutrients, oxygen, and remove waste.</span></div>\\r\\n                <div><strong>Teratogen</strong><span>Any substance or condition that can interfere with fetal development and cause birth defects.</span></div>\\r\\n                <div><strong>Prenatal care</strong><span>Medical care received during pregnancy to monitor the health of mother and developing baby.</span></div>\\r\\n                <div><strong>Trimester</strong><span>One of three ~13-week periods that divide a pregnancy.</span></div>\\r\\n                <div><strong>Labor</strong><span>The process by which the uterus contracts to deliver the baby and placenta.</span></div>\\r\\n                <div><strong>SIDS</strong><span>Sudden Infant Death Syndrome — the unexplained death of an otherwise healthy infant during sleep.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=17","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 17 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=17#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=17#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 17 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=17#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=17","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 17 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🧬","title":"Side Quest — Teratogen Research","desc":"Research one teratogen — a substance that harms fetal development (alcohol, tobacco, certain medications, or infections). What are its effects on the developing baby? At what stage of pregnancy is it most dangerous? Use current medical sources.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📰","title":"Exploration — Advances in Prenatal Care","desc":"Find a news story about advances in prenatal care, genetic testing, or neonatal medicine. How is modern science changing outcomes for premature babies or those with genetic conditions? What ethical questions arise?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"👶","title":"Challenge — Birth Story Interview","desc":"Interview a parent or guardian about what they know about your birth and early childhood. Were there any health factors, complications, or memorable milestones? Write a personal reflection on what you learned about the beginning of your life cycle.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_wordle.html","icon":"🔤","title":"Word Quest","desc":"Guess the 5-letter health word"},{"href":"/dopp_match.html","icon":"🧠","title":"Sprite Memory","desc":"Match healthy pairs before time runs out"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":18,"realmTag":"Realm VI — Life Cycle Shrine","title":"The Life Cycle Continues","sub":"From the identity chaos of adolescence to the wisdom of late adulthood, every stage of life brings new physical, emotional, and social changes. This chapter maps the human journey — and shows how the health choices you make today echo through every decade that follows.","meta":[{"icon":"📅","label":"Days","value":"32–33"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Life Keeper"}],"lessons":["L1: Adolescence","L2: Adulthood and Aging","L3: Health Throughout Life"],"pdf":"/Chapter_18_The_Life_Cycle_Continues.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Adolescence &amp; Young Adulthood</h3>\\r\\n              <p>Adolescence spans roughly ages 10–19, involving rapid physical, cognitive, emotional, and social development. The teenage brain is still developing — particularly the prefrontal cortex (judgment, impulse control) — until the mid-20s.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Brain Development</strong><br>\\r\\n                The limbic system (emotions, reward) matures before the prefrontal cortex (planning, consequence evaluation). This explains why teens may take more risks — the emotional brain drives behavior before the rational brain is fully online.\\r\\n              </div>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Physical</strong><span>Growth spurts, hormonal changes, reproductive maturity</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Cognitive</strong><span>Abstract thinking, moral reasoning, identity formation</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Emotional</strong><span>Intense emotions, peer influence, identity exploration</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Social</strong><span>Peer relationships become central; independence from parents increases</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why is the prefrontal cortex important, and when does it finish developing?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Adulthood &amp; Middle Age</h3>\\r\\n              <p>Young adulthood (20s–30s) focuses on career, relationships, and establishing independence. Middle adulthood (40s–60s) involves physical changes and a shift toward legacy and meaning.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Physical peak typically occurs in the 20s; gradual decline begins in the 30s–40s</li>\\r\\n                <li>Menopause occurs around age 50 in women — estrogen production stops</li>\\r\\n                <li>Chronic disease risk increases with age, especially without healthy habits</li>\\r\\n                <li>Midlife crisis is real for some — a reassessment of goals and identity</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is menopause, and what hormone change causes it?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Aging &amp; Late Adulthood</h3>\\r\\n              <p>Aging is a natural biological process. Late adulthood (65+) brings physical changes, but active aging — staying physically and mentally engaged — dramatically improves quality of life.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Physical Changes</strong><span>Muscle loss (sarcopenia), bone density reduction, slower metabolism, vision/hearing changes</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Cognitive Changes</strong><span>Processing speed slows; memory may decline; wisdom and vocabulary often improve</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Social Changes</strong><span>Retirement, loss of peers, grandparenting, shifting family roles</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Active Aging</strong><span>Exercise, social connection, lifelong learning protect physical and cognitive health</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is sarcopenia, and how can it be slowed?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Death, Dying &amp; Grief</h3>\\r\\n              <p>Death is a universal part of the life cycle. Understanding the process of dying and healthy grieving helps people cope with loss and support others.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Kübler-Ross\'s 5 stages of grief: Denial, Anger, Bargaining, Depression, Acceptance</li>\\r\\n                <li>Grief is not linear — people move between stages in their own way and time</li>\\r\\n                <li>Hospice care focuses on comfort and dignity at end of life</li>\\r\\n                <li>Healthy grief includes talking, crying, remembering — and eventually, moving forward</li>\\r\\n                <li>Supporting a grieving friend: listen, be present, avoid minimizing their loss</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Name the 5 Kübler-Ross stages of grief in order.</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Adolescence</strong><span>The developmental stage between childhood and adulthood, typically ages 10–19.</span></div>\\r\\n                <div><strong>Prefrontal cortex</strong><span>The brain region responsible for planning, judgment, and impulse control; fully mature in the mid-20s.</span></div>\\r\\n                <div><strong>Menopause</strong><span>The cessation of menstruation, marking the end of female reproductive capacity, typically around age 50.</span></div>\\r\\n                <div><strong>Sarcopenia</strong><span>The age-related loss of muscle mass and strength.</span></div>\\r\\n                <div><strong>Grief</strong><span>The emotional response to significant loss, including death of a loved one.</span></div>\\r\\n                <div><strong>Kübler-Ross stages</strong><span>Five stages of grief: Denial, Anger, Bargaining, Depression, Acceptance.</span></div>\\r\\n                <div><strong>Hospice</strong><span>A program focused on comfort care and quality of life for people with terminal illness.</span></div>\\r\\n                <div><strong>Life expectancy</strong><span>The average number of years a person is expected to live based on current mortality rates.</span></div>\\r\\n                <div><strong>Gerontology</strong><span>The scientific study of aging and older adults.</span></div>\\r\\n                <div><strong>Active aging</strong><span>Maintaining physical activity, social engagement, and mental stimulation in older adulthood to improve quality of life.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=18","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 18 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=18#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=18#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 18 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=18#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=18","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 18 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🗣","title":"Side Quest — Life Stage Interview","desc":"Interview someone at least 20 years older than you about one major physical or emotional change they experienced at a different life stage. How did they adapt? What do they wish they had known? Write a one-page reflection.","tags":[{"text":"Solo","kind":""},{"text":"~25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📰","title":"Exploration — Teen Brain & Healthy Aging Research","desc":"Find a news story or study about healthy aging, teen brain development, or the transition to adulthood. What does the research say teens can do NOW to set themselves up for healthier middle and late adulthood?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🗺","title":"Challenge — Life Stage Health Map","desc":"Map out your own life stages: adolescence, early adulthood, middle age, late adulthood. For each stage, identify one health decision you could make TODAY that would positively affect that future stage. Be specific — not general advice.","tags":[{"text":"Solo","kind":""},{"text":"~15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_kong.html","icon":"🧗","title":"Sprite Climb","desc":"Climb past rolling junk food"},{"href":"/habit_showdown.html","icon":"⚖️","title":"Habit Showdown","desc":"Good habit or bad? Myth or fact?"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":19,"realmTag":"Realm VII — Shadow World","title":"Medicines & Drugs","sub":"Medicines save lives — but misuse kills. This chapter covers how medications work, the opioid crisis, fentanyl in counterfeit pills, and how to stay safe in a world where drug misinformation is everywhere.","meta":[{"icon":"📅","label":"Days","value":"34–37"},{"icon":"📖","label":"Lessons","value":"2"},{"icon":"🏆","label":"Badge","value":"Shadow Slayer"}],"lessons":["L1: The Role of Medicines","L2: Using Medicines Safely"],"pdf":"/Chapter_19_Medicines_and_Drugs.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — What Are Medicines?</h3>\\r\\n              <p>Medicines are chemical substances used to treat, prevent, or diagnose illness. They are carefully tested for safety and effectiveness before being approved.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Prescription (Rx)</strong><span>Requires a doctor\'s order; used for serious/complex conditions; regulated dosing</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Over-the-Counter (OTC)</strong><span>Available without prescription; safe when used as directed on label</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Vaccines</strong><span>Stimulate immune response to provide immunity without causing disease</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Side Effects</strong><span>Unintended effects of a medicine; listed on labels; some require medical attention</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Safe Medicine Use</strong><br>\\r\\n                Always follow dosing instructions, check expiration dates, and never share prescription medications. Drug interactions can be dangerous — tell your provider all the medications you take.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the difference between prescription and OTC medications?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Drug Misuse &amp; Abuse</h3>\\r\\n              <p>Drug misuse means using medication in a way other than intended — wrong dose, wrong person, or wrong purpose. Drug abuse is intentional use to alter mood or perception.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li><strong>Tolerance</strong> — needing more of a drug to get the same effect</li>\\r\\n                <li><strong>Dependence</strong> — body adapts and requires drug to function normally</li>\\r\\n                <li><strong>Addiction</strong> — compulsive use despite harmful consequences; a chronic brain disorder</li>\\r\\n                <li><strong>Withdrawal</strong> — physical/psychological symptoms when stopping a substance</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the difference between drug tolerance and drug dependence?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Types of Drugs &amp; Their Effects</h3>\\r\\n              <p>Psychoactive drugs alter brain chemistry and behavior. They are categorized by how they affect the central nervous system:</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Stimulants</strong><span>Speed up CNS; increase alertness (caffeine, amphetamines, cocaine)</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Depressants</strong><span>Slow CNS; reduce anxiety (alcohol, benzodiazepines, barbiturates)</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Opioids</strong><span>Block pain receptors; high addiction potential (morphine, oxycodone, heroin)</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Hallucinogens</strong><span>Distort perception of reality (LSD, psilocybin, PCP)</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> How do stimulants affect the central nervous system differently than depressants?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Prevention &amp; Getting Help</h3>\\r\\n              <p>Understanding risk factors, building refusal skills, and knowing where to get help are essential life skills for navigating a world where drugs are present.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Risk factors: peer pressure, stress, family history of addiction, trauma</li>\\r\\n                <li>Protective factors: strong relationships, school engagement, healthy coping skills</li>\\r\\n                <li>Practice refusal scripts: \\"No thanks, it\'s not for me\\" — short, confident, no explanation needed</li>\\r\\n                <li>SAMHSA National Helpline: 1-800-662-4357 (free, confidential, 24/7)</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Name two risk factors and two protective factors for drug misuse.</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Medicine</strong><span>A chemical substance used to treat, prevent, or diagnose illness.</span></div>\\r\\n                <div><strong>Prescription drug</strong><span>A medication that requires a doctor\'s written order before it can be dispensed.</span></div>\\r\\n                <div><strong>Drug misuse</strong><span>Using a medication in a manner other than intended (wrong dose, person, or purpose).</span></div>\\r\\n                <div><strong>Drug abuse</strong><span>Intentional use of a substance to alter mood or perception in a harmful way.</span></div>\\r\\n                <div><strong>Tolerance</strong><span>The need for increasing amounts of a drug to achieve the same effect.</span></div>\\r\\n                <div><strong>Dependence</strong><span>A physical or psychological need for a substance to function normally.</span></div>\\r\\n                <div><strong>Addiction</strong><span>A chronic brain disorder involving compulsive drug use despite harmful consequences.</span></div>\\r\\n                <div><strong>Stimulant</strong><span>A drug that speeds up central nervous system activity.</span></div>\\r\\n                <div><strong>Depressant</strong><span>A drug that slows central nervous system activity.</span></div>\\r\\n                <div><strong>Opioid</strong><span>A class of drugs that block pain receptors and carry high addiction potential.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=19","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 19 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=19#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=19#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 19 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=19#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=19","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 19 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"The Opioid Crisis Timeline","desc":"Research how prescription painkillers triggered America\'s opioid epidemic. Trace the timeline from OxyContin\'s 1996 launch to the fentanyl crisis of today. What decisions made it worse at each stage?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🔍","title":"Fentanyl & Counterfeit Pills","desc":"Research fentanyl: what it is, why it\'s 50–100× more potent than morphine, how it entered counterfeit pills, and why naloxone is now available OTC. Present the 3 facts that would most change teen behavior.","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Medication Safety Home Audit","desc":"Review the medications in your home. Check labels for storage instructions, expiration dates, and refill counts. Identify any that could be misused. Write a specific plan to secure them properly.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/habit_showdown.html","icon":"⚖️","title":"Habit Showdown","desc":"Good habit or bad? Myth or fact?"},{"href":"/dopp_dunk.html","icon":"🏀","title":"Sprite Hoops","desc":"Shoot bad habits into the trash"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":20,"realmTag":"Realm VII — Shadow World","title":"Tobacco","sub":"480,000 Americans die from tobacco every year. And 9 in 10 adult smokers started as teenagers. This chapter covers tobacco\'s real effects on the body — and the good news: teen smoking is at a 25-year low.","meta":[{"icon":"📅","label":"Days","value":"36–39"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Shadow Slayer"}],"lessons":["L1: Health Risks of Tobacco","L2: Choosing Tobacco-Free","L3: Promoting a Smoke-Free Environment"],"pdf":"/Chapter_20_Tobacco.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — What\'s in Tobacco?</h3>\\r\\n              <p>Tobacco contains over 7,000 chemicals when burned, including hundreds that are toxic and at least 70 known carcinogens. Understanding what you\'re inhaling is the foundation of informed refusal.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Nicotine</strong><span>The addictive chemical in tobacco; stimulates the brain\'s reward centers</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Carbon Monoxide</strong><span>Bonds to hemoglobin better than oxygen; reduces oxygen delivery to tissues</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Tar</strong><span>Sticky residue that coats lungs; contains most carcinogens</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Formaldehyde</strong><span>Used in embalming; damages lung tissue with every cigarette</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> How does carbon monoxide harm the body?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Health Consequences of Tobacco</h3>\\r\\n              <p>Tobacco is the leading cause of preventable death in the United States — responsible for 480,000 deaths per year. It damages virtually every organ system.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Diseases Caused by Smoking</strong><br>\\r\\n                Lung cancer, COPD, emphysema, chronic bronchitis, oral cancer, esophageal cancer, heart disease, stroke, peripheral artery disease, and reduced fertility — all linked to tobacco use.\\r\\n              </div>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Smokers die on average 10 years younger than non-smokers</li>\\r\\n                <li>Secondhand smoke causes 41,000 deaths/year among non-smokers (CDC)</li>\\r\\n                <li>Teen smokers lose lung function faster than non-smoking peers</li>\\r\\n                <li>Nicotine is especially harmful to the developing adolescent brain</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Name three diseases caused by tobacco use.</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Vaping &amp; E-Cigarettes</h3>\\r\\n              <p>E-cigarettes (vapes) heat liquid containing nicotine, propylene glycol, vegetable glycerin, and flavorings to create an aerosol. They were marketed as \\"safer\\" — but evidence tells a different story.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>EVALI</strong><br>\\r\\n                In 2019, thousands of people were hospitalized with EVALI (e-cigarette or vaping product use-associated lung injury), many of them teens. The outbreak was linked to Vitamin E acetate in some products.\\r\\n              </div>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Vaping delivers highly concentrated nicotine — one JUUL pod = ~20 cigarettes of nicotine</li>\\r\\n                <li>Adolescent vapers are 3x more likely to start smoking cigarettes</li>\\r\\n                <li>Flavors (mango, mint, candy) are specifically designed to attract teens</li>\\r\\n                <li>Long-term effects of vaping are still being studied — the risk is real</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why are flavored e-cigarette products especially concerning for teens?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Quitting &amp; Prevention</h3>\\r\\n              <p>Nicotine addiction is powerful — but quitting is possible. Most smokers try multiple times before successfully quitting, and that\'s normal. Each attempt teaches something valuable.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>FDA-approved cessation aids: nicotine replacement (patch, gum, lozenge), varenicline (Chantix), bupropion</li>\\r\\n                <li>Behavioral counseling doubles quit success rates</li>\\r\\n                <li>Set a quit date, tell someone, remove tobacco from your environment</li>\\r\\n                <li>Identify triggers (stress, social situations) and plan alternatives</li>\\r\\n                <li>smokefree.gov offers free tools and apps for quitting</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What are two strategies that increase the success of quitting tobacco?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Nicotine</strong><span>The highly addictive chemical found in tobacco that stimulates the brain\'s reward pathway.</span></div>\\r\\n                <div><strong>Tar</strong><span>The sticky brown residue from tobacco smoke that coats the lungs and contains carcinogens.</span></div>\\r\\n                <div><strong>Carbon monoxide</strong><span>A colorless, odorless gas in tobacco smoke that reduces oxygen delivery in the blood.</span></div>\\r\\n                <div><strong>Carcinogen</strong><span>Any substance capable of causing cancer in living tissue.</span></div>\\r\\n                <div><strong>COPD</strong><span>Chronic Obstructive Pulmonary Disease — a group of lung diseases including emphysema and chronic bronchitis.</span></div>\\r\\n                <div><strong>Emphysema</strong><span>A lung disease where alveoli are destroyed, causing severe breathing difficulty.</span></div>\\r\\n                <div><strong>Secondhand smoke</strong><span>Tobacco smoke inhaled by a non-smoker in the vicinity of someone smoking.</span></div>\\r\\n                <div><strong>E-cigarette</strong><span>An electronic device that heats a liquid to create an aerosol containing nicotine and other chemicals.</span></div>\\r\\n                <div><strong>EVALI</strong><span>E-cigarette or Vaping Product Use-Associated Lung Injury — a serious lung condition linked to vaping.</span></div>\\r\\n                <div><strong>Cessation</strong><span>The act of stopping a behavior, such as quitting tobacco use.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=20","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 20 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=20#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=20#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 20 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=20#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=20","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 20 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"Vaping vs. Smoking — The Research","desc":"Compare the health risks of e-cigarettes vs. traditional cigarettes using current peer-reviewed studies. Are e-cigarettes safer? Summarize what we know, what we don\'t, and why that uncertainty matters.","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🔍","title":"Tobacco Industry Marketing Tactics","desc":"Research how tobacco companies targeted teens historically and how vaping brands use the same playbook today. Find 3 specific current examples. Why are flavors, social media, and influencers so effective on teens?","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Cessation Methods Comparison","desc":"Research the most effective tobacco and nicotine cessation methods: NRT patches/gum, prescription medication, counseling, and apps. What does the evidence show works best? Which approach would you recommend to a friend?","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_dunk.html","icon":"🏀","title":"Sprite Hoops","desc":"Shoot bad habits into the trash"},{"href":"/sprite_flap.html","icon":"🪽","title":"Sprite Flap","desc":"Flap through junk-food towers"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":21,"realmTag":"Realm VII — Shadow World","title":"Alcohol","sub":"Teen drinking is at a historic low — but alcohol remains the most dangerous legal drug teens encounter. This chapter covers the science of how alcohol affects the developing brain, and why the risks are higher for teens than adults.","meta":[{"icon":"📅","label":"Days","value":"38–41"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"Shadow Slayer"}],"lessons":["L1: Health Risks of Alcohol","L2: Choosing Alcohol-Free","L3: The Impact of Alcohol Abuse"],"pdf":"/Chapter_21_Alcohol.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — What Alcohol Does to the Body</h3>\\r\\n              <p>Alcohol (ethanol) is a central nervous system depressant that slows brain activity. It\'s absorbed rapidly into the bloodstream and affects every organ system.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Brain</strong><span>Impairs judgment, coordination, memory; slows reaction time</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Liver</strong><span>Processes ~1 drink/hour; overload leads to fatty liver, cirrhosis</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Heart</strong><span>Raises blood pressure; heavy use weakens heart muscle (cardiomyopathy)</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Teen Brain</strong><span>Alcohol is more damaging to developing brains — memory and learning impaired</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Blood Alcohol Concentration (BAC)</strong><br>\\r\\n                BAC measures alcohol in the bloodstream. At 0.08% (legal limit for driving) coordination and judgment are significantly impaired. At 0.30%+, loss of consciousness and death risk increase dramatically.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why is alcohol especially harmful to the brains of teenagers?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Alcohol Risks &amp; Consequences</h3>\\r\\n              <p>Alcohol impairs decision-making and increases risk-taking, leading to a cascade of social, legal, and health consequences — especially for teens.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Leading cause of teen traffic deaths — 1 in 4 teen traffic fatalities involve alcohol</li>\\r\\n                <li>Increases risk of sexual assault and unwanted sexual activity</li>\\r\\n                <li>Binge drinking (4+ drinks for women, 5+ for men in 2 hrs) causes acute alcohol poisoning</li>\\r\\n                <li>Underage drinking is illegal — criminal charges, license suspension, college/career impacts</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is binge drinking, and what are two risks associated with it?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Alcohol Use Disorder</h3>\\r\\n              <p>Alcohol Use Disorder (AUD) is a chronic medical condition involving loss of control over drinking despite negative consequences. It\'s a brain disease, not a moral failure.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Warning Signs of AUD</strong><br>\\r\\n                Drinking more than intended, failed attempts to cut back, neglecting responsibilities, continued use despite relationship/health problems, experiencing withdrawal symptoms.\\r\\n              </div>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Genetics account for ~50% of AUD risk — family history matters</li>\\r\\n                <li>Early drinking onset dramatically increases lifetime AUD risk</li>\\r\\n                <li>Treatment options: counseling, support groups (AA), medication-assisted treatment</li>\\r\\n                <li>Recovery is possible — millions of people live in sustained recovery</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why is starting to drink at a young age considered a major risk factor for AUD?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Refusing Alcohol &amp; Getting Help</h3>\\r\\n              <p>Resisting peer pressure around alcohol is a critical skill. Having a plan before social situations makes refusal easier and more effective.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>\\"No thanks — I\'m good\\" (simple, no explanation required)</li>\\r\\n                <li>Have a non-alcoholic drink in hand at parties to avoid offers</li>\\r\\n                <li>Pre-plan an exit strategy or code word with a trusted friend</li>\\r\\n                <li>If someone is dangerously intoxicated: stay with them, call for help, put them in recovery position</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What should you do if a friend shows signs of alcohol poisoning?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Ethanol</strong><span>The type of alcohol found in beverages; a central nervous system depressant.</span></div>\\r\\n                <div><strong>BAC</strong><span>Blood Alcohol Concentration — the percentage of alcohol in the bloodstream.</span></div>\\r\\n                <div><strong>Binge drinking</strong><span>Consuming 4+ drinks (women) or 5+ drinks (men) in about 2 hours, raising BAC to 0.08%+.</span></div>\\r\\n                <div><strong>Cirrhosis</strong><span>Severe scarring of the liver caused by long-term alcohol abuse.</span></div>\\r\\n                <div><strong>Alcohol Use Disorder</strong><span>A chronic medical condition characterized by inability to control drinking despite negative consequences.</span></div>\\r\\n                <div><strong>Tolerance</strong><span>The need for more alcohol to feel the same effect as before.</span></div>\\r\\n                <div><strong>Withdrawal</strong><span>Physical and psychological symptoms that occur when a dependent person stops drinking.</span></div>\\r\\n                <div><strong>Fetal Alcohol Syndrome</strong><span>A group of birth defects caused by alcohol exposure during pregnancy.</span></div>\\r\\n                <div><strong>Alcohol poisoning</strong><span>A dangerous, potentially fatal condition caused by a high BAC that overwhelms the body.</span></div>\\r\\n                <div><strong>Peer pressure</strong><span>Social influence from peers that encourages a person to conform to group behaviors.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=21","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 21 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=21#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=21#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 21 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=21#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=21","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 21 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"Teen Alcohol Statistics Deep Dive","desc":"Research current national data on teen alcohol use: prevalence, binge drinking rates, age of first use, and 25-year trend lines. What protective factors most reliably keep teens from starting? Cite your sources.","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🔍","title":"Alcohol & the Developing Brain","desc":"Find current neuroscience research on how alcohol damages the adolescent brain differently than the adult brain. What structures are most vulnerable? What are the long-term consequences on memory, impulse control, and addiction risk?","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Alcohol Advertising Audit","desc":"Analyze 3 alcohol advertisements from different media. Identify the specific persuasion techniques used in each. Why are these techniques especially effective on teens? What would responsible alcohol marketing look like?","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/habit_showdown.html","icon":"⚖️","title":"Habit Showdown","desc":"Good habit or bad? Myth or fact?"},{"href":"/dopp_corner.html","icon":"👑","title":"Sprite Dodge","desc":"Out-dodge King Junk for 60 seconds"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":22,"realmTag":"Realm VII — Shadow World","title":"Illegal Drugs","sub":"The fentanyl crisis has fundamentally changed the risk landscape for teens. This chapter covers every major drug category — with special focus on why counterfeit pills are so lethal and how to stay safe.","meta":[{"icon":"📅","label":"Days","value":"40–41"},{"icon":"📖","label":"Lessons","value":"4"},{"icon":"🏆","label":"Badge","value":"Shadow Slayer"}],"lessons":["L1: Health Risks of Drug Use","L2: Marijuana, Inhalants, Steroids","L3: Psychoactive Drugs","L4: Living Drug-Free"],"pdf":"/Chapter_22_Illegal_Drugs.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Marijuana</h3>\\r\\n              <p>Marijuana (cannabis) is the most commonly used illegal drug among teens. THC (tetrahydrocannabinol) is the psychoactive compound that creates its effects by binding to cannabinoid receptors in the brain.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Short-Term Effects</strong><span>Euphoria, impaired memory, slowed reaction time, increased appetite, anxiety</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Long-Term Effects</strong><span>Memory/learning impairment, lung damage (if smoked), risk of Cannabis Use Disorder</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Teen Brain Risk</strong><span>THC disrupts normal brain development; linked to lower IQ and mental health problems</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Vaping/Edibles</strong><span>Concentrated forms increase overdose risk; edibles have delayed effects</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why is marijuana use particularly risky for teenagers compared to adults?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Stimulants &amp; Cocaine</h3>\\r\\n              <p>Stimulant drugs like cocaine, methamphetamine, and Adderall (when misused) dramatically increase dopamine in the brain\'s reward system, creating intense pleasure — and severe crashes.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Meth &amp; the Brain</strong><br>\\r\\n                Methamphetamine releases 3x more dopamine than cocaine. It destroys dopamine receptors over time, leaving users unable to feel pleasure from normal activities — a condition called anhedonia.\\r\\n              </div>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Cocaine: short-lived high, intense crash, high addiction potential; can cause cardiac arrest</li>\\r\\n                <li>Meth: cheap, long-lasting, devastatingly addictive; causes severe dental decay and skin sores</li>\\r\\n                <li>Adderall misuse: not \\"safer\\" because it\'s a prescription — still carries addiction and cardiac risk</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is anhedonia, and why does meth cause it?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Opioids &amp; Heroin</h3>\\r\\n              <p>The opioid epidemic is the deadliest drug crisis in U.S. history. At its peak it killed over 80,000 Americans a year. Deaths have dropped since, but opioids still killed about 44,600 people in 2025 (CDC). Many opioid addictions start with legally prescribed painkillers.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Fentanyl Crisis</strong><br>\\r\\n                Illicitly manufactured fentanyl — 50x stronger than heroin — is now found in counterfeit pills and other drugs. A dose the size of a few grains of salt can be fatal. There is no safe \\"recreational\\" opioid use.\\r\\n              </div>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Opioids bind to brain receptors, blocking pain and creating euphoria</li>\\r\\n                <li>Respiratory depression (breathing stops) is the mechanism of overdose death</li>\\r\\n                <li>Naloxone (Narcan) can reverse an overdose — available without prescription in most states</li>\\r\\n                <li>Medication-assisted treatment (buprenorphine, methadone) saves lives</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why is fentanyl especially dangerous compared to other opioids?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Inhalants, Club Drugs &amp; Prevention</h3>\\r\\n              <p>Some of the most dangerous substances are legal products misused for their psychoactive effects. Inhalants are particularly common among younger teens due to easy access.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Inhalants</strong><span>Huffing glue, paint, aerosols; can cause sudden death (SDS) even on first use</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>MDMA (Ecstasy)</strong><span>Damages serotonin neurons; causes dehydration, overheating, cardiac risk</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Ketamine/GHB</strong><span>Dissociative drugs; used as date rape drugs; dangerous combinations with alcohol</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Prevention</strong><span>Education, strong family bonds, healthy coping, refusal skills, community programs</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What makes inhalants especially dangerous compared to other drugs?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>THC</strong><span>Tetrahydrocannabinol — the psychoactive compound in marijuana that produces its effects.</span></div>\\r\\n                <div><strong>Dopamine</strong><span>A neurotransmitter in the brain\'s reward system; many addictive drugs trigger massive dopamine release.</span></div>\\r\\n                <div><strong>Methamphetamine</strong><span>A highly addictive stimulant that causes intense euphoria followed by severe physical and mental damage.</span></div>\\r\\n                <div><strong>Opioid</strong><span>A class of drugs — including heroin, morphine, and fentanyl — that bind to pain receptors and cause euphoria.</span></div>\\r\\n                <div><strong>Fentanyl</strong><span>A synthetic opioid 50x stronger than heroin; now the leading cause of overdose deaths in the U.S.</span></div>\\r\\n                <div><strong>Naloxone</strong><span>A medication that rapidly reverses opioid overdose; available as Narcan nasal spray.</span></div>\\r\\n                <div><strong>Inhalants</strong><span>Volatile substances inhaled to produce psychoactive effects; can cause sudden death on first use.</span></div>\\r\\n                <div><strong>MDMA</strong><span>3,4-methylenedioxymethamphetamine (Ecstasy/Molly) — a stimulant/hallucinogen that damages serotonin neurons.</span></div>\\r\\n                <div><strong>Anhedonia</strong><span>The inability to feel pleasure from normally enjoyable activities, often caused by drug-induced receptor damage.</span></div>\\r\\n                <div><strong>Gateway drug</strong><span>A substance (like alcohol or marijuana) whose early use is associated with higher likelihood of using harder drugs later.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=22","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 22 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=22#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=22#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 22 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=22#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=22","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 22 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"Fentanyl Crisis Data Analysis","desc":"Using current CDC and DEA data, map the fentanyl crisis: how it entered the illegal drug supply, why it\'s now in counterfeit pills of every kind, and why it\'s the #1 cause of death for Americans ages 18–45.","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🔍","title":"Addiction Treatment in the News","desc":"Find a current news story on drug rehabilitation, harm reduction, or addiction recovery. What approach is being used? What does the research say about its effectiveness? What barriers prevent people from accessing treatment?","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Risk & Protective Factor Reflection","desc":"Using addiction research, identify the biological, psychological, and social risk factors and protective factors in your own life. Be specific and honest. Write a reflection on what you can actively control.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_corner.html","icon":"👑","title":"Sprite Dodge","desc":"Out-dodge King Junk for 60 seconds"},{"href":"/dopp_breakout.html","icon":"🧱","title":"Habit Breaker","desc":"Smash a wall of bad habits"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":23,"realmTag":"Realm VIII — Disease Fortress","title":"Communicable Diseases","sub":"COVID-19 infected over 700 million people worldwide. The flu kills up to 52,000 Americans in a single year. Understanding how pathogens spread, how your immune system fights back, and how vaccines work is essential health knowledge in the modern world.","meta":[{"icon":"📅","label":"Days","value":"42–45"},{"icon":"📖","label":"Lessons","value":"4"},{"icon":"🏆","label":"Badge","value":"Health Guardian"}],"lessons":["L1: Understanding Communicable Diseases","L2: Common Diseases","L3: Fighting Communicable Diseases","L4: Emerging Diseases"],"pdf":"/Chapter_23_Communicable_Diseases.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — How Diseases Spread</h3>\\r\\n              <p>A communicable disease is any illness that can be transmitted from person to person, animal to person, or environment to person. Understanding transmission is key to prevention.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Direct Contact</strong><span>Touching, kissing, sexual contact — pathogen transfers person-to-person</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Droplets</strong><span>Coughing/sneezing sends infected droplets into the air (flu, COVID-19)</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Contaminated Surfaces</strong><span>Fomites — doorknobs, phones — harbor pathogens that transfer via touch</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Vectors</strong><span>Animals/insects (mosquitoes, ticks) transmit pathogens between hosts</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the difference between direct and indirect disease transmission?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — The Immune System</h3>\\r\\n              <p>The immune system is the body\'s defense against pathogens. It has two layers: innate immunity (rapid, non-specific) and adaptive immunity (slower, highly specific).</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Antibodies &amp; Memory Cells</strong><br>\\r\\n                When the adaptive immune system encounters a pathogen, B cells produce antibodies that neutralize it. Memory cells remain after the infection clears — allowing faster, stronger responses if the same pathogen returns. This is the basis of vaccination.\\r\\n              </div>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>White blood cells (leukocytes) are the primary immune fighters</li>\\r\\n                <li>Fever is an immune response — high temperature inhibits pathogen growth</li>\\r\\n                <li>Inflammation directs immune cells to the site of infection</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> How do memory cells protect you from getting the same illness twice?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Common Communicable Diseases</h3>\\r\\n              <p>Several communicable diseases affect teens frequently. Knowing symptoms and treatment helps manage illness and prevent spread.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Influenza</strong><span>Viral; spreads by droplets; sudden fever, aches, cough; annual vaccine recommended</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Common Cold</strong><span>Rhinovirus; spreads by contact; runny nose, sore throat; no cure — rest and fluids</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Strep Throat</strong><span>Bacterial (Group A Strep); treated with antibiotics; can lead to rheumatic fever if untreated</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Mononucleosis</strong><span>Epstein-Barr virus; spread by saliva (\\"kissing disease\\"); extreme fatigue, swollen glands</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why can\'t antibiotics treat influenza or the common cold?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Prevention &amp; Public Health</h3>\\r\\n              <p>Most communicable diseases can be prevented through individual behaviors and public health measures that protect communities.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Wash hands thoroughly — 20+ seconds with soap and water; most effective prevention</li>\\r\\n                <li>Vaccinate — \\"herd immunity\\" protects those who can\'t be vaccinated</li>\\r\\n                <li>Stay home when sick — prevents spreading illness to classmates and coworkers</li>\\r\\n                <li>Cover coughs and sneezes — use elbow, not hand</li>\\r\\n                <li>Clean and disinfect high-touch surfaces regularly</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is herd immunity, and why does it matter?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Communicable disease</strong><span>An illness that can be transmitted from one person to another.</span></div>\\r\\n                <div><strong>Pathogen</strong><span>A microorganism (virus, bacteria, fungus, parasite) that causes disease.</span></div>\\r\\n                <div><strong>Virus</strong><span>A non-living pathogen that replicates inside host cells; not treatable with antibiotics.</span></div>\\r\\n                <div><strong>Bacteria</strong><span>Single-celled living organisms; many are harmless; some cause disease and can be treated with antibiotics.</span></div>\\r\\n                <div><strong>Immune system</strong><span>The body\'s defense network of organs, cells, and proteins that fight pathogens.</span></div>\\r\\n                <div><strong>Antibody</strong><span>A protein produced by the immune system that neutralizes a specific pathogen.</span></div>\\r\\n                <div><strong>Vaccine</strong><span>A preparation that stimulates immunity against a specific disease without causing the disease itself.</span></div>\\r\\n                <div><strong>Herd immunity</strong><span>When enough of a population is immune to a disease that it stops spreading, protecting even unvaccinated individuals.</span></div>\\r\\n                <div><strong>Incubation period</strong><span>The time between exposure to a pathogen and the appearance of symptoms.</span></div>\\r\\n                <div><strong>Vector</strong><span>An organism (like a mosquito or tick) that transmits a pathogen from one host to another.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=23","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 23 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=23#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=23#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 23 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=23#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=23","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 23 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🦠","title":"Side Quest — Disease Profile","desc":"Choose one communicable disease — influenza, tuberculosis, COVID-19, measles, or mono — and create a complete disease profile: pathogen type, transmission routes, symptoms, complications, treatment, and prevention. Use CDC as your primary source.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📰","title":"Exploration — Outbreak Response Analysis","desc":"Find a current news story about an infectious disease outbreak or public health response anywhere in the world. What containment strategies were used? Were they effective? What would you do differently as the public health director?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🧼","title":"Challenge — Personal Prevention Audit","desc":"Audit your disease prevention habits for one week: handwashing frequency, vaccination status, staying home when sick, and touching your face. Where are your gaps? Write a personal prevention plan with three specific, actionable improvements.","tags":[{"text":"Solo","kind":""},{"text":"~15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_invaders.html","icon":"🦠","title":"Germ Invaders","desc":"Spray germs and stress clouds"},{"href":"/dopp_pacman.html","icon":"🍎","title":"Sprite Maze","desc":"Collect water, dodge junk monsters"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":24,"realmTag":"Realm VIII — Disease Fortress","title":"STIs & HIV/AIDS","sub":"1 in 5 Americans has an STI — and most don\'t know it. STIs are among the most common infectious diseases in the U.S., yet they remain among the least discussed. This chapter cuts through the stigma with real data, honest prevention strategies, and the health literacy every teen needs.","meta":[{"icon":"📅","label":"Days","value":"44–47"},{"icon":"📖","label":"Lessons","value":"4"},{"icon":"🏆","label":"Badge","value":"Health Guardian"}],"lessons":["L1: Sexually Transmitted Infections","L2: Preventing STIs","L3: HIV/AIDS","L4: Preventing HIV"],"pdf":"/Chapter_24_STIs_and_HIV_AIDS.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Understanding STIs</h3>\\r\\n              <p>Sexually transmitted infections (STIs) are infections passed from person to person primarily through sexual contact. They are among the most common infectious diseases globally, with young people ages 15–24 accounting for nearly half of new U.S. cases.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Bacterial STIs</strong><span>Chlamydia, gonorrhea, syphilis — curable with antibiotics if caught early</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Viral STIs</strong><span>HIV, herpes, HPV, hepatitis B — no cure, but manageable with treatment</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Parasitic STIs</strong><span>Pubic lice, trichomoniasis — treatable</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Asymptomatic</strong><span>Many STIs have no symptoms — infected people can spread them unknowingly</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Testing Matters</strong><br>\\r\\n                Most STIs are asymptomatic. The only way to know your status is to get tested. The CDC recommends annual STI screening for sexually active individuals under 25.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Why can someone have an STI and not know it?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — HIV and AIDS</h3>\\r\\n              <p>HIV (Human Immunodeficiency Virus) attacks CD4+ T-cells — the commanders of the immune system. Without treatment, HIV progresses to AIDS (Acquired Immunodeficiency Syndrome), when the immune system can no longer fight infections.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Modern HIV Treatment</strong><br>\\r\\n                Antiretroviral therapy (ART) suppresses HIV to undetectable levels. People with undetectable HIV cannot transmit the virus sexually (U=U: Undetectable = Untransmittable). HIV is now a manageable chronic condition, not a death sentence.\\r\\n              </div>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>HIV is transmitted through blood, breast milk, semen, and vaginal fluids</li>\\r\\n                <li>HIV is NOT spread through casual contact: hugging, sharing food, toilet seats</li>\\r\\n                <li>PrEP (pre-exposure prophylaxis) is a daily medication that prevents HIV</li>\\r\\n                <li>Needle exchange programs reduce HIV transmission among drug users</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What does U=U mean in the context of HIV treatment?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Prevention Strategies</h3>\\r\\n              <p>Prevention is the most effective approach to STIs. A combination of behavioral and biomedical strategies provides the strongest protection.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Abstinence</strong><span>100% effective when practiced consistently — the only method that completely eliminates risk</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Condoms</strong><span>85–95% effective against STIs when used correctly and consistently</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Vaccination</strong><span>HPV and hepatitis B vaccines prevent specific viral STIs</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Regular Testing</strong><span>Knowing your status enables timely treatment and prevents unknowing transmission</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Name three prevention strategies for STIs and explain how each works.</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Reducing Stigma &amp; Getting Help</h3>\\r\\n              <p>STI stigma prevents people from getting tested, treated, and disclosing their status to partners — making the public health problem worse. Accurate information is the antidote to stigma.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>STIs are medical conditions, not moral judgments — anyone who is sexually active can get one</li>\\r\\n                <li>Early treatment prevents complications (infertility, cancer, organ damage)</li>\\r\\n                <li>Partner notification is an ethical responsibility — many health departments offer anonymous notification</li>\\r\\n                <li>Planned Parenthood and local health clinics offer confidential, low-cost testing</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> How does stigma make the STI epidemic worse?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>STI</strong><span>Sexually Transmitted Infection — an infection passed primarily through sexual contact.</span></div>\\r\\n                <div><strong>HIV</strong><span>Human Immunodeficiency Virus — the virus that attacks the immune system and can lead to AIDS.</span></div>\\r\\n                <div><strong>AIDS</strong><span>Acquired Immunodeficiency Syndrome — the late stage of HIV when the immune system is severely compromised.</span></div>\\r\\n                <div><strong>Antiretroviral therapy</strong><span>Medication that suppresses HIV to undetectable levels, preventing disease progression and transmission.</span></div>\\r\\n                <div><strong>Chlamydia</strong><span>The most common bacterial STI; often asymptomatic; curable with antibiotics.</span></div>\\r\\n                <div><strong>HPV</strong><span>Human Papillomavirus — the most common STI; some strains cause genital warts or cancer; preventable by vaccine.</span></div>\\r\\n                <div><strong>Abstinence</strong><span>Refraining from sexual activity; the only 100% effective method to prevent STIs and pregnancy.</span></div>\\r\\n                <div><strong>PrEP</strong><span>Pre-Exposure Prophylaxis — a daily medication that prevents HIV in high-risk individuals.</span></div>\\r\\n                <div><strong>Asymptomatic</strong><span>Having an infection without noticeable symptoms.</span></div>\\r\\n                <div><strong>U=U</strong><span>Undetectable = Untransmittable — a person on effective ART with undetectable HIV cannot sexually transmit the virus.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=24","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 24 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=24#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=24#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 24 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=24#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=24","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 24 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🔬","title":"Side Quest — STI Fact Sheet","desc":"Using CDC data, research the most common STI among teens in the U.S. Cover: transmission routes, symptoms (or lack of them), testing recommendations, treatment options, and prevention. Create a fact sheet that is accurate, non-judgmental, and teen-appropriate.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📰","title":"Exploration — Prevention Programs in the News","desc":"Find a news story about HIV/AIDS prevention, PrEP access, or STI testing initiatives targeting young people. What is the public health approach? What does the data say about its effectiveness? What gaps still exist?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"💬","title":"Challenge — Breaking the Silence","desc":"Reflect on what makes it difficult for teens to discuss sexual health with parents, doctors, or partners. What communication and refusal skills from Chapters 2 and 6 apply here? Write a specific script for one of these conversations.","tags":[{"text":"Solo","kind":""},{"text":"~15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_invaders.html","icon":"🦠","title":"Germ Invaders","desc":"Spray germs and stress clouds"},{"href":"/dopp_wordle.html","icon":"🔤","title":"Word Quest","desc":"Guess the 5-letter health word"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":25,"realmTag":"Realm VIII — Disease Fortress","title":"Noncommunicable Diseases & Disabilities","sub":"Heart disease, cancer, diabetes, and stroke cause nearly 75% of all deaths in the U.S. — and the lifestyle choices you make as a teenager are directly building or reducing your risk. This chapter shows how noncommunicable diseases develop and, more importantly, how to prevent them.","meta":[{"icon":"📅","label":"Days","value":"46–49"},{"icon":"📖","label":"Lessons","value":"4"},{"icon":"🏆","label":"Badge","value":"Health Guardian"}],"lessons":["L1: Cardiovascular Disease","L2: Cancer","L3: Allergies, Asthma, Diabetes","L4: Disabilities"],"pdf":"/Chapter_25_Noncommunicable_Diseases_and_Disabilities.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Heart Disease &amp; Stroke</h3>\\r\\n              <p>Cardiovascular disease (CVD) is the #1 cause of death in the United States. Atherosclerosis — the buildup of plaque in artery walls — is the underlying cause of most heart attacks and strokes.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Heart Attack</strong><span>Coronary artery blocked; heart muscle dies without oxygen; symptoms: chest pain, arm pain, shortness of breath</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Stroke</strong><span>Brain artery blocked or burst; brain cells die; FAST: Face drooping, Arm weakness, Speech difficulty, Time to call 911</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Risk Factors</strong><span>Hypertension, high cholesterol, diabetes, obesity, smoking, physical inactivity, family history</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Prevention</strong><span>Exercise, healthy diet, no smoking, managing blood pressure and cholesterol</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What does FAST stand for, and when do you use it?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Cancer</h3>\\r\\n              <p>Cancer is the uncontrolled division of abnormal cells. The over 100 types of cancer vary widely in cause, treatment, and prognosis. It\'s the second leading cause of death in the U.S.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Cancer Prevention</strong><br>\\r\\n                Up to 42% of cancers are preventable. Don\'t smoke, limit alcohol, maintain healthy weight, use sunscreen, get vaccinated (HPV, Hep B), eat vegetables/fiber, and get regular cancer screenings.\\r\\n              </div>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Carcinogens (tobacco, UV radiation, some chemicals) trigger DNA mutations</li>\\r\\n                <li>Early detection dramatically improves survival rates</li>\\r\\n                <li>Treatments: surgery, chemotherapy, radiation, immunotherapy, targeted therapy</li>\\r\\n                <li>Benign tumors are non-cancerous; malignant tumors can invade other tissues</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the difference between a benign and malignant tumor?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Diabetes</h3>\\r\\n              <p>Diabetes is a chronic disease where the body cannot properly regulate blood sugar (glucose). It affects 37 million Americans and is a growing epidemic linked to obesity and inactivity.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Type 1</strong><span>Autoimmune — immune system destroys insulin-producing beta cells; requires insulin injections; not preventable</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Type 2</strong><span>Cells become resistant to insulin; often linked to obesity/inactivity; largely preventable and reversible</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Prediabetes</strong><span>Blood sugar higher than normal but below diabetic threshold; wake-up call to change lifestyle</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Complications</strong><span>Blindness, kidney failure, nerve damage, cardiovascular disease if unmanaged</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the key difference between Type 1 and Type 2 diabetes?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Disabilities &amp; Chronic Conditions</h3>\\r\\n              <p>A disability is any physical, mental, or developmental condition that limits one or more major life activities. Disabilities can be congenital (present at birth) or acquired, visible or invisible.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>People-first language: \\"person with a disability\\" — not \\"disabled person\\" or \\"wheelchair-bound\\"</li>\\r\\n                <li>ADA (Americans with Disabilities Act) protects equal access in schools, jobs, and public spaces</li>\\r\\n                <li>Assistive technology (wheelchairs, hearing aids, screen readers) increases independence</li>\\r\\n                <li>Chronic conditions (asthma, epilepsy, arthritis) are managed, not cured</li>\\r\\n                <li>Supporting peers with disabilities means including, not pitying</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is people-first language, and why does it matter?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Noncommunicable disease</strong><span>A disease that cannot be passed from person to person; caused by lifestyle, genetics, or environment.</span></div>\\r\\n                <div><strong>Atherosclerosis</strong><span>The buildup of fatty plaques inside artery walls, narrowing blood flow and increasing heart attack risk.</span></div>\\r\\n                <div><strong>Hypertension</strong><span>Persistently high blood pressure; a major risk factor for heart attack and stroke.</span></div>\\r\\n                <div><strong>Cancer</strong><span>A disease of uncontrolled cell division that can invade and spread to other parts of the body.</span></div>\\r\\n                <div><strong>Malignant</strong><span>Describes a tumor that is cancerous and has the potential to invade other tissues.</span></div>\\r\\n                <div><strong>Metastasis</strong><span>The spread of cancer cells from the original tumor to other parts of the body.</span></div>\\r\\n                <div><strong>Diabetes</strong><span>A chronic disease in which the body cannot properly regulate blood sugar levels.</span></div>\\r\\n                <div><strong>Insulin</strong><span>The hormone that allows cells to absorb glucose from the bloodstream for energy.</span></div>\\r\\n                <div><strong>Disability</strong><span>A physical, mental, or developmental condition that limits one or more major life activities.</span></div>\\r\\n                <div><strong>ADA</strong><span>Americans with Disabilities Act — federal law protecting equal access and rights for people with disabilities.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=25","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 25 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=25#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=25#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 25 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=25#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=25","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 25 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🧬","title":"Side Quest — Family Health History","desc":"Research your family health history for noncommunicable diseases: heart disease, diabetes, cancer, hypertension, or stroke. For each condition you find, identify which risk factors are genetic vs. lifestyle-related. Create a personal risk assessment.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📰","title":"Exploration — New Research on Prevention","desc":"Find a current news story about cancer prevention, Type 2 diabetes in young people, or cardiovascular disease research. What are scientists learning? What does it mean specifically for teens and young adults?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Challenge — Risk Factor Analysis","desc":"Honestly evaluate your current lifestyle for the top modifiable risk factors: diet quality, physical activity, sleep, stress levels, and substance use. Identify your top two risk factors and create a realistic 30-day plan to address them.","tags":[{"text":"Solo","kind":""},{"text":"~15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_2048.html","icon":"🔢","title":"Snack 2048","desc":"Merge snacks up to the Healthy Heart"},{"href":"/sprite_dash.html","icon":"🏃","title":"Sprite Dash","desc":"Jump and duck past junk food"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":26,"realmTag":"Realm IX — The Final Tower","title":"Safety & Injury Prevention","sub":"Accidents are the #1 cause of death for Americans ages 1–44. Most of them are preventable. From distracted driving to online dangers, from home hazards to weather emergencies, this chapter gives you the awareness and skills to protect yourself and the people around you.","meta":[{"icon":"📅","label":"Days","value":"50–51"},{"icon":"📖","label":"Lessons","value":"4"},{"icon":"🏆","label":"Badge","value":"★ Master of Wellness"}],"lessons":["L1: Personal Safety","L2: Home and Community Safety","L3: Outdoor Safety","L4: Road Safety"],"pdf":"/Chapter_26_Safety_and_Injury_Prevention.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Motor Vehicle Safety</h3>\\r\\n              <p>Motor vehicle crashes are the second leading cause of death for American teens, after firearm injuries. Most are preventable through responsible behaviors behind the wheel and as passengers.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Distracted Driving</strong><span>Texting takes eyes off road for 5 seconds — at 55 mph, that\'s a football field blind</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Seat Belts</strong><span>Reduce crash death risk by 45% for front seat, 60% for rear seat passengers</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Impaired Driving</strong><span>Alcohol, marijuana, prescription drugs, and sleep deprivation all impair driving</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Passenger Risk</strong><span>Teen drivers crash more with teen passengers; every additional passenger doubles crash risk</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Name two behaviors that increase teen crash risk and one way to prevent each.</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Home &amp; Environmental Safety</h3>\\r\\n              <p>Most accidents happen in the home — particularly to young children and older adults. Awareness and simple precautions prevent most home injuries.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Top Home Hazards</strong><br>\\r\\n                Falls (leading cause of injury death for 65+), poisoning (leading cause for ages 25–64, mostly overdose), fire/burns, drowning, and firearms. Most are preventable with education and planning.\\r\\n              </div>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Install smoke detectors on every floor; test monthly; replace batteries yearly</li>\\r\\n                <li>Store medications locked away from children</li>\\r\\n                <li>Never leave young children unsupervised near water</li>\\r\\n                <li>Use non-slip mats in bathtubs and secure loose rugs</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is the leading cause of injury death for older adults, and how can it be prevented?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Sports &amp; Recreation Safety</h3>\\r\\n              <p>Physical activity is essential for health, but sports injuries are the leading cause of ER visits for teens. Proper preparation and equipment dramatically reduce risk.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Warm up properly — cold muscles tear more easily</li>\\r\\n                <li>Wear appropriate protective gear for your sport (helmets, pads, eye protection)</li>\\r\\n                <li>Follow rules — many are specifically designed to prevent injury</li>\\r\\n                <li>Recognize concussion signs: headache, confusion, dizziness, memory problems</li>\\r\\n                <li>Never return to play after a suspected concussion — second impact syndrome can be fatal</li>\\r\\n                <li>Stay hydrated — heat illness is preventable</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What is second impact syndrome, and why is it dangerous?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Workplace &amp; Weather Safety</h3>\\r\\n              <p>Teens in the workforce face real safety risks — particularly in food service, construction, and agriculture. Natural disasters and severe weather require preparedness.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Workplace Rights</strong><span>OSHA requires safe working conditions; teens under 18 have extra protections on hours and hazardous tasks</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Heat Illness</strong><span>Heat exhaustion → heat stroke; cool and hydrate immediately; heat stroke is life-threatening</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Lightning Safety</strong><span>Seek indoor shelter; avoid tall trees and open fields; wait 30 min after last thunder</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Emergency Kits</strong><span>72-hour supply: water (1 gal/person/day), food, medications, flashlight, first aid</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What supplies should be in a 72-hour emergency kit?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Accident</strong><span>An unintended event that results in injury, damage, or harm.</span></div>\\r\\n                <div><strong>Distracted driving</strong><span>Operating a vehicle while attention is diverted to another activity, such as texting.</span></div>\\r\\n                <div><strong>Concussion</strong><span>A mild traumatic brain injury caused by a blow or jolt to the head that temporarily disrupts brain function.</span></div>\\r\\n                <div><strong>Second impact syndrome</strong><span>A rare but often fatal condition where a second concussion occurs before the first has healed.</span></div>\\r\\n                <div><strong>Heat exhaustion</strong><span>A heat-related illness caused by overheating, involving heavy sweating, weakness, and dizziness.</span></div>\\r\\n                <div><strong>Heat stroke</strong><span>A life-threatening condition where body temperature exceeds 104°F; requires immediate emergency care.</span></div>\\r\\n                <div><strong>OSHA</strong><span>Occupational Safety and Health Administration — the federal agency that regulates workplace safety.</span></div>\\r\\n                <div><strong>Fire escape plan</strong><span>A prepared strategy for evacuating a building safely during a fire, practiced regularly by household members.</span></div>\\r\\n                <div><strong>Passive safety</strong><span>Safety measures that protect automatically without requiring action (e.g., airbags, smoke alarms).</span></div>\\r\\n                <div><strong>Active safety</strong><span>Safety measures that require deliberate human action (e.g., wearing a seat belt, using a helmet).</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=26","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 26 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=26#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=26#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 26 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=26#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=26","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 26 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🚗","title":"Side Quest — Teen Driving Safety Research","desc":"Research teen motor vehicle accident statistics in your state. What are the leading causes — distracted driving, speeding, impaired driving, or passenger distractions? What laws exist, and are they working? Present your findings with data.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📰","title":"Exploration — Safety Issue in the News","desc":"Find a current news story about a safety issue affecting teens: dangerous social media challenges, recreational accidents, pedestrian safety, or cyberbullying. What should schools or communities do differently based on the evidence?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🔍","title":"Challenge — Safety Hazard Audit","desc":"Walk through your home or school and identify five specific safety hazards. For each one, describe the type of risk (fire, fall, electrical, etc.) and write a specific, realistic solution. Share your safety audit findings with your family.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_motomania.html","icon":"🏍️","title":"Sprite Rider","desc":"Hills, ramps and safe landings"},{"href":"/sprite_sling.html","icon":"🎯","title":"Sprite Slingshot","desc":"Topple towers of junk-food monsters"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":27,"realmTag":"Realm IX — The Final Tower","title":"First Aid & Emergencies","sub":"Every 40 seconds, someone in the U.S. has a heart attack. 70% of out-of-hospital cardiac arrests happen at home. Knowing CPR, how to stop severe bleeding, how to recognize a stroke, and how to respond to an overdose are skills that could save someone\'s life — possibly someone you love.","meta":[{"icon":"📅","label":"Days","value":"52–53"},{"icon":"📖","label":"Lessons","value":"4"},{"icon":"🏆","label":"Badge","value":"★ Master of Wellness"}],"lessons":["L1: Providing First Aid","L2: CPR and Shock","L3: Common Emergencies","L4: Emergency Preparedness"],"pdf":"/Chapter_27_First_Aid_and_Emergencies.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — First Aid Basics</h3>\\r\\n              <p>First aid is immediate, temporary care given to a person who is injured or suddenly ill before professional medical help arrives. Basic skills can save lives — every person should learn them.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Check-Call-Care</strong><br>\\r\\n                The first aid action sequence: (1) <strong>Check</strong> the scene for safety; (2) <strong>Call</strong> 911 for serious emergencies; (3) <strong>Care</strong> for the person with the skills you have.\\r\\n              </div>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Controlling Bleeding</strong><span>Apply direct pressure with a clean cloth; elevate the limb; don\'t remove cloth; add more if needed</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Burns</strong><span>Cool with running water for 10–20 min; cover loosely; don\'t use ice or butter; seek care for serious burns</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Choking</strong><span>5 back blows then 5 abdominal thrusts (Heimlich maneuver); call 911 if can\'t clear</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Shock</strong><span>Lay person flat; raise legs; keep warm; don\'t give fluids; call 911</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What does Check-Call-Care mean in a first aid emergency?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — CPR &amp; AED</h3>\\r\\n              <p>CPR (Cardiopulmonary Resuscitation) keeps blood flowing when the heart stops. Combined with an AED (Automated External Defibrillator), survival rates for cardiac arrest double or triple.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Call 911 first, or have someone else call while you begin CPR</li>\\r\\n                <li>Compression-only CPR for adults: 100–120 compressions/min, 2\\" deep</li>\\r\\n                <li>Full CPR includes 30 compressions + 2 rescue breaths</li>\\r\\n                <li>AED will analyze rhythm and deliver shock if needed — voice-guided, safe to use</li>\\r\\n                <li>Continue CPR until help arrives or the person regains consciousness</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>CPR for Teens</strong><br>\\r\\n                For children (1-puberty): same process but use 1 hand for compressions (or 2 fingers for infants). Push down ~2\\" on children, ~1.5\\" on infants.\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What are the compression rate and depth for adult CPR?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Common Medical Emergencies</h3>\\r\\n              <p>Recognizing emergencies quickly and knowing initial actions can prevent permanent injury or death while waiting for EMS.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Heart Attack</strong><span>Chest pain/pressure, arm pain, shortness of breath, nausea — call 911, chew aspirin if not allergic</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Stroke</strong><span>FAST: Face drooping, Arm weakness, Speech difficulty, Time to call 911</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Diabetic Emergency</strong><span>Hypoglycemia: give sugar (juice, candy) if conscious; hyperglycemia: needs insulin, call 911</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Allergic Reaction</strong><span>Mild: antihistamine; severe (anaphylaxis): epinephrine auto-injector (EpiPen), call 911</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What should you do if you suspect someone is having a stroke?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Natural Disasters &amp; Emergency Preparedness</h3>\\r\\n              <p>Emergency preparedness means planning, practicing, and equipping before disaster strikes — when it\'s too late to figure it out.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Build a 72-hour kit: water (1 gal/person/day), non-perishable food, medications, flashlight, first aid kit, copies of documents</li>\\r\\n                <li>Know your family\'s evacuation routes and meeting point</li>\\r\\n                <li>Tornado: go to lowest floor, interior room away from windows</li>\\r\\n                <li>Earthquake: Drop, Cover, Hold On — under a sturdy table or against an interior wall</li>\\r\\n                <li>Flood: never walk or drive through floodwater; 6\\" can knock you down</li>\\r\\n                <li>Sign up for local emergency alerts (Wireless Emergency Alerts system)</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What are the three actions for an earthquake emergency?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>First aid</strong><span>Immediate, temporary care given to a sick or injured person before professional help arrives.</span></div>\\r\\n                <div><strong>CPR</strong><span>Cardiopulmonary Resuscitation — chest compressions and rescue breaths that maintain circulation during cardiac arrest.</span></div>\\r\\n                <div><strong>AED</strong><span>Automated External Defibrillator — a device that delivers an electric shock to restore normal heart rhythm.</span></div>\\r\\n                <div><strong>Heimlich maneuver</strong><span>An abdominal thrust technique used to dislodge a foreign object from a choking person\'s airway.</span></div>\\r\\n                <div><strong>Shock</strong><span>A life-threatening condition where blood flow is inadequate to meet the body\'s needs.</span></div>\\r\\n                <div><strong>Anaphylaxis</strong><span>A severe, potentially fatal allergic reaction requiring immediate epinephrine treatment.</span></div>\\r\\n                <div><strong>Triage</strong><span>The process of sorting injured people by severity to prioritize treatment.</span></div>\\r\\n                <div><strong>Tourniquet</strong><span>A tight band applied to a limb to stop severe bleeding when direct pressure fails.</span></div>\\r\\n                <div><strong>Hypothermia</strong><span>Dangerously low body temperature caused by exposure to cold; requires gradual rewarming.</span></div>\\r\\n                <div><strong>Recovery position</strong><span>A side-lying position used for unconscious breathing persons to keep the airway open.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=27","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 27 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=27#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=27#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 27 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=27#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=27","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 27 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"🫀","title":"Side Quest — CPR & AED Training","desc":"Learn the steps for Hands-Only CPR using American Heart Association guidelines. Practice the compression rate (100–120 per minute) with a pillow. Write a step-by-step guide clear enough that you could teach it to a family member from memory.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0288db42408191a246e22257b95ec4-low-side-quest-guide"},{"icon":"📰","title":"Exploration — Bystander Saves a Life","desc":"Find a news story about a bystander who saved someone\'s life using CPR, the Heimlich maneuver, naloxone, or another first aid skill. What did they do? What training had they received? What can schools do to produce more prepared bystanders?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🏠","title":"Challenge — Family Emergency Plan","desc":"Create a complete family emergency plan: nearest hospital address, emergency contact list, first aid kit location and contents check, and a designated meeting point outside your home. Present the plan to at least one family member this week.","tags":[{"text":"Solo","kind":""},{"text":"~20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/habit_showdown.html","icon":"⚖️","title":"Habit Showdown","desc":"Good habit or bad? Myth or fact?"},{"href":"/dopp_wordle.html","icon":"🔤","title":"Word Quest","desc":"Guess the 5-letter health word"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]},{"n":28,"realmTag":"Realm IX — The Final Tower","title":"Community & Environmental Health","sub":"Everything connects. Your personal health exists within a community and environment that shapes it. This final chapter zooms out to see the big picture — and your role in making it better.","meta":[{"icon":"📅","label":"Days","value":"54–55"},{"icon":"📖","label":"Lessons","value":"3"},{"icon":"🏆","label":"Badge","value":"★ Master of Wellness"}],"lessons":["L1: The Health Care System","L2: Air Quality","L3: Protecting Land and Water"],"pdf":"/Chapter_28_Community_and_Environmental_Health.pdf","readerHtml":"<section class=\\"reader-section\\">\\r\\n              <h3>Lesson 1 — Community Health</h3>\\r\\n              <p>Community health refers to the physical, mental, and social well-being of a defined group of people. It goes beyond individual health — the zip code you grow up in predicts health outcomes as much as your genetic code.</p>\\r\\n              <div class=\\"reading-callout\\">\\r\\n                <strong>Social Determinants of Health</strong><br>\\r\\n                The non-medical factors that influence health: income, education, housing, employment, food access, transportation, and social support. Addressing these \\"upstream\\" factors prevents disease more effectively than treatment alone.\\r\\n              </div>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Public Health</strong><span>The science of protecting and improving the health of communities through education, policy, and research</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Health Disparities</strong><span>Preventable differences in disease burden between groups due to social, economic, and environmental factors</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Community Resources</strong><span>Health departments, clinics, food banks, shelters — local systems that support community health</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Advocacy</strong><span>Working to change policies, systems, and environments that affect community health</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> What are social determinants of health, and why do they matter?</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 2 — Air &amp; Water Quality</h3>\\r\\n              <p>Clean air and safe water are fundamental public health needs. Pollution affects respiratory health, cardiovascular health, and cognitive development — especially in children.</p>\\r\\n              <ul class=\\"reader-list\\">\\r\\n                <li>Indoor air pollutants: radon, carbon monoxide, mold, tobacco smoke, VOCs</li>\\r\\n                <li>Outdoor air: smog (ozone + particulate matter) worsens asthma and heart disease</li>\\r\\n                <li>Clean Water Act (1972) regulates discharge of pollutants into U.S. waterways</li>\\r\\n                <li>Lead in water (e.g., Flint, MI) causes permanent neurological damage — especially in children</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Name two indoor and two outdoor air pollutants that affect health.</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 3 — Climate Change &amp; Health</h3>\\r\\n              <p>Climate change is recognized by every major medical organization as the greatest health threat of the 21st century. Its effects are already measurable and accelerating.</p>\\r\\n              <div class=\\"reading-grid\\">\\r\\n                <div class=\\"reading-tile\\"><strong>Heat</strong><span>Record heat waves cause heat stroke and cardiovascular stress; urban areas hit hardest</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Extreme Weather</strong><span>Stronger hurricanes, floods, wildfires displace communities and contaminate water supplies</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Vector Expansion</strong><span>Warmer temperatures expand mosquito/tick ranges — spreading Lyme, Zika, dengue</span></div>\\r\\n                <div class=\\"reading-tile\\"><strong>Mental Health</strong><span>Eco-anxiety and climate grief are real; disaster trauma causes PTSD</span></div>\\r\\n              </div>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Name two ways climate change directly affects human health.</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section\\">\\r\\n              <h3>Lesson 4 — Being a Health Advocate</h3>\\r\\n              <p>You don\'t need to be a politician to make a difference. Health advocacy starts locally — in your school, neighborhood, and community — and builds from there.</p>\\r\\n              <ul class=\\"reader-checklist\\">\\r\\n                <li>Vote and engage with local government — zoning, parks, food access, and transit decisions affect health</li>\\r\\n                <li>Reduce personal carbon footprint: plant-based meals, public transit, energy efficiency</li>\\r\\n                <li>Support community health organizations and volunteer</li>\\r\\n                <li>Use your voice — write letters, attend school board meetings, start or join clubs</li>\\r\\n                <li>Share accurate health information — counter misinformation in your networks</li>\\r\\n                <li>Champion health equity — advocate for under-resourced communities</li>\\r\\n              </ul>\\r\\n              <div class=\\"reading-check\\"><strong>Quick Check:</strong> Name two local actions a teenager can take to improve community health.</div>\\r\\n            </section>\\r\\n            <section class=\\"reader-section vocab-section\\">\\r\\n              <h3>Chapter Vocabulary</h3>\\r\\n              <div class=\\"vocab-table\\">\\r\\n                <div><strong>Community health</strong><span>The physical, mental, and social well-being of a defined group of people living in a shared environment.</span></div>\\r\\n                <div><strong>Public health</strong><span>The science of protecting and improving the health of populations through education, policy, and preventive measures.</span></div>\\r\\n                <div><strong>Social determinants of health</strong><span>Non-medical factors (income, education, housing) that significantly influence health outcomes.</span></div>\\r\\n                <div><strong>Health disparity</strong><span>A preventable difference in health outcomes between populations linked to social, economic, or environmental disadvantage.</span></div>\\r\\n                <div><strong>Environmental health</strong><span>The field studying how the natural and built environment affects human health.</span></div>\\r\\n                <div><strong>Air quality index</strong><span>A measure of how clean or polluted outdoor air is and what health effects may be of concern.</span></div>\\r\\n                <div><strong>Greenhouse gases</strong><span>Gases (CO₂, methane) that trap heat in the atmosphere, contributing to climate change.</span></div>\\r\\n                <div><strong>Health advocacy</strong><span>Actions taken to promote policies, systems, and conditions that improve health for individuals and communities.</span></div>\\r\\n                <div><strong>Health equity</strong><span>The state in which every person has a fair opportunity to be as healthy as possible.</span></div>\\r\\n                <div><strong>Sustainability</strong><span>Meeting present needs without compromising the ability of future generations to meet their own needs.</span></div>\\r\\n              </div>\\r\\n            </section>","vocabGames":[{"href":"/vocab_engine.html?ch=28","icon":"🃏","title":"Flashcard Flip","desc":"Tap to flip — term to definition. Study solo or quiz a partner.","count":"All Ch 28 terms","color":"#38BFFF"},{"href":"/vocab_engine.html?ch=28#speedquiz","icon":"⚡","title":"Speed Quiz","desc":"Timed multiple choice. Race the clock!","count":"30s per question","color":"#FF3B5C"},{"href":"/vocab_engine.html?ch=28#wordbuild","icon":"🔤","title":"Word Builder","desc":"Read the definition, type the term. Scrambled letter hints available.","count":"All Ch 28 terms","color":"#00E5A0"},{"href":"/vocab_engine.html?ch=28#conceptmap","icon":"🗺","title":"Concept Map","desc":"Drag and drop terms into the correct category.","count":"Grouped by topic","color":"#FFD700"},{"href":"/vocab_slice.html?ch=28","icon":"🥕","title":"Vocab Slice","desc":"Read the definition, then swipe the fruit with the matching term. Arcade style!","count":"All Ch 28 terms · earn medals","color":"#FF8C00"}],"activities":[{"icon":"📖","title":"Local Health Department Investigation","desc":"Research your county or city health department. What services do they provide? What are their top 3 stated public health priorities? How do they compare to national CDC priorities? What gap is most surprising?","tags":[{"text":"Team","kind":"team"},{"text":"20–25 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"🔍","title":"Environmental Health Issue in the News","desc":"Find a current news story on environmental health — air quality, water safety, lead exposure, or climate change impacts on health. Who is most affected? What\'s being done? What should be done?","tags":[{"text":"Solo","kind":""},{"text":"15–20 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a0287fb759c819196d149716a22bc4e-low-exploration-guide"},{"icon":"📊","title":"Community Health Action Plan","desc":"Identify one specific health problem in your school or community. Propose a realistic action plan: the problem, the population affected, 3 evidence-based interventions, and how you would measure success.","tags":[{"text":"Solo","kind":""},{"text":"10–15 min","kind":""},{"text":"🤖 AI Guide","kind":"ai-guide"}],"aiUrl":"https://chatgpt.com/g/g-6a02899217f88191ba9a805ab83f466e-low-challenge-coach"},{"icon":"👑","title":"Boss Battle","desc":"Chapter boss battle — tests all lesson content. Teams compete for realm badges.","tags":[{"text":"Boss Battle","kind":"boss"},{"text":"Full Class","kind":"team"},{"text":"~40 min","kind":""}],"aiUrl":null}],"related":[{"href":"/dopp_pacman.html","icon":"🍎","title":"Sprite Maze","desc":"Collect water, dodge junk monsters"},{"href":"/dopp_tetris.html","icon":"🟦","title":"Snack Stack","desc":"Stack healthy snacks, clear lines"},{"href":"/how_smart.html","icon":"🧠","title":"How Smart Am I?","desc":"Compare yourself, 3rd grade to grad school"}]}]')}]);